window.COMMON_BANK = window.COMMON_BANK || {};
window.COMMON_BANK["tech"] = window.COMMON_BANK["tech"] || {name:"科技常识", items:[]};
window.COMMON_BANK["tech"].items.push(
{"id": "tech-202", "q": "下列属于气体扩散现象的是：", "options": ["有麝自然香，何必当风立", "火场之旁，必有风生", "扇子有凉风，宜夏不宜冬", "月晕而风，础润而雨"], "a": 0, "e": ".【A】本题考查科技常识。气体扩散是指某种气体分子通过扩散运动而进入到其它气体里。A项正确，题干现象是因为麝能分泌麝香，并不需要站在风口，麝香分子就可以通过扩散运动到很远地方，使人闻得见香气。故体现了气体扩散现象。B项错误，题干现象是由于火场附近的空气受热膨胀，密度减小而上升，压强变小，周围冷空气填充，空气的流动就形成风。并未体现气体扩散现象。C项错误，题干现象是因为夏日气温较高，扇扇子，有利于空气的流动，从而加快了人体表面汗水的蒸发，蒸发要吸热，用扇子有制冷作用，所以扇子宜夏不宜冬。并未体现气体扩散现象。D项错误，月晕的出现，往往预示着天气要有一定的变化。月晕多预示着要刮风，月晕有时候会有缺口，缺口的方向便是刮风的方向。柱子的基石润湿了，就是要下雨的征候。比喻见到一点迹象就能知道它的发展趋向。并未体现气体扩散现象。故正确答案为A。", "tag": "科技常识"},
{"id": "tech-203", "q": "下列每组现象包含的物理学原理不同的是：", "options": ["高压锅蒸煮食物—火星上水的沸点降低", "饮料从摔碎的瓶子中溅出—大质量恒星末期爆炸", "烤箱中葡萄干面包膨胀，葡萄干远移—宇宙扩张，星系远移", "用LED 手电直射滴入1 滴牛奶的水杯，末端呈黄色—傍晚天边呈橘红色"], "a": 1, "e": ".【B】本题考查物理常识。B项符合题意：饮料本来依附在瓶子上，瓶子破裂，饮料与瓶子之间的附着力消失，饮料溅出，体现的是弹力原理。大质量恒星的质量越大，引力越大，塌陷时的压力就越强，大质量恒星末期爆炸是由于引力与塌陷产生的压力不平衡造成的。A项不符合题意：两种现象均体现压强原理，高压锅蒸煮食物利用压强提高沸点，火星上由于气压低，水的沸点也降低。C项不符合题意：两种现象都是由于膨胀造成周围物质远移。天体物理学家经常用“葡萄干面包”来比喻宇宙扩张。D项不符合题意：两种现象均体现了光的散射原理。本题为选非题，故正确答案为B。", "tag": "科技常识"},
{"id": "tech-204", "q": "用砂锅煮食物，食物煮好后，让砂锅离开火炉，食物将在锅内继续沸腾一段时间，这是因为：", "options": ["砂锅是不良导体，导热速度较慢，锅内食物温度上升较慢", "锅内食物吸收较多热量，温度超过", "离开火炉的砂锅锅底超过", "砂锅热容量较大，离开火炉后，食物将从砂锅吸收热量，温度继续上升"], "a": 2, "e": ".【C】本题考查物理常识，主要考查物体的状态变化。C项正确：用砂锅煮食物，食物煮好后，让砂锅离开火炉，食物将在锅内继续沸腾一段时间，这是因为砂锅离开火炉时，砂锅底的温度高于，而锅内食物为，离开火炉后，锅内食物能从锅底吸收热量，继续沸腾，直到锅底的温度降为为止。A项错误：在已经达到沸点时，温度不会继续上升，砂锅导热速度慢，因此锅内食物温度降低较慢。B项错误：在1个标准大气压下，水的沸点是。D项错误：砂锅离开火炉后，从锅底吸收热量，使锅内温度保持在，而无法使温度继续上升。", "tag": "科技常识"},
{"id": "tech-205", "q": "变色太阳镜的镜片能在太阳光线射来之后变暗，光线减弱后变亮，这是因为：", "options": ["镜片吸收水平偏振光线，使镜片变暗，光线减弱后，水平偏振光增强使镜片变亮", "镜片有选择地反射部分波段的光线，使镜片变暗，光线减弱后，透射光增加使镜片变亮", "镜片中的晶体见光分解，吸收光线使镜片变暗，光线变暗时，晶体重新形成，镜片变亮", "镜片有选择地吸收部分波段的太阳光线，使镜片变暗，光线变暗时，反射光加强，镜片变亮"], "a": 2, "e": ".【C】本题考查物理常识。变色太阳镜在阳光下光线强烈照射时，镜片颜色会渐渐变深，可以保护眼睛免受强光刺激；进入室内，光线减弱，镜片颜色渐渐变浅，保证了对景物的正常观察。C项正确：变色太阳镜的镜片是用含氯化银微晶体的光学玻璃制作的，根据光色互变可逆反应原理，在日光和紫外线照射下可迅速变暗，完全吸收紫外线，对可见光呈中性吸收；回到暗处，能快速恢复无色透明。A项错误：偏振光是电矢量相对于传播方向以一固定方式振动的光，偏振镜主要应用于摄影，可以改变蓝天影调和色调、模拟夜景效果、改善非金属物体表面耀斑部位的影像清晰度、质感和色彩饱和度等。B项错误：光投射到两种介质的分界面时，一部分光线改变了传播方向，返回第一媒介质继续传播，称之为光的反射。即光学镜片都会发生光的反射，并不是变色太阳镜变暗的原理。D项错误，有选择性地吸收部分太阳波段的光线是偏光太阳镜的原理，即我们常说的墨镜，偏光太阳镜的镜片由于金属粉末过滤装置，能在光线射入时对其进行选择，将所有有害光线都阻隔掉却不影响可视光的透过，能够很好的保护眼睛不受阳光中有害光线的伤害。故正确答案为C。", "tag": "科技常识"},
{"id": "tech-206", "q": "声音可以在固态、液态和气态的介质中传播，传播的速度与介质分子间距有关，分子间距越小，声音的传播速度越快。下列介质中声音传播速度最快的是（）。", "options": ["铁棒", "竹竿", "盐水", "液态汞"], "a": 0, "e": ".【A】声音传播的速度与介质的种类有关：声音在固体中传播的最快，在气体中传播的最慢，液体介于两者之间。而铁棒的密度要大于竹竿，因此声音通过铁棒传播的速度更快。所以排除B、C、D，只有A项属于密度最大的固体。故正确答案为A。", "tag": "科技常识"},
{"id": "tech-207", "q": "应用斜面原理省力的是：", "options": ["开瓶器", "扳手", "订书机", "螺丝钉"], "a": 3, "e": ".【D】本题考查科技常识。斜面指同水平面成一倾斜角度的平面，是一种简单机械，用于克服垂直提升重物的困难，省力但是费距离。斜面与平面的倾角越小，斜面越长，则省力越大。A项错误，啤酒开瓶器运用了杠杆原理，开瓶器手柄相对较长，利用大的动作幅度来换取小的行程，实现省力。支点离瓶盖越近，开啤酒瓶就越轻松。B项错误，扳手运用的是杠杆原理，活动手柄为动力臂，手柄越长即动力臂越长，动力臂大于阻力臂故为省力杠杆。C项错误，订书机涉及的物理原理主要为压强、杠杆原理，不涉及斜面原理。如：压柄做得宽大有利于减小压强；钉书针（出针口）很尖细有利于增大压强；底座做得宽大有利于减小压强；订书机是以转轴为支点的杠杆，压柄、弹簧、转轴构成一个省力杠杆。D项正确，螺丝钉是利用物体的斜面省力原理，螺钉的螺纹展开就是一个长长的斜面,但是角度很小，拧螺丝钉的时候就相当于在斜面上推一个方块。故正确答案为D。", "tag": "科技常识"},
{"id": "tech-208", "q": "下列有关物理知识的表述中，正确的是：", "options": ["立竿见影与桥在河里形成倒影，其原理相同", "将哈勃天文望远镜送到太空中要避免光的反射", "硬币比纸片下落得快，是因为硬币受到的重力比纸片大", "冰雪天开车时，车辆加装防滑链，是为了增加摩擦力"], "a": 3, "e": ".【D】本题考查科技常识。A项错误，“立竿见影”是指在阳光下竖起竹竿，立刻就能看到竹竿的影子，其物理原理是光在同一种均匀介质中沿直线传播；而桥在河里的倒影属于平面镜成像现象，是由于光的反射原理。故二者原理不同。B项错误，由于太空中不存在空气、尘埃以及水蒸气等因素，光在真空中沿直线传播，不存在折射和反射现象，所以不需要避免光的反射。C项错误，重力是指物体由于地球的吸引而受到的力。重力的方向总是竖直向下，物体受到的重力的大小跟物体的质量成正比，计算公式是：，为重力加速度，一般取9.8N/kg。当物体质量相同时，受到的重力是一样的。但由于硬币密度比纸大得多，同质量的硬币要比纸体积小很多，导致硬币受到空气阻力的影响比纸片小，所以比纸片下落得快。如果在真空环境中，二者将下落得一样快。D项正确，防滑链的原理是把车辆的重力集中到防滑链片的金属点上，产生巨大的压力，轧透冰雪层直达路面，增大接触面积，有效增强车辆在雪道的附着力，从而增大摩擦力，增加车辆行驶的安全系数，保证了在冰雪道路上行驶的操控性和稳定性，让车辆顺利通行。故正确答案为D。", "tag": "科技常识"},
{"id": "tech-209", "q": "下列做法中符合用电安全的是：", "options": ["为使用方便，应将销售到农村地区的空调三脚插头改为两脚插头", "发生触电事故后，应先切断电源再救治", "为安全起见，保险丝应尽可能粗", "当电器发生起火事故时，应迅速泼水灭火"], "a": 1, "e": ".【B】A项：三脚插头的三根电线是L（火线）、N（零线）和E（接地线)。接地线是与电器的金属外壳连通的，万一外壳因绝缘体损坏等原因而带电，泄漏电就流到保护接地线里，从而引发断路器（空气开关）跳闸或熔断器断路或漏电保护器动作等保护动作，从而保护我们不被触电，所以三脚插头更安全。将三脚插头改为两脚插头，错误；B项：当发生人身触电事故时，应立即断开电源，使触电人员与带电部分脱离，并立即进行急救。在切断电源之前禁止其他人员直接接触触电人员，正确；C项：粗保险丝通过的电流大，在电流过大时不易及时熔断，起不到保护电路作用，错误；D项：家用电器或电线发生火灾时，应先断开电源再灭火，切断电源后方可用常规的方法灭火，没有灭火器时可用水浇灭。电器设备着火后，不能直接用水冲浇，因为水有导电性，进入带电设备后易引触电，会降低设备绝缘性能，甚至引起设备爆炸，危及人身安全，错误。故正确答案为B。", "tag": "科技常识"},
{"id": "tech-210", "q": "关于生活常识，下列说法正确的是：", "options": ["数字电视将数字信号转化为模拟信号", "微波炉利用自身的电阻丝发出的热量来加热食物", "常压下蒸汽电熨斗喷出的水汽不会超过100℃", "LED 灯的发光原理与白炽灯相同"], "a": 2, "e": ".【C】C项正确，我们看到的水汽，本质上是悬浮在空气中的小水滴，是液态水，常压下，水的沸点是100℃，液态水的温度不会超过100℃。A项错误，数字电视是指通过接收数字电视信号来收看电视节目的一种电视类型，将数字电视信号转换成模拟信号的，是数字电视机顶盒，不是数字电视。B项错误，微波炉主要是利用微波的能量来加热食物。D项错误，LED灯是利用发光二极管把电能转化为光能，白炽灯是把电能转化成热能和光能，且大部分是转化成热能。故正确答案为C。", "tag": "科技常识"},
{"id": "tech-211", "q": "雾霾天气有时会使建筑物呈现“蜃景”。以下关于“蜃景”说法错误的一项是（）", "options": ["古人将“蜃景”归因于蛟龙之属的蜃吐气而形成，因而得名", "我国广东澳角、山东蓬莱、浙江普陀海面上经常出现这种幻景", "“蜃景”只会出现在平静的海面、江面，雪原、沙漠和戈壁等地方不会出现“蜃景”", "“蜃景”是物体反射的光经大气折射而形成的虚像"], "a": 2, "e": ".【C】A项：说法正确，蜃景即海市蜃楼，古人误认是蜃吐气所形成的景象。蜃景，是指大气光学现象。光线经过不同密度的空气层后发生显著折射，使远处景物显示在半空中或地面上的奇异幻景。常发生在海上或沙漠地区。古时传说这种幻景是海里的蜃吐气而成的；B项：说法正确，我国几大著名的海市蜃楼的观景点为广东澳角、山东蓬莱、浙江普陀等地；C项：说法错误，海市蜃楼不只会出现在平静的海面、江面，雪原，沙漠和戈壁等其他的地方，只要有不同密度的空气出现，都有可能出现海市蜃楼；D项：说法正确，“蜃景”是物体反射的光经大气折射而形成的虚像。本题为选非题，故正确答案为C。", "tag": "科技常识"},
{"id": "tech-212", "q": "当海面上空气各层的密度有较大差异时，远处的光线通过密度不同的空气层发生折射或全反射，海面上会出现远处物体的影像，这一现象被称为海市蜃楼。海市蜃楼最有可能发生的季节是：", "options": ["春季", "夏季", "秋季", "冬季"], "a": 1, "e": ".【B】海市蜃楼是一种由光的折射产生的现象，多发生在夏天的海面上。夏天，较热的空气笼罩海面，但是海水比较凉，海面附近空气的温度比空中的低。来自地平线以外远处的物体的光线，本来不能到达我们的眼中，但有一些射向空中的光线，由于不同高度空气的疏密不同而发生弯曲，逐渐弯向地面，进入观察者的眼睛。逆着光线看去，就感觉看到了远处的物体。故正确答案为B。", "tag": "科技常识"},
{"id": "tech-213", "q": "火车轨道由两道钢轨组成。一般来说，转弯处的火车轨道，内外两侧钢轨的高低关系为：", "options": ["内侧比外侧高", "外侧比内侧高", "两侧一样高", "有时内侧高，有时外侧高"], "a": 1, "e": ".【B】转弯处的火车轨道外轨比内轨略高，这样可以使列车顺利转弯，减少车轮与铁轨的挤压。故正确答案为B。", "tag": "科技常识"},
{"id": "tech-214", "q": "世界上的一切物体都是由大量分子组成的。下列现象中能说明分子在不停息运动的是：", "options": ["秋风瑟瑟，桂香袭人", "沙尘暴起，飞沙漫天", "晚风轻拂，炊烟袅袅", "狂风怒吼，波翻浪涌"], "a": 0, "e": ".【A】A项正确，桂香袭人说明分子在运动，分子是看不见的，其他三个选项沙尘、炊烟、波浪都是看的到的，不可能是分子运动。故正确答案为A。", "tag": "科技常识"},
{"id": "tech-215", "q": "以下各项中，不属于太阳能利用的主要形式的是：", "options": ["光热", "光电", "风热", "光化学"], "a": 2, "e": ".【C】太阳能的利用方式包括太阳能的光热利用、光电利用、光化学利用以及光生物利用，而风热属于风能的范畴。本题为选非题，故正确答案为C。", "tag": "科技常识"},
{"id": "tech-216", "q": "人类利用杠杆原理发明了各种各样的工具，使工作生活更加便利。以下工具中，使用杠杆原理的目的与其他三项不同的是：", "options": ["扫帚", "手推车", "开瓶器", "扳手"], "a": 0, "e": ".【A】B、C、D均为省力杠杆，A项扫帚为费力杠杆，与其他三项不同。故正确答案为A。", "tag": "科技常识"},
{"id": "tech-217", "q": "晴朗的夜空中，星星一闪一闪的原因是：", "options": ["对月光的反射", "大气的折射作用", "星际物质的遮挡作用", "星星自身会发出闪烁的光"], "a": 1, "e": ".【B】星星闪烁是大气折射的现象。恒星虽然体积很大，但距离我们过于遥远，因此是点光源。所以其发出的光受到大气的扰动后，就会有时看到，有时看不到，肉眼看去，就是一闪一闪了。故正确答案为B。", "tag": "科技常识"},
{"id": "tech-218", "q": "每年春分和秋分前后，太阳穿过赤道，这段时间太阳位于地球赤道上空。由于通讯卫星多定点在赤道上空运行，在这期间，如果太阳、通信卫星和地面卫星接收天线恰巧又在一条直线上，那么太阳强大的电磁辐射会对卫星下行信号造成强烈的干扰。这种现象称为：", "options": ["日凌", "幻日", "彩虹", "幻日弧光"], "a": 0, "e": ".【A】太阳会发出强大的电磁辐射，是一种正常的自然现象。每年春分和秋分前后，太阳穿过赤道，这段时间太阳位于地球赤道上空。由于通讯卫星多定点在赤道上空运行，在这期间，如果太阳、通信卫星和地面卫星接收天线恰巧又在一条直线上，那么太阳强大的电磁辐射会对卫星下行信号造成强烈的干扰，这种现象称为日凌，就是太阳侵犯、干扰之意，这是一种正常的自然现象，故A项正确。幻日是大气的一种光学现象。在天空出现的半透明薄云里面，有许多飘浮在空中的六角形柱状的冰晶体，偶尔它们会整整齐齐地垂直排列在空中。当太阳光射在这一根根六角形冰柱上，就会发生非常规律的折射现象，也就是我们日常生活中常见的多个太阳，故B项错误。彩虹是气象中的一种光学现象。当太阳光照射到空气中的水滴，光线被折射及反射，在天空上形成拱形的七彩光谱，雨后常见。形状弯曲，通常为半圆状，色彩艳丽，常有七色彩虹之说，故C选项错误。幻日弧光又叫环天顶弧，是一种由太阳光折射形成的天文奇观，它是由阳光以一定的角度照射在距离地面2万英尺至", "tag": "科技常识"},
{"id": "tech-219", "q": "盥洗间里的干手器可以自动开关的原因是：", "options": ["因为人手可以改变湿度", "因为人手可以改变电容量", "因为人手可以改变温度", "因为人手可以产生磁场"], "a": 1, "e": ".【B】B选项正确，因为人体是导电的，可以形成电容，电容的变化打破了电流原来的平衡状态，产生了一股新的电流，接通了干手器上的电源。故正确答案为B。", "tag": "科技常识"},
{"id": "tech-220", "q": "遇到雷电天气时，下列说法不正确的是：", "options": ["要及时从汽车中逃离", "在建筑物中应远离电话、电视等", "要远离单独的高大树木", "在野外可以蜷缩在地面较低的区域"], "a": 0, "e": ".【A】A项表述错误：汽车本身就是一个金属壳体，相当于一个屏蔽室，当雷电击中汽车时，电流会沿着汽车表面的金属导入地面，汽车里面的人员相对更加安全，当选。B项表述正确：电话、电视等天线有极佳的导电性，其电磁波也会引雷，排除。C项表述正确：雷雨天气时，不要在孤立的高大建筑物和大树下避雨，因为高大物体易遭雷击，排除。D项表述正确：蜷缩在地面较低的区域，是因为雷电容易击中较高的地方，低洼的地方一般不会遭雷击，排除。本题为选非题，故正确答案为A。", "tag": "科技常识"},
{"id": "tech-221", "q": "下列哪项没有运用热胀冷缩原理？", "options": ["医生用水银温度计给病人量体温", "架设天线时，两个电线杆之间的电线要略有下垂", "夏季自行车胎不能打太足的气", "古代人在冬天往岩石缝里灌水，水结冰膨胀后使岩石碎裂"], "a": 3, "e": ".【D】D项错误，古代人采用冷冻法破碎岩石，是让水受冻结成冰，由于密度的变化导致体积膨胀使岩石开裂，并没有运用热胀冷缩的原理。本题为选非题，故正确答案为D。", "tag": "科技常识"},
{"id": "tech-222", "q": "下列物品利用凸透镜透光原理的是：", "options": ["近视镜", "显微镜目镜", "汽车观后镜", "手电筒反光镜"], "a": 1, "e": ".【B】A项错误，近视镜是利用了凹透镜原理；B项正确，显微镜目镜利用了凸透镜原理；C项错误，汽车观后镜利用了凸面镜发散的原理；D项错误，手电筒反光镜利用了凹面镜的原理。故正确答案为B。", "tag": "科技常识"},
{"id": "tech-223", "q": "当乘坐升降电梯上楼时，从电梯开始启动到最后停下来，身体所处的状态先后分别为：", "options": ["失重正常超重", "超重正常失重", "超重失重正常", "正常超重失重"], "a": 1, "e": ".【B】电梯启动后，具有向上的加速度，此时人体所受到的支持力大于人体本身的重力，处于超重的状态，而后电梯匀速上升，人体处于正常状态，电梯即将停下来前，具有向下的加速度，这时人体所受到的支持力小于人体本身的重力，处于失重的状态，直到最后停下来。故正确答案为B。", "tag": "科技常识"},
{"id": "tech-224", "q": "红外线是太阳光线中众多不可见光线的一种，由德国科学家霍胥尔于1800 年发现。它之所以不能被人看到是因为：", "options": ["超出了可见光谱范围", "低于视觉刺激阈限", "不能刺激锥体细胞", "不能刺激棒体细胞"], "a": 0, "e": ".【A】人的眼睛能看到的可见光按波长从长到短排列，依次为红、橙、黄、绿、青、蓝、紫。其中红光的波长范围为", "tag": "科技常识"},
{"id": "tech-225", "q": "下列表述正确的是：", "options": ["房顶被风掀翻是由于屋内的大气压力高于室外的大气压力", "用手动打气筒给轮胎打气，气筒内气压始终高于胎内气压", "高海拔地区气压低于平原地区是由于氧浓度变化造成的", "轮胎充气后，内胎气压升高、摩擦力增大，起到了缓冲作用"], "a": 0, "e": ".【A】根据流体力学的伯努利原理，气流速度越小，压强就越大；反之速度越大，压强就越小。大风天气中大气流动速度增大，房顶外部压强变小，而房屋内部空气相对静止，压强与外部相比较大，压力将房顶顶翻，造成大风掀翻房顶的现象。B项错误，当打不进去气的时候，气筒内气压和胎内气压是相等的。C项错误，高海拔地区气压低是因为高处空气稀薄。D项错误，内胎气压升高后，轮胎更鼓，与地面接触的面积减小，摩擦力降低。故正确答案为A。", "tag": "科技常识"},
{"id": "tech-226", "q": "下列关于能源分类表述错误的是：", "options": ["水能是一次能源，是可再生能源，属于清洁能源", "电能是一次能源，是可再生能源，属于清洁能源", "太阳能是一次能源，是可再生能源，属于清洁能源", "石油是一次能源，是不可再生能源，不是清洁能源"], "a": 1, "e": ".【B】B项错误，一次能源是指自然界中以原有形式存在的、未经加工转换的能量资源，包括化石燃料、生物质能、水能、风能、太阳能等。电能主要来自其他形式能量的转换，是二次能源。本题为选非题，故正确答案为B。", "tag": "科技常识"},
{"id": "tech-227", "q": "关于灯具，下列说法错误的是（）。", "options": ["霓虹灯内填充不同稀有气体会发出不同颜色的光", "探照灯将光线集中投射于特定方向是利用凹面镜", "激光灯光线不易分散可在空中呈现条条靓丽光束", "荧光灯光线十分接近自然光，是一种热辐射光源"], "a": 3, "e": ".【D】本题考查科技常识。A项正确，霓虹灯是一种常见的室外照明灯具，把氖或氩等稀有气体（早期曾填充过氮气或二氧化碳）填充在真空的玻璃外壳中制成，通电时，在高电压作用下部分气体原子被电离成正离子和自由电子（气体的电离过程），带电粒子在电场作用下快速定向漂移，漂移过程中与未被电离的气体原子发生频繁碰撞，带电粒子能量足够大时可将气体原子激发，气体原子（本质上是原子中的电子）由激发态（高能态）向基态（低能态）跃迁时发射光子，形成亮光。不同稀有气体原子跃迁时发出不同频率的光，故灯管内填充不同稀有气体通电后发出不同颜色的光，氖气发出红光，氩气发出蓝紫色光等。B项正确，探照灯具有强大的光源以及一面能将光线集中投射于特定方向的凹面镜，用于远距离照明和搜索。光源（灯泡）处于凹面镜焦点位置，焦点光源发出的光线以不同角度射向镜面，经反射会聚为平行光，光束穿过灯罩照亮前方。如没有凹面镜，光源（灯泡）发出的光线会向外四处发散，难以形成会聚的光束直射前方，如下图所示。C项正确，某些物质中的原子（本质上是原子中的电子）受光或电的激发，由低能级原子跃迁为高能级原子，随着高能级原子不断累积，数目上大于低能级原子，这时的高能级原子处于相对稳定的状态，不易自发跃迁到低能级，只有受到外来光子激励，才由高能级跃迁回低能级（这一过程称为受激辐射），同时发射出与外来光子相位、频率、方向等完全相同的光子，由于是受外来光子激励而发生跃迁射出的光，故名激光。激光具有亮度高、方向性好（散射极小、不易分散）、单色性好的特性。D项错误，荧光灯俗称日光灯，其发出的光线与自然光十分接近，被认为是最接近自然光的光源。荧光灯是在真空玻璃管里充入微量水银（常温下挥发为水银蒸气），两端安装电极，管内壁涂有荧光物质。通电后水银蒸气放电，同时产生紫外线，激发荧光物质而发光，故荧光灯属气体放电光源。热辐射光源是指物体（如白炽灯中的钨丝）通电加热到白热程度而发出亮光，这一过程是电能转化为热能，热能进而转化为光能，不过，热能大部分以辐射形式散失掉，只有少部分转化为光能，故白炽灯耗电大，照明效率低。本题为选非题，故正确答案为D。", "tag": "科技常识"},
{"id": "tech-228", "q": "2019 年1 月3 日，“嫦娥四号”探测器成功着陆在月球背面，这是人类航天器首次在月球背面软着陆并传回了世界第一张近距离拍摄的月背影像图。对此，下列说法正确的是（）。", "options": ["探测器在月球背面着陆后，不再具有惯性", "探测器在月球背面着陆后，万有引力消失", "拍摄的月背影像图通过电磁波信号传回地面", "该月背影像图是月球背面缩小的虚像"], "a": 2, "e": ".【C】本题考查科技常识。A项错误，惯性是物体的一种固有属性，表现为物体对其运动状态变化的一种阻抗程度，其大小与质量有关。探测器在月球背面着陆，仍然具有惯性。B项错误，万有引力定律：自然界中任何两个物体都是相互吸引的，引力的大小跟这两个物体的质量乘积成正比，跟它们的距离的二次方成反比。探测器着陆后，与月球、地球，或者是其他的有质量的物体间仍然存在万有引力。C项正确，探测器与地面之间利用电磁波进行通信，电磁波的传播不需要介质，将月背影像图通过电磁波信号传回地面。D项错误，该影像图通过探测器携带的全景相机拍摄，其原理与普通相机的成像原理相同，利用凸透镜成像，物体位于二倍焦距以外，得到的是缩小的实像。故正确答案为C。", "tag": "科技常识"},
{"id": "tech-229", "q": "中国科幻电影《流浪地球》自上映后，引起了观影热潮。关于影片中涉及到的物理知识，下列说法错误的是（）。", "options": ["地球的逃逸速度为“第二宇宙速度”", "飞行器的变轨过程中常利用“引力弹弓效应”", "“氦闪”是太阳内部的热核裂变反应造成的", "“洛希极限”是由洛希计算出来的一个距离值"], "a": 2, "e": ".【C】本题考查科技常识。A项正确，“第二宇宙速度”是指人造天体无动力脱离地球引力束缚所需的最小速度。若不计空气阻力，它的大小为", "tag": "科技常识"},
{"id": "tech-230", "q": "下列情形中未包含相同物理原理的是（）。", "options": ["火箭升空蝶泳比赛", "碧空万里霞光万丈", "浮光掠影绿树成荫", "酒精退烧牛肉风干"], "a": 2, "e": ".【C】本题考查科技常识。A项正确，火箭升空（飞行）应用了反冲原理，它是靠喷出气流的反冲作用而获得巨大速度的。根据动量守恒定律，如果一个静止的物体在内力的作用下分裂为两个部分，一部分向某个方向运动，另一部分必然向相反的方向运动。这个现象叫做反冲。反冲运动中，火箭发动机用力将燃料燃烧产生的气体向后推出（喷出），喷出的气体对火箭施加反作用力，即反冲力，反冲力推动火箭上升。因此，反冲原理中包含了作用力与反作用力这一原理；蝶泳（游泳）比赛时，运动员向后划水，水对手臂形成向前的反作用，推动运动员向前游动。蝶泳比赛包含的物理原理是作用力与反作用力。B项正确，可见光由红橙黄绿蓝靛紫七色光组成，七种色光波长递减，由于波长较短的光比波长较长的光更容易被大气散射，故蓝紫色光被大气中的微粒散射到天空的四面八方，所以天空看起来是蓝色的（红橙黄绿色光大部分可穿越大气层到达地面）。碧空万里包含的物理原理是光的散射；霞光出现在日出和日落时候，早晨和傍晚时，太阳处于地平线以下，相比白天，阳光需穿过更长的距离才能到达地球。大气对波长较短的光有较强的散射作用，可见光中波长较短的光（橙黄绿蓝靛紫）在穿越大气层的“长途跋涉”中都被大气散射掉了，只有波长较长的红光因不易被散射而可以较多的到达地面，故人们看到霞光的颜色为（橙）红色。霞光万丈包含的物理原理是光的散射。C项错误，浮光掠影是指像水面的光和略过的影子一样，一晃就消逝。水面的光是反射现象（光照射在水面上而被反射），水面的影子（物体在水中成的像）也是光的反射形成的。浮光掠影包含的物理原理是光的反射；绿树成荫（树荫）是树木枝叶在阳光下所形成的阴影，阴影的形成是由于光的直线传播所致。绿树成荫包含的物理原理是光的直线传播。故二者包含不同的物理原理。D项正确，酒精退烧是物理降温，通过酒精挥发（蒸发）带走热量而达到降低体温的目的。蒸发是一种缓慢的汽化现象，酒精退烧包含的物理原理是汽化（蒸发）；风干牛肉是通过自然晾晒使牛肉中的水分挥发（蒸发），风干的牛肉便于保存。风干牛肉包含的物理原理是汽化（蒸发）。本题为选非题，故正确答案为C。", "tag": "科技常识"},
{"id": "tech-231", "q": "若不考虑万有引力，下列诗词所体现的力学原理与“潮打空城寂寞回”所体现的力学原理不同的是（）。", "options": ["惊涛拍岸，卷起千堆雪", "少女棹舟归，歌声逐流水", "春风得意马蹄疾，一日看尽长安花", "泪眼问花花不语，乱红飞过秋千去"], "a": 3, "e": ".【D】本题考查科技常识。“潮打空城寂寞回”意指潮水拍打着空城的城墙而后落寞地退回。潮水拍打城墙而受到城墙的反作用力，在反作用力下退回，故该句体现的力学原理是作用力与反作用力。A项正确，“惊涛拍岸，卷起千堆雪”意指惊涛拍击着江岸，激起的浪花好似卷起的数千堆白雪。惊涛拍打江岸而受到江岸的反作用力，在反作用力下激起而成为白雪似的浪花，该句体现的力学原理是作用力与反作用力。B项正确，“少女棹舟归，歌声逐流水”意指少女划船归来，歌声随着水波流淌。划船时桨向后拨水，水对桨产生向前的反作用力，水给桨的反作用力通过桨架和划船人的身体传递给船,从而推动船前进，该句体现的力学原理是作用力与反作用力。C项正确，“春风得意马蹄急，一日看尽长安花”意指愉快地骑着马奔驰在春风里，一天的时间便把长安城美景看遍了。马奔跑时蹄向后蹬地，地面对其产生向前的反作用力，成为马奔跑的助推力，该句体现的力学原理是作用力与反作用力。D项错误，“乱红飞过秋千去”意指飘散的花瓣飞过秋千。花瓣在风力作用下，克服自身重力，四处飞散，该句未体现作用力与反作用力。本题为选非题，故正确答案为D。", "tag": "科技常识"},
{"id": "tech-232", "q": "下列关于大气压强的表述，错误的是（）", "options": ["真空压缩保存袋利用了大气压强原理", "马德堡半球实验证明了大气压强的存在", "常用的气压计是无液气压计", "距离地心越远，大气压强就越小"], "a": 3, "e": ".【D】本题考查科技常识。A项正确，真空压缩袋是指用于装棉被和各类衣服的袋子，其工作原理为把棉被衣物内部的空气抽走，再利用大气压强把本来膨胀的棉被等物品压扁，隔离外界空气，以节约空间，达到防尘、防霉、防潮、防虫的作用。B项正确，1654年，在德国马德堡市的广场上曾经做过一个著名的马德堡半球实验。人们把两个铜制空心半球合在一起，抽去里面的空气，用两支马队向相反的方向拉两个半球。当每一侧的马匹达到16匹时，才将半球拉开，并发出巨大的响声。这一实验证明了大气压强的存在。C项正确，测量大气压的仪器叫作气压计。水银气压计比较准确，但携带不便，用得比较多的气压计是金属盒气压计，又叫做无液气压计，它的主要部分是一个波纹状真空金属盒。气压变化时，金属盒厚度会发生变化，传动装置将这种变化转变为指针的偏转，指示出气压的大小。D项错误，距离地面（海平面）越远，压强越小。但并非距离地心越远，压强越小。如南美的钦博拉索山是世界距离地心最远的地点，但是海拔只有6272米，其最高点大气压强就比海拔最高峰珠穆朗玛峰要大。本题为选非题，故正确答案为D。", "tag": "科技常识"},
{"id": "tech-233", "q": "下列体育场景中，物体受力所发生的形变不同于其他三项的是（）。", "options": ["灌篮后触地即将反弹的篮球", "花剑击中对方时弯曲的剑体", "铅球落地时被砸出坑印的场地", "跳水运动员起跳时下压的踏板"], "a": 2, "e": ".【C】本题考查科技常识。物理学中，把物体发生的伸长、缩短、弯曲等变化称为形变。形变有弹性形变和塑性形变两种。A、B、D三项正确，弹性形变是指固体受外力作用而使各点间相对位置改变，当外力撤消后，固体又恢复原状。A项“触地即将反弹的篮球”、B项“花剑击中对方时弯曲的剑体”、D项“起跳时下压的踏板”，当它们所受到的外力消失时，都可以恢复到原状，所以它们发生的是弹性形变。C项错误，物体的形变过大，超过一定限度，这个时候即使除去外力，物体也不能完全恢复原状，这个限度叫做弹性限度，超过了这个限度，物体发生的形变叫做塑性形变。铅球被拿开后，场地上的坑印仍然存在。即外力撤去，场地也不能恢复原状，所以场地发生的是塑性形变。本题为选非题，故正确答案为C。", "tag": "科技常识"},
{"id": "tech-234", "q": "下列关于磁场的表述，正确的是（）", "options": ["司南是最早的磁性指向器，它的勺尾指向北方", "地球的地理两极与地磁两极是完全重合的", "奥斯特最先发现了电流的磁效应", "安培最早提出磁场对运动电荷有力的作用"], "a": 2, "e": ".【C】本题考查科技常识。A项错误，司南是最早的磁性指向器，它由青铜盘和磁石琢磨的勺组成，磁勺头为磁体的北极，尾为南极。磁勺放置在盘的中心，受地磁作用，勺尾指向南方。B项错误，地球的地理两极与地磁两极并不重合。因此，磁针并非准确地指南或指北，其间有一个交角，这就是地磁偏角，简称磁偏角。磁偏角的发现，对于科学的发展和指南针在航海中的应用很重要。C项正确，1820年，奥斯特发现：把一根导线平行地放在磁针的上方，给导线通电时，磁针发生了偏转，就好像磁针受到磁铁的作用一样。这说明不仅磁铁能产生磁场，电流也能产生磁场，这个现象被称为电流的磁效应。这一发现震惊了当时的科学界，对电与磁研究的深入发展具有划时代的意义，也预示了电力应用的可能性。D项错误，荷兰物理学家洛伦兹首先提出运动电荷产生磁场和磁场对运动电荷有作用力的观点。为了纪念他，人们称磁场对运动电荷的作用力为洛伦兹力。故正确答案为C。", "tag": "科技常识"},
{"id": "tech-235", "q": "下列应用中未涉及伯努利原理的是（）。", "options": ["飞机机翼", "地铁候车安全线", "平行前进的两船相撞", "潜艇下潜"], "a": 3, "e": ".【D】本题考查科技常识。伯努利原理是指在流体中（水流或气流里），如果流体速度小，压强就大；如果流体速度大，压强就小。A项正确，飞机机翼横截面设计成上下不对称的形状，使得飞机飞行时机翼上方的空气流线密，流速大，下方的空气流线疏，流速小。由伯努利原理可知，机翼上方的压强小，下方的压强大。这样就产生了作用在机翼上的方向向上的升力。B项正确，地铁列车进站时速度很快，车厢附近的空气被带着也会流速加快，而距离车厢远的地方空气流速慢。根据伯努利原理，靠近车厢的地方压力小，远离车厢的地方压力大，二者之间有压力差，因此，如果距离轨道太近，会被推向列车，造成事故。C项正确，当两艘船平行前进时，两船中间的水比外侧的水流速快，根据伯努利原理，中间的水对两船内侧的压强比外侧水对两船外侧的压强要小，于是在外侧水压力的“推动”下，两船逐渐靠近，最后相撞。D项错误，潜水艇工作原理是阿基米德定律（浮力定律）。在潜艇上都设有压载水舱，只要往空的压载水舱里注水，潜艇就变重了，这时潜艇的重量就会大于它排开水的重量（即大于浮力），潜艇就逐渐下潜。当潜艇上浮时，用高压空气分步骤把压载水舱里的水挤出去，使之充满了空气，使潜艇在水下的重量减轻了，当潜艇的重量小于它同体积的水的重量时（即小于浮力时），潜艇就会上浮，直至浮出水面。本题为选非题，故正确答案为D。", "tag": "科技常识"},
{"id": "tech-236", "q": "涉及汽车的物理常识，下列说法不正确的是：", "options": ["汽车爬坡时要提高车辆速度", "汽车使用凸面镜作为后视镜", "鸣笛是电能转换为机械能的过程", "汽车一般用循环流动的水冷却发动机"], "a": 0, "e": ".【A】本题考查科技常识。A项错误，爬坡时汽车要克服重力做功，需要较大牵引力才能克服重力，根据（P为功率，F为牵引力，V为速度），在发动机的功率一定时速度越小，牵引力越大，所以汽车爬坡时要以较小速度通过，来获得较大牵引力。B项正确，凸面镜对光有发散作用，可以让司机获得更广的视野，凸面镜还主要用于各种弯道、路口。C项正确，喇叭发声的原理为：交流电流通过喇叭音圈，产生电磁场，与喇叭的永磁体产生排斥从而带动音圈震盘运动，推动空气震动而发出声音。声音是机械波，因此这一过程中电能转化为了机械能。D项正确，因为水的比热高，有着良好的传热性能，所以现代汽车发动机大多采用水冷，具体就是将发动机外装上水套，用循环流动的水帮助发动机散热。本题为选非题，故正确答案为A。", "tag": "科技常识"},
{"id": "tech-237", "q": "关于塑料大棚，下列说法正确的是：", "options": ["塑料大棚的薄膜能够提高光照强度", "搭建塑料大棚能有效防御地质灾害", "冬季在塑料大棚内熏烟有助于防御霜冻", "无土栽培技术必须在塑料大棚中进行​"], "a": 2, "e": ".【C】本题考查科技常识。A项错误，塑料大棚内的光照强度比外界要低，因为所有的塑料薄膜都有吸收和反光作用。B项错误，地质灾害是指因地质现象给人类造成的灾害，包括地震、海啸、火山喷发、山崩、滑坡、泥石流、塌陷、地面下沉等。地质灾害破坏性强，塑料大棚无法起到防御作用。C项正确，大气凭借自身的温度向外辐射能量，为大气辐射。大气辐射中一小部分向上，散失于宇宙空间；其余大部分向下，归还给地面。大气辐射中向下的部分，称为大气逆辐射，属于长波辐射。由于大气逆辐射的存在，使地面实际损失的热量比它以长波辐射放出的热量要少一些。大气逆辐射的强度主要与大气中的水汽含量、二氧化碳之类所谓“温室气体”的浓度以及大气温度成正比关系。人造烟幕中含有大量的二氧化碳、水汽、尘埃，能强烈地吸收地面辐射，从而增强大气逆辐射，减少夜晚地面辐射损失的热量，对地面起到保温的作用，所以可以预防霜冻。D项错误，无土栽培指完全不用土壤而用化肥溶液（营养液）供给作物养分的栽培方法。无土栽培设施分为环境设施、监控设施及栽培设施。环境设施主要指生产蔬菜的保护地设施，即温室、大棚、中棚等。因此无土栽培栽培场所不仅仅局限于塑料大棚。故正确答案为C。", "tag": "科技常识"},
{"id": "tech-238", "q": "下列与疫苗有关的说法正确的是：", "options": ["疫苗通过三角肌注射才能产生作用", "免疫力弱的人不能接种疫苗", "疫苗的接种者必须是健康个体", "卡介疫苗是典型的活疫苗​"], "a": 3, "e": ".【D】本题考查科技常识。A项错误，1988年WHO建议：狂犬病疫苗注射部位由臀部改为上臂三角肌。观察证明狂犬病疫苗注入人体不同部位会产生不同程度的抗体应答，其中注射三角肌抗体应答滴度最高，臀部肌肉注射滴度最低，比较观察乙肝疫苗在臀部和三角肌肌肉注射的免疫效果也证明：三角肌注射的抗体阳转率和GMT均比臀部肌肉注射的高得多。普遍认为这是由于注入臀部脂肪中，影响疫苗的吸收与免疫效果的发挥，而三角肌较接近腋下淋巴结，有利于免疫力的产生。所以并不是疫苗通过三角肌注射才能产生作用，只是通过三角肌注射效果比较好。B项错误，免疫力低下者一般不可以接种减毒活疫苗，而灭活疫苗是可以接种的，比如乙肝疫苗等。C项错误，预防性接种，受种者普遍是健康的个体。然而在治疗性接种中，比如狂犬疫苗，由于狂犬病是致命性疾病，为挽救生命任何禁忌症都是次要的，故被患狂犬病的动物咬后预防无禁忌症。D项正确，卡介苗是一种减毒牛型结核分枝杆菌活菌疫苗，用来预防结核病的疫苗。卡介苗接种后可使儿童产生对结核病的特殊抵抗力，可以降低儿童结核病的发病率及其严重性，特别是结核性脑膜炎等严重结核病减少，并可减少此后内源性恶化的可能性。故正确答案为D。", "tag": "科技常识"},
{"id": "tech-239", "q": "下列选项对烹饪方式的解释表述正确的是：", "options": ["煸——将食物放在沸水中烫", "煨——将各种食物混合加水煮", "烩——用小火将食物慢慢地煮", "焗——利用蒸汽使密闭容器中的食物变熟"], "a": 3, "e": ".【D】A项错误：煸，是原料投入锅中后中火热油不断翻炒至原料干香滋润而成菜的烹调方法，是一种较短时间加热成菜的方法。B项错误：煨，是食物连同汤水放入密封的瓦坛中，在文火中致熟的烹调方法。C项错误：烩，是炒菜后加少量的水和芡粉的一种烹饪方法。D项正确：焗，客家菜烹调方法，通过盖上锅盖保留热气，使未熟的食物熟透，是以汤汁与蒸气或盐或热的气体为导热媒介，将经腌制的物料或半成品加热至熟而成菜的烹调方法。故正确答案为D。", "tag": "科技常识"},
{"id": "tech-240", "q": "下列选项中，叙述错误的是：", "options": ["用手或其他物品轻敲瓷器，通过声音就能判断瓷器的好坏，因为有裂缝的碗、盆发出声音的音色远比正常的瓷器差", "通过监测次声波可以知道地震、台风的信息，因为次声波是频率低于20 赫兹的声音，人类无法听到", "除大型客车外，绝大多数汽车的前窗都是倾斜的，避免因平面镜成像而造成事故", "对胃肠有明显刺激的药物，最好饭前服用，服药后能充分吸收，可使药物保持有效浓度，迅速发挥药效"], "a": 3, "e": ".【D】本题考查科技常识。A项正确，判断瓷器好坏，可以通过用手或其他物品轻敲瓷器的音色来辨别：如果声音清脆响亮，则说明瓷胎细致密实，无裂损；如果声音沉闷喑哑，则说明瓷胎有裂损、内伤，瓷化不完全。此外，实际生活中还会通过辨别音调、观察瓷器形态来辨别。B项正确，一些自然灾害如地震、火山喷发、台风等都伴有次声波的产生，次声波是频率低于20赫兹的声音，人类无法听到，次声波在传播过程中减速很小，能传播的很远，所以通过监测次声波能获取某些自然灾害的信息。C项正确，汽车的前窗相当于一块平面镜，除了透光外，还能反光，车内的人或一些物品就会呈现在前窗上，呈现一个等大的虚像，给司机造成错觉，不易分清车内和车外的人或东西，容易造成交通事故。如果前窗是倾斜的，车内的人或物的像就会呈现在车的正上方，而路上的行人是不可能出现在上方的空中的，这样就将车内乘客的像与路上行人分离开来，司机就不会出现错觉，避免因平面镜成像而造成事故。而大型客车都比较高，在地面上行走的人的像不会出现在前窗上，所以司机容易区分车内、车外的人或事物。因此除大型客车外，绝大多数汽车的前窗都是倾斜的。D项错误，对胃肠有明显刺激的药物，对胃肠黏膜有刺激性，会直接或间接地损伤胃肠黏膜，服后易产生恶心、呕吐、嗳酸等反应，这类药物最好饭后服用，药物被食物稀释，可减少对胃肠道的刺激。本题为选非题，故正确答案为D。", "tag": "科技常识"},
{"id": "tech-241", "q": "下列做法属于接种预防的是：", "options": ["给糖尿病患者注射胰岛素", "给孕妇注射黄体酮", "给幼儿喂食脊灰糖丸", "给患者皮下注射青霉素"], "a": 2, "e": ".【C】本题考查生活常识，主要涉及接种预防的相关知识。接种预防，是利用人工制备的疫苗通过适宜的途径注入人体，使机体获得对疾病的特异免疫力。A项错误，注射外源性胰岛素是用来治疗糖尿病，而不是用来预防糖尿病。B项错误，黄体酮，又称孕酮激素，是女性卵巢分泌的具有生物活性的主要孕激素。在女性怀孕后，如果自身孕酮激素过低，会导致胎儿不稳定，可能引起流产。这时可以通过注射黄体酮给胎儿的早期生长及发育提供保障，不属于接种预防。C项正确，脊髓灰质炎是由脊髓灰质炎病毒引起的一种急性传染病。脊灰糖丸，属于脊髓灰质炎疫苗，给幼儿喂食脊灰糖丸可以预防脊髓灰质炎，属于接种预防。D项错误，青霉素属于抗菌素（抗生素属于抗菌素），具有杀菌作用。注射青霉素主要用来杀菌，治疗疾病，不属于接种预防。故正确答案为C。", "tag": "科技常识"},
{"id": "tech-242", "q": "在日常生活中，下列说法符合科学原理的是（）。", "options": ["使用碳酸饮料可以有效溶解水壶内的水垢", "成年人体内的水分大约能占到体重的", "烧开的水放置一个晚上后，亚硝酸盐含量会显著增加", "剧烈运动后，人们应当避免摄入电解质，以免增加肾脏负担"], "a": 0, "e": ".【A】本题考查科技常识。A项正确，碳酸饮料中含有（碳酸），水垢是水中所含的微量沉淀物质长期积累形成的，主要成分是碳酸钙等碳酸盐，碳酸饮料里面的碳酸会与其发生反应，产生溶于水的碳酸氢钙，从而达到去水垢的目的。B项错误，根据生物学家的报告，成年人体内水分约占人体重的。其中脑脊髓中水占、淋巴腺中水占、血液中水占、肌肉中水占、骨骼中水占。C项错误，按照国家规定，生活饮用水的亚硝酸盐标准是1微克/ml。只要亚硝酸盐不超过这个量，就是安全的。而一般隔夜水的亚硝酸盐含量都不会超过这个数字。D项错误，运动时会丢失大量汗液，其中的成分是水，剩余的则是尿素、乳酸、脂肪酸和各种电解质。过多丢失体内电解质，对运动能力及健康有严重影响。因此大量运动后既要补水，也要补充矿物元素。故正确答案为A。", "tag": "科技常识"},
{"id": "tech-243", "q": "下列有关急救知识的叙述正确的是：", "options": ["对等待急救的脑出血病人不宜随意搬动", "发生烫伤后的伤口可用酱油或牙膏涂抹", "胸外心脏按压的频率为每分钟30～50 次", "严重烧伤的病人口渴时可以喝白开水"], "a": 0, "e": ".【A】本题考查生活常识，主要涉及急救知识的相关内容。A项正确，脑出血的患者如果在突然发病搬运过程中颠簸太厉害就可能加重脑出血。所以发生脑出血的病人应立即平卧、避免震动、就近治疗，不宜长途搬运;待病情稳定后再转院治疗，如果必须搬运应尽量保持车辆、担架平稳，保持头部不要晃动，同时还应将患者的头歪向一侧，以便使呕吐物流出，以免气道阻塞引起窒息。B项错误，牙膏或酱油涂抹在烫伤部位，是一种错误方法。这是由于伤口的热气受到牙膏等物质的遮盖，只能往皮下组织深部扩散，结果就造成了更深一层的烫伤。而酱油不仅不具备治疗功能，酱油的颜色还会影响医生的诊断。另外烫伤后也不要使用冰块冷敷创口处，以免温度过低致使已经破损的皮肤伤口恶化。C项错误，按照2015版心肺复苏指南建议，对成年人实施心肺复苏时胸外按压的频率为100～120次/分。D项错误，严重的烧伤病人常有口渴的感觉，这是由于皮肤大面积烧伤后，体液从伤面大量外渗，致使体内血容量下降，水分减少所致。按医学要求，烧伤后口渴时不能给伤员饮白开水。因在烧伤后，体液丢失的同时，体液中的钠盐也跟着一起丧失，如果单纯给病人喝白开水，可导致血液内氯化钠浓度进一步下降，细胞外液渗透压降低，引起细胞内水肿，出现脑水肿或肺水肿，形成所谓的水中毒，可危及伤员生命。故正确答案是A。", "tag": "科技常识"},
{"id": "tech-244", "q": "根据生产要素在各产业中的相对密集度，可以将产业划分为不同类型。下列对应错误的是：", "options": ["土地密集型产业——畜牧业、采掘业", "劳动密集型产业——钢铁业、化工业", "技术密集型产业——微电子工业、现代制药业", "资本密集型产业——重型机械工业、电力工业"], "a": 1, "e": ".【B】钢铁业、化工业属于资本密集型产业，B项错误；A、C、D三项对应均正确。本题为选非题，故正确答案为B。", "tag": "科技常识"},
{"id": "tech-245", "q": "关于生活知识，下列说法错误的是：", "options": ["缺碘可能会患“大脖子病”", "吃水果有助于补充维生素", "甲醛可以用作药品的防腐剂", "回收废电池可减少重金属污染"], "a": 2, "e": ".【C】A项正确，“大脖子病”学名甲状腺肿，是碘缺乏病的主要表现之一。碘是甲状腺合成甲状腺激素的重要原料之一，碘缺乏时合成甲状腺激素不足，反馈引起垂体分泌过量的促甲状腺激素（TSH），刺激甲状腺增生肥大。B项正确，维生素是维持人体生命活动必需的一类有机物质，也是保持人体健康的重要活性物质。维生素具有外源性，人体自身只能合成维生素D，不能满足人体需要，大部分维生素以维生素原的形式存在于食物中，需要通过食物补充。蔬菜水果中含有多种维生素。C项错误，甲醛有刺激性气味，对人体有害。低浓度就会使人产生不适感，长期、低浓度接触甲醛会引起头痛、头晕、乏力、感觉障碍、免疫力降低；长期接触甲醛可引发呼吸功能障碍和肝中毒性病变，表现为肝细胞损伤、肝辐射能异常等。D项正确，电池主要含镉、锰、汞、锌等重金属，若被弃于自然环境中，重金属成份会随渗液溢出，造成地下水和土壤的污染，日积月累会严重危害人类健康。本题为选非题，故正确答案为C。", "tag": "科技常识"},
{"id": "tech-246", "q": "下列生活常识中，说法错误的是", "options": ["饮酒导致的脂肪肝可能发展成肝硬化", "发烧时多喝水可降低体温和排出毒素", "经常吃冷冻肉有利于延缓人体的衰老", "茶杯壁上的茶垢并不会危害身体健康"], "a": 2, "e": ".【C】本题考查生活常识。需结合具体选项予以分析。A项正确，饮酒导致的脂肪肝，如果不能及时的发现并进行对应治疗的话，酒精性脂肪肝就会演变成肝硬化。B项正确，发烧是身体机能受到外界病毒或者细菌侵袭时的一种自我保护反应，一般情况下，身体温度升高，可以促使身体分泌更多的白细胞来杀死入侵身体的细菌，发烧时多喝水，可以加快新陈代谢，通过排汗、排尿来降低身体温度，同时也可以排除体内毒素。C项错误，肉品经冷冻能较长时间的储存和运输，但冷冻肉并不能延缓人体的衰老。D项正确，茶垢是茶叶中的鞣质（一种复杂的酚类有机物，化学性质很不稳定）暴露在空气中被氧化、聚合形成的棕红色化合物，难溶于水，慢慢从茶叶中沉淀出来，依附在杯壁或壶壁上。茶垢本身并不会危害人体健康。本题为选非题，故正确答案为C。", "tag": "科技常识"},
{"id": "tech-247", "q": "国家气象局地面观测规范规定，降水量仅包括垂直降水，即由空中降落到地面上的水汽凝结物。按照这一标准，下列哪组现象都会被计入“降水量”？", "options": ["雹、霜、雾", "雨、雪、霜", "雪、露、雾", "雨、雪、雹"], "a": 3, "e": ".【D】雾是空气中的水汽凝结成水滴而悬浮于空中。露是凝结在地面或植物上的小水滴。霜是水蒸气在地面上遇冷凝华附在物体表面而形成。A、B、C三项错误，雾、露、霜都不属于垂直降水；D项正确，雨、雪、雹都是由空中降落到地面的水汽凝结而成，属于垂直降水。故正确答案为D。", "tag": "科技常识"},
{"id": "tech-248", "q": "关于蔬菜的保健功能，下列对应正确的是", "options": ["芹菜——安五脏，除胃中热", "苦瓜——调味增食欲，抑菌杀菌", "苦苣——清热解毒，治疗痢疾", "韭菜——止血、益气、利尿，降血压"], "a": 2, "e": ".【C】A项错误，根据《千金食治》菜蔬第三（五十八条）：“韭∶味辛、酸、温、涩、无毒。辛归心，宜肝。可久食。安五脏，除胃中热。”因此，“安五脏，除胃中热”的是韭菜。B项错误，苦瓜具有生津消暑、促进食欲、增强免疫力的作用，一般具有杀菌作用的蔬菜主要指葱蒜类，如大蒜、大葱、韭菜、洋葱、青蒜、蒜苗等。C项正确，苦苣性寒味苦，具有清热解毒、凉血的功效。用于治疗痢疾、黄疸等。D项错误，芹菜的功效是止血、益气、利尿，降血压，而不是韭菜。故正确答案为C。", "tag": "科技常识"},
{"id": "tech-249", "q": "下列说法中，正确的是：", "options": ["1952 年12 月，震惊世界的英国伦敦“烟雾”事件爆发，造成此次事件的原因是燃煤产生的废气污染", "光的波长顺序从短到长排列依次为：红、紫、黄、蓝", "冷藏保存食物是低温可以将细菌冻死", "污染物随废水进入水体后，被浮游生物吸收，小鱼吃浮游生物，大鱼又吃小鱼，人又吃污染后的鱼类，污染物会逐渐"], "a": 0, "e": ".【A】A项正确，发生1952年伦敦“烟雾”事件的直接原因是燃煤产生的二氧化硫和粉尘污染，间接原因是开始于12月4日的逆温层所造成的大气污染物蓄积。燃煤产生的粉尘表面会大量吸附水，成为形成烟雾的凝聚核，这样便形成了浓雾。另外燃煤粉尘中含有三氧化二铁成分，可以催化另一种来自燃煤的污染物二氧化硫氧化生成三氧化硫，进而与吸附在粉尘表面的水化合生成硫酸雾滴。这些硫酸雾滴吸入呼吸系统后会产生强烈的刺激作用，使体弱者发病甚至死亡。B项错误，光的波长顺序从长到短排列依次为：红、橙、黄、绿、蓝、靛、紫。C项错误，冷藏保存食物是低温可以抑制细菌的生长，而不是冻死。D项错误，交叉污染是指饲料在加工、运输和贮藏过程中，不同饲料原料或饲料产品之间发生的相互污染。选项所说的例子实际上是有毒物质的循环，而非交叉污染。故正确答案为A。", "tag": "科技常识"},
{"id": "tech-250", "q": "下列关于生活常识的表述，错误的是：", "options": ["干冰是固体状态的二氧化碳，可用于人工降雨", "红黄绿能作为信号灯的颜色，是因为这三种颜色有波长优势", "海市蜃楼是由于特殊气象条件下大气发生剧烈的反射造成的", "烟草、面粉等有机粉尘聚焦的厂房里容易发生爆炸"], "a": 2, "e": ".【C】C项错误：海市蜃楼，简称蜃景，是一种因为光的折射和全反射而形成的自然现象，是地球上物体反射的光经大气折射而形成的虚像，所以并不是反射造成的。A项正确：干冰是固态的二氧化碳，干冰极容易挥发，升华为二氧化碳，升华吸热，使得空气中的水蒸气遇冷凝结，所以干冰可用作人工降雨中的催化剂。B项正确：红绿黄作为交通信号灯的三种颜色，是根据光学原理来确定的。光是由七种光色组成的，其中红光波长最长，穿透介质的能力最大，最容易被人们的视觉观察到，因此用作停止信号；黄光波长仅次于红光，穿透介质的能力也很大，所以选用黄光作为过渡信号；绿光的波长也是较长的，由于它与红光和黄光易区别，对比色强，因此被用作允许通行信号。D项正确：某些厂矿生产过程中产生的粉尘，特别是一些有机物加工中产生的粉尘，在某些特定条件下会发生爆炸燃烧事故。本题为选非题，故正确答案为C。", "tag": "科技常识"},
{"id": "tech-251", "q": "下列关于生活常识的说法，错误的是：", "options": ["缺铁性贫血应多食用水果，因为维生素C 可以帮助铁的转化和利用", "燕麦有丰富的膳食纤维，能延缓胃中食物进入小肠的速度，产生饱腹感", "柴鸡、肉鸡的营养物质含量相差无几，柴鸡更营养的说法并不科学", "蔬菜水果一洗就掉色，是因为人为添加了色素，正常情况应该是无色的"], "a": 3, "e": ".【D】A项正确，多吃富含维生素C的新鲜水果，如橙子、猕猴桃、山楂等，对补血也有一定的帮助，因为维生素C可以帮助铁的转化和利用，所以缺铁性贫血应多食用水果；B项正确，燕麦中含有丰富的膳食纤维，尤其是可溶性膳食纤维能够延缓胃中内容物进入小肠的速度，使人产生饱腹感，C项正确，从营养物质含量看柴鸡、肉鸡营养成分相差无几，虽然生长周期长的柴鸡口感在一定程度上或许会比肉鸡更好，但是柴鸡更营养的说法并不科学。并且，散养的鸡所进食的食物很有可能得不到保障，无法追根溯源，并不能完全保证食品安全；D项错误，掉色是蔬菜水果本身就存在的特质，因为其本身含有大量的天然色素。水洗掉色的“色”就属于水溶性的花青素，葡萄、草莓等都含有此类色素。通常被储存在植物细胞液泡中的花青素，当细胞破损时会溶解到外界的水中，水被染色也就不足为怪了。因此，蔬菜水果一洗就掉色，并不一定是人为添加了色素。本题为选非题，故正确答案为D。", "tag": "科技常识"},
{"id": "tech-252", "q": "下列体育人物与其擅长领域对应错误的是：", "options": ["罗尼·奥沙利文：斯诺克台球", "拉菲尔·纳达尔：棒球", "罗杰·费德勒：网球", "泰格·伍兹：高尔夫"], "a": 1, "e": ".【B】A项正确，罗尼奥沙利文，世界著名斯诺克球手，以左右开弓和独特的杆法著称，绰号“TheRocket”（火箭）；B项错误，拉菲尔纳达尔是西班牙职业网球运动员，是“金满贯”得主，并且是“体育界的奥斯卡”——劳伦斯奖最佳男运动员获得者；C项正确，罗杰费德勒是瑞士男子职业网球运动员，多次获得大满贯男子单打冠军。2012年上海大师赛结束后，费德勒在ATP世界第一的总周数达到了300周，是公开赛时代以来第一位在世界第一总周数达到300周的男子单打球员；D项正确，艾德瑞克泰格伍兹是美国高尔夫球手，截至2009年世界排名首位，并被公认为是史上最成功的高尔夫球手之一。本题为选非题，故正确答案为B。", "tag": "科技常识"},
{"id": "tech-253", "q": "下列叙述正确的是：", "options": ["酗酒会影响下一代", "长期酗酒的人一旦戒酒，就会得病", "喝酒能促进血液循环，对人体有益无害", "青少年正处于生长发育期，应少量饮酒"], "a": 0, "e": ".【A】研究发现，在对酒精产生依赖以后，女性的大脑萎缩进程要比男性快。酒精对精子和卵子也有毒副作用，不管父亲还是母亲酗酒，都会造成下一代发育畸形、智力低下等不良后果。孕妇饮酒，酒精能通过胎盘进入胎儿体内直接毒害胎儿，影响其正常生长发育。而丈夫经常酗酒的家庭中平均人工流产次数比其他家庭高很多。故正确答案为A。", "tag": "科技常识"},
{"id": "tech-254", "q": "图案造型的基本形式法则不包括：", "options": ["对称与均衡", "照应与搭配", "对比与和谐", "节奏与律动"], "a": 1, "e": ".【B】图案形式美的法则有：对称与均衡、比例与尺度、黄金分割律、主从与重点、稳定与轻巧、节奏与韵律、渗透与层次、和谐与对比、多样与统一。故正确答案为B。", "tag": "科技常识"},
{"id": "tech-255", "q": "下列应急救护的处理方法中，不科学的是：", "options": ["现场救治婴儿气道异物梗塞时，将婴儿置于“头低脚高”的体位", "成人心肺复苏时，以60 次/分钟左右的频率进行胸外心脏按压", "踝关节严重扭伤时，立即用冷水或冰块进行冷敷", "地震后，对埋压时间较长的幸存者，先喂适量含盐饮料"], "a": 1, "e": ".【B】A项正确，现场救治婴儿气道异物梗塞时，应将婴儿置于“头低脚高”体位；B项错误，进行胸外心脏按压要求位置为双乳头连线中点，单手掌跟覆其上，另一手从掌背交叉握紧，按压每分钟至少", "tag": "科技常识"},
{"id": "tech-256", "q": "以下路况，一般来说，驾驶员最容易出现视觉疲劳的是：", "options": ["高速公路", "盘山水泥公路", "平原砂石公路", "城市街道"], "a": 0, "e": ".【A】高速公路上，路况单调，最容易产生视觉疲劳。故正确答案为A。", "tag": "科技常识"},
{"id": "tech-257", "q": "下列能够用于电器设备起火的灭火工具是：①泡沫灭火器②干粉灭火器③二氧化碳灭火器④水枪", "options": ["①②", "①③", "②④", "②③"], "a": 3, "e": ".【D】泡沫灭火器不适用于电器火灾、档案馆或图书室有重要资料文献的火灾、油料类火灾。现在已经少用泡沫灭火器了，一般单位里配的都是干粉灭火器或二氧化碳灭火器。而水不是绝缘体，也不能用于电器设备的灭火。故正确答案为D。", "tag": "科技常识"},
{"id": "tech-258", "q": "发酵是人类较早接触的一种生物化学反应，如今在食品工业、生物和化学工业中均有广泛应用。以下没有用到发酵工艺的是：", "options": ["酱油", "醋", "蔗糖", "味精"], "a": 2, "e": ".【C】发酵即通过对微生物（或动植物细胞）进行大规模的生长培养，使之发生化学变化和生理变化，A、B、D三项都用到了发酵工艺，C项蔗糖是将甘蔗或甜菜用机器压碎，收集糖汁，过滤后用石灰处理，除去杂质，再用二氧化硫漂白；将经过处理的糖汁煮沸，抽去沉底的杂质，刮去浮到面上的泡沫，然后熄火待糖浆结晶成为蔗糖，没有发酵的过程。本题为选非题，故正确答案为C。", "tag": "科技常识"},
{"id": "tech-259", "q": "以下说法中，不正确的是：", "options": ["在加油站停车加油时，不能拨打手机", "室内装修应尽可能选择在冬季进行", "受到核辐射的人应适当服用稳定碘", "家用电冰箱的制冷剂氟利昂会破坏空气中的臭氧"], "a": 1, "e": ".【B】B项不正确，冬季施工，与其他季节相比，需要用到额外的建筑材料，例如冷冻剂，会释放出大量氨气，室内污染更为严重。同时，由于冬季天气寒冷，人们室内活动时间增多，户外活动大量减少，导致室内污染物对人体的危害比其他季节更大，皮肤病、呼吸道系统疾病以及心血管疾病的发病率也随之增高。本题为选非题，故正确答案为B。", "tag": "科技常识"},
{"id": "tech-260", "q": "以下洗剂用品，最为环保的是：", "options": ["洗衣液", "洗衣粉", "肥皂", "衣物漂白剂"], "a": 2, "e": ".【C】洗衣粉、洗衣液是化学合成物，虽然随着技术的进步，洗衣液使用表面活性剂等中性原料后，其生物降解度在", "tag": "科技常识"},
{"id": "tech-261", "q": "日常生活中有许多省电的技巧。以下做法，不能省电的是：", "options": ["经常清洗空调进风口处的过滤网", "用同等亮度的LED 灯代替节能灯", "把新、旧电池接在一起使用", "冰箱内尽量多放或放满食物"], "a": 2, "e": ".【C】C选项不正确，如果把新、旧电池接在一起用，旧电池内的电阻实际上就成了电路中的一个电器，会把电白白耗掉，而且一直消耗到新、旧电池的电压相等时才停止，所以此做法不能省电。本题为选非题，故正确答案为C。", "tag": "科技常识"},
{"id": "tech-262", "q": "发生雷暴时，有时会下冰雹。大的冰雹甚至可以击穿飞机的机翼，砸伤地面的动植物。影响冰雹大小的主要因素是：", "options": ["风速", "云团", "上升气流", "空气中的固体颗粒"], "a": 2, "e": ".【C】冰雹来自对流特别旺盛的对流云（积雨云）中。积雨云中的上升气流要比一般雷雨云强，小冰雹是在对流云内由雹胚和过冷水滴上下数次碰撞而增长起来的，当积雨云中的上升气流支托不住时就下降到地面。由上述可知，上升气流起到了支托作用，使冰雹不断变大。故正确答案为C。", "tag": "科技常识"},
{"id": "tech-263", "q": "下列说法错误的一项是：", "options": ["日常生活中的无糖食品一般是指不含蔗糖、葡萄糖等的甜味食品", "人的汗液发臭主要是由于细菌分解了汗液中的有机物导致的", "人补充钙时加服维生素D 可以促进钙剂的吸收", "肌肉系统是负责人体各类运动功能的重要系统"], "a": 3, "e": ".【D】无糖食品一般是指不含蔗糖（甘蔗糖和甜菜糖）、葡萄糖、麦芽糖、果糖等的甜味食品，A说法正确。由于空气污染和在健身房共用器械等问题，存在于皮肤表层的大量细菌、寄生虫等，会分解汗液中的有机成分，产生各种有毒物质，释放出有异味的气体，B说法正确。维生素D可以提高肌体对钙、磷的吸收，故C说法正确。人体各类运动功能都是在神经系统支配下，通过肌肉收缩而实现的，D表述不够准确。本题为选非题，故正确答案为D。", "tag": "科技常识"},
{"id": "tech-264", "q": "日常生活中的污染现象可以分为不同的种类。下列污染不属于物理性污染的是：", "options": ["遗弃的废旧荧光灯管", "夜间刺眼的汽车灯光", "歌厅震耳欲聋的音乐", "变压器的电磁波"], "a": 0, "e": ".【A】物理性污染是指由物理因素引起的环境污染，如放射性辐射、电磁辐射、噪声、光污染等，显然B、C、D项都属于物理性污染。本题为选非题，故正确答案为A。", "tag": "科技常识"},
{"id": "tech-265", "q": "关于日常生活用品，下列说法正确的是：", "options": ["牙膏的成分中含有摩擦剂", "添加了高级脂肪酸的肥皂，质量更好一些", "加碘盐应注意防潮，保存在有阳光照射、干燥通风的地方", "“生抽”是酿造酱油，而“老抽”是配制酱油"], "a": 0, "e": ".【A】A项正确：牙膏成分包括摩擦剂、保湿剂、表面活性剂等。B项错误：肥皂的主要成分是高级脂肪酸盐，添加高级脂肪酸与肥皂质量没有关系。C项错误：加碘盐应该放置在干燥、避光、避高温处。D项错误：“生抽”和“老抽”都是经过酿造发酵的酱油。故正确答案为A。", "tag": "科技常识"},
{"id": "tech-266", "q": "下列关于医学常识的说法，错误的是：", "options": ["临床上一般以红血球蛋白的浓度值作为诊断贫血的依据", "卡介苗是一种疫苗，一般在婴儿出生后接种，可以预防结核病", "游泳时应避免将水咽入口中，以免水通过鼻咽进入中耳引发中耳炎", "人体骨密度在达到高峰值后会逐渐下降，男性下降幅度较女性大"], "a": 3, "e": ".【D】D项表述错误，年龄与性别是影响人骨矿含量的因素之一。婴儿至青春期骨矿物质含量随年龄增长而增加，且无明显性别差异。青春期之后，骨矿含量的增加男性较女性显著，30~40岁达到最高峰值。以后骨矿物质含量随年龄的增长逐渐下降，女性下降幅度较男性大，而并非男性下降幅度较女性大。本题为选非题，故正确答案为D。", "tag": "科技常识"},
{"id": "tech-267", "q": "一个天真的孩子听妈妈讲故事。妈妈对他讲鲸鱼是现在生存在海洋里体积最大的动物，比大象大不知有多少。孩子天真地问妈妈：“那鲸鱼一定是最大的鱼了？”妈妈笑着说他错了，那么，孩子错在哪里呢：", "options": ["鲸鱼并不是海洋里现存的最大的动物", "鲸鱼不生活在海洋里", "鲸鱼其实不是鱼，是一种哺乳动物", "现在已经不存在鲸鱼了"], "a": 2, "e": ".【C】孩子的问题是鲸鱼是不是最大的鱼，妈妈说他错了，是对这句话的否定，这说明，鲸鱼不是最大的鱼。实际上，鲸鱼是一种哺乳动物。故正确答案为C。", "tag": "科技常识"},
{"id": "tech-268", "q": "下雨的时候，闪电一过，接着就要打雷。对这种现象正确的解释是：", "options": ["雷声是闪电后形成的", "雷是闪电的附属物", "闪电和雷声同时产生，但闪电比雷声快", "打雷自然而然跟着闪电"], "a": 2, "e": ".【C】本题考查生活中的物理现象。雷电是云层在运动过程中产生的电荷在放电时产生的电火花，既有光也有声。之所以先出现闪电后听到雷声，是因为在空气中，光的传播速度比声音的传播速度快。故正确答案为C。", "tag": "科技常识"},
{"id": "tech-269", "q": "下列关于合理饮食有利于健康的说法，正确的是：", "options": ["没有水就没有生命", "饮用水越纯净越好", "调味剂和营养剂加得越多越好", "养成良好的饮食习惯，多吃蔬菜、水果"], "a": 3, "e": ".【D】本题考查合理饮食与健康的关系。A项错误，与题干无关；B项错误，饮用水并非越纯净越好，人体中有些元素是从饮水中获得的，纯度过高的水中不含人体所需的微量元素和矿物质，不利于人体健康；C项错误，调味剂和营养剂有一定的营养价值，但过量使用会破坏营养的均衡，甚至会影响健康，导致疾病；D项正确，蔬菜和水果含有人体必须的多种维生素和矿物质，大部分蔬菜和水果属于碱性食物，多吃有利于调节身体的酸碱平衡系统，促进健康。故正确答案为D。", "tag": "科技常识"},
{"id": "tech-270", "q": "下列表述正确的是：", "options": ["父母的血型分为A 和O 型，其子女只会是A 或O 型", "吸气时，人肺容积增大，肺内气压高于大气压", "含酸味的水果一般为酸性食品，而乳酸、甜点一般是碱性食品", "艾滋病病毒能在蚊虫体内生存繁殖，会通过蚊虫叮咬传播给人类"], "a": 0, "e": ".【A】A项正确，由血型遗传规律表可知，父母的血型为A型和O型，子女的血型只会是A型或O型，不可能是B型或AB型；B项错误，人在吸气时，肺容量增大，肺内的气压低于外界大气压；C项错误，判断食物的酸碱性，依据的是食物进入人体后所形成的最终代谢物的酸碱性，而不是根据人们的味觉或根据食物溶于水中的化学性。水果大多数是碱性食品，乳酪、甜点则是强酸性食品；D项错误，艾滋病病毒在蚊虫体内会被蚊虫消化掉，无法在蚊虫体内生存、繁殖，因此蚊虫叮咬不会把艾滋病病毒传播给人类。故正确答案为A。", "tag": "科技常识"},
{"id": "tech-271", "q": "下列食品中，不属于发酵类食品的是：", "options": ["白酒", "饼干", "面包", "腐乳"], "a": 1, "e": ".【B】发酵食品是指人们利用有益微生物加工制造的一类食品，通常包括酒精饮料、谷物发酵制品、乳类发酵制品、豆类发酵制品等。白酒、面包、腐乳均属于发酵类食品。饼干是以小麦粉为主要原料，不属于发酵制品。故正确答案为B。", "tag": "科技常识"},
{"id": "tech-272", "q": "牙膏中最重要的成分是摩擦剂、洗涤剂与香料，其中洗涤剂的主要成分通常与（）的主要成分相同。", "options": ["漂白粉", "洗衣粉", "肥皂", "碳酸钙"], "a": 1, "e": ".【B】牙膏中的洗涤剂成分主要是表面活性剂，与洗衣粉中洗涤剂成分相同。故正确答案为B。", "tag": "科技常识"},
{"id": "tech-273", "q": "传统中药柜常设有“匣”、“斗”、“瓶”、“暗柜”几种容器。以下药品适合在“暗柜”中存放的是：", "options": ["质轻量大的药物", "容易挥发的药物", "粉面类的药物", "毒性强的药物"], "a": 3, "e": ".【D】中药柜存放药物有一句顺口溜：质轻量大易装匣，常用普通斗中装，挥发粉面细子瓶，暗柜独存贵毒麻。A项错误，应放在匣中；B、C项错误，应放在瓶中；D项正确，应放在暗柜中。故正确答案为D。", "tag": "科技常识"},
{"id": "tech-274", "q": "在铅笔上，常常印着“6B”“4H”或者“HB”的字样，这些字样代表着铅笔的软硬。“B”代表软，“H”代表硬，前边的阿拉伯数字代表软硬的程度，“HB”则代表软硬适中。如果你要选择铅笔分别用来画画、写字、制图，相应选择的铅笔类型分别为：", "options": ["6H 4B HB.", "HB 6H 4B.", "4B HB 6H.", "HB 4B 6H."], "a": 2, "e": ".【C】铅笔的B值越大则越软越浓，H值越大则越硬越淡。软铅笔铅质松，轻附纸面，便于修改，硬铅笔适合深入刻画细部。画画宜用较软的铅笔（4B），制图则应该用较硬的铅笔（6H），写字则适用软硬适中的铅笔（HB）。故正确答案为C。", "tag": "科技常识"},
{"id": "tech-275", "q": "乘飞机时乘务员常会拿糖果给乘客吃，其主要目的是：", "options": ["缓解乘客在飞机起落时紧张情绪", "担心乘客血糖过低", "缓解耳气压变化带来的不适感", "一份小礼物"], "a": 2, "e": ".【C】飞机在天空中不断升高，空气越来越稀薄，大气压力迅速降低，机舱内气压的下降，会引起人体耳朵出现堵塞的感觉，少数人还可能会产生短暂的听力障碍及耳道疼痛。因此，在飞机起飞和降落时吃些糖果等食品，不断进行咀嚼和吞咽动作，耳咽管即会随时开合，空气就可自由地出入中耳腔，使得中耳内压和外界大气压力保持正常平衡状态，耳部不适感就会减轻或消失。故正确答案为C。", "tag": "科技常识"},
{"id": "tech-276", "q": "下列可以缓解城市内涝的措施是：", "options": ["将水泥路面改为柏油路面", "铺设人行道时使用透水砖", "兴建人行天桥", "拓宽城市道路"], "a": 1, "e": ".【B】铺设人行道时使用透水砖，下雨时雨水可以渗透到土壤里，可以缓解城市内涝。故正确答案为B。", "tag": "科技常识"},
{"id": "tech-277", "q": "下列说法错误的是：", "options": ["高浓度糖液破坏微生物的细胞结构，可延长食品保存期", "山梨酸钾是一种食品添加剂，可用于增加食品的风味", "茶多酚能够抑制自由基的活性，可以作为食品防腐剂", "β-胡萝卜素可以作为食用性色素，可以用于食品调色"], "a": 1, "e": ".【B】B项错误，山梨酸钾能有效地抑制霉菌、酵母菌和好氧性细菌的活性，还能防止肉毒杆菌、葡萄球菌、沙门氏菌等有害微生物的生长和繁殖，但对厌氧性芽孢菌与嗜酸乳杆菌等有益微生物几乎无效，其抑止发育的作用比杀菌作用更强，所以可以作为食品添加剂，达到有效地延长食品的保存时间，并保持原有食品的风味的作用，但不能增加食品的风味。本题为选非题，故正确答案为B。", "tag": "科技常识"},
{"id": "tech-278", "q": "下列有关生活常识的叙述，不正确的是：", "options": ["不慎扭伤关节，不应立即揉搓按摩", "洪水来袭，如来不及逃生可向高处转移等候营救", "火灾逃生时，应用湿毛巾或口罩蒙鼻，匍匐着撤离", "电热毯折叠加热，升温快，且便于热量保存"], "a": 3, "e": ".【D】电热毯严格禁止折叠使用。折叠电热毯致使一些元件损坏，线路不畅通，容易导致漏电，所以使用电热毯的过程中，应经常检查电热毯是否有堆集、打褶现象，如有，应将皱褶摊平后再使用。本题为选非题，故正确答案为D。", "tag": "科技常识"},
{"id": "tech-279", "q": "2011 年，一场关于PM2.5 的讨论，牵动着国人神经。PM2.5 是指：", "options": ["极细颗粒物", "细颗粒物", "微颗粒物", "超微颗粒物"], "a": 1, "e": ".【B】PM2.5是指大气中直径小于或等于2.5微米的细颗粒物，也称为可入肺颗粒物。故正确答案为B。", "tag": "科技常识"},
{"id": "tech-280", "q": "下列中暑处置方式错误的是：", "options": ["冷敷", "及时到医院就诊", "多喝水", "将患者转移到阴凉通风处"], "a": 2, "e": ".【C】中暑后可采取以下处理方式：（1）及时将患者送往医院就诊。（2）让患者脱离高温环境,迅速将中暑者转移至阴凉通风处休息。（3）冷敷。应在头部、颈部、腋窝等大动脉血管部位放置冰袋，并可用冷水或", "tag": "科技常识"},
{"id": "tech-281", "q": "生态整体主义追求的最高价值是：", "options": ["发展人居环境", "人类整体利益", "自由主义", "生态系统整体利益"], "a": 3, "e": ".【D】生态整体主义强调的是把人类的物质欲望、经济的增长、对自然的改造和扰乱限制在能为生态系统所承受、吸收、降解和恢复的范围内。这种限制为的是生态系统的整体利益，而生态系统的整体利益与人类的长远利益和根本利益是一致的。生态整体主义的核心思想是：把生态系统的整体利益作为最高价值而不是把人类的利益作为最高价值。故正确答案为D。", "tag": "科技常识"},
{"id": "tech-282", "q": "小船匀速横渡一条河流，若船行驶到河中央时，水流速度突然变快，则：", "options": ["小船渡河时间减少", "小船渡河时间增加", "小船渡河时间不变", "小船无法到达对岸"], "a": 2, "e": ".【C】小船在匀速横渡河流的时候在竖直方向上的速度（V）不会发生变化，到河对岸的距离（S）也不会变化，根据公式T＝S/V，故时间（T）不会发生变化。这里值得注意的是，水流的快慢影响的只是小船在河流方向上的行驶距离，水流变快会加大这个距离，但是它并不影响过河的时间。故正确答案为C。", "tag": "科技常识"},
{"id": "tech-283", "q": "人们在剧烈运动后会感到非常口渴，这时为补充水分、恢复体力，适量饮用下列哪种饮料更为合适：", "options": ["淡盐水", "白开水", "茶饮料", "碳酸饮料"], "a": 0, "e": ".【A】人在剧烈运动过程中，身体通过排汗将大量热能及时散发掉，以保持体温的相对稳定。在机体大量排汗的同时，带走了不少无机盐，如钠、钾、镁等。这样势必引起机体疲乏无力，甚至肌肉痉挛或抽筋。因此，从事剧烈运动后，适当喝些淡盐水是必要的。故正确答案为A。", "tag": "科技常识"},
{"id": "tech-284", "q": "下列俗语或成语与蕴含的原理对应正确的是（）。", "options": ["三个和尚没水喝——华盛顿合作定律", "冤冤相报——刺猬效应", "鱼目混珠而傍名牌——挤出效应", "软绳可以捆硬柴——墨菲定律"], "a": 0, "e": ".【A】本题考查科技常识。三个和尚没水喝”，也是我们通常所说的“一个人是龙，两个人是熊，三个人是虫”。华盛顿合作定律说明，在管理中，合作是一个问题，如何合作更是一个问题。人与人的合作并不是简单的数量相加，而是会受到很多因素的干扰，关系非效能。相报、致使仇恨越来越深的社会心理效应。刺猬效应，说的是在寒冷的冬天里，两只刺猬要相依取暖，一开始由于距离太近，各自的刺将对方刺得鲜血淋漓，后来它们调整了姿势，相互之间保持了适当的距离，不但互相之间能够取暖，而且很好地保护了对方，强调人际交往沟通要保持恰当的距离。C项错误，“鱼目混珠而傍名牌”体现的是“搭便车”。“搭便车”亦称“免费搭车”，指不付成本而坐享他人之利的行为，比喻利用有关政策或有利条件为自己谋利。如果各企业一哄而上用一个知名商品的名称，便是“搭便车”行为，让质量低劣的产品流入市场，鱼目混珠，混淆消费者的视线，从而危害整个行业的发展。挤出效应是指政府支出的增加导致私人消费支出或投资支出的减少。D项错误，“软绳可以捆硬柴”体现的是南风效应。南风效应来源于法国作家拉封丹写过的一则寓言，说的是北风和南风比威力，看谁能把行人身上的大衣脱掉。北风首先发威，放出凛冽刺骨的寒风，结果行人把大衣裹得紧紧的，接着南风徐徐吹动，行人顿觉风和日丽，春暖上身，于是解开钮扣，继而脱掉大衣，显然，南风获得了胜利。南风效应比喻人使用柔软的手段，往往能制服强硬的敌手，或性情温和的人往往能迫使性情刚烈的人就范。墨菲定律根本内容是：如果事情有变坏的可能，不管这种可能性有多小，它总会发生。故正确答案为A。", "tag": "科技常识"},
{"id": "tech-285", "q": "铺设盲道拐弯的地方，应该选择下列哪种盲道砖（）。", "options": ["A", "B", "C", "D"], "a": 2, "e": ".【C】本题考查科技常识。盲道砖是为盲人安全出行、行路方便提供的道路设施。一般由三类砖铺就，一类是条形方向引路砖，引导盲人放心前行，称为行进盲道砖，或盲道方向引路砖；一类是带有圆点的提示砖，提示盲人前面有障碍，该转弯了，称为提示盲道砖，或盲道方位引路砖；最后一类是盲道危险警告引路砖，圆点较大，警视不要超越，前面危险。所以，BD两种盲道砖不存在。A为行进盲道砖，引导盲人放心前行。C为提示盲道砖，提示盲人前面该转弯了。故正确答案为C。", "tag": "科技常识"},
{"id": "tech-286", "q": "下列说法不正确的是（）。", "options": ["脊髓灰质炎疾病也就是我们常说的小儿麻痹症", "超声波可以用来制作加湿器", "青霉素是最重要的抗生素之一", "味精的制作没有用到发酵工艺"], "a": 3, "e": ".【D】本题考查科技常识。A项正确，脊髓灰质炎是由脊髓灰质炎病毒引起的严重危害儿童健康的急性传染病，脊髓灰质炎病毒为嗜神经病毒，主要侵犯中枢神经系统的运动神经细胞，以脊髓前角运动神经元损害为主。患者多为1～6岁儿童，主要症状是发热，全身不适，严重时肢体疼痛，发生分布不规则和轻重不等的弛缓性瘫痪，俗称小儿麻痹症。B项正确，超声波加湿器主要是采用高频的震荡，再通过雾化片的高频震动使得加湿器中的水被抛离水面产生飘逸的水雾，达到空气加湿的目的。C项正确，青霉素是最重要的抗生素之一，有阻止多种细菌生长的优异功能，即使三千万倍的稀释，仍有疗效，适用于医治因葡萄球菌和链球菌等引起的血毒症。因最初是从青霉的培养液中取得的，因此被称为“青霉素”。D项错误，味精又称味素，是采用微生物发酵的方法由粮食制成的一种现代调味品，主要是以粮食为原料经发酵提纯的谷氨酸钠结晶，因此用到了发酵工艺。本题为选非题，故正确答案为D。", "tag": "科技常识"},
{"id": "tech-287", "q": "重金属污染指由重金属或其化合物造成的环境污染。主要是因为人类活动导致环境中的重金属含量增加，超出正常范围，直接危害人体健康，并导致环境质量恶化。下列关于重金属污染的说法错误的一项是（）。", "options": ["日本的水俣病是由重金属汞污染所引起的", "重金属含量可以通过食物链富集，造成公害", "儿童长时间啃咬铅笔芯会引起重金属铅中毒", "废旧电池的乱弃会造成重金属镉污染"], "a": 2, "e": ".【C】本题考查生活常识，主要涉及重金属污染的相关内容。A项正确，水俣病是因食入被有机汞污染的河水中的鱼、贝类所引起的以甲基汞为主的有机汞中毒或是孕妇吃了被有机汞污染的海产品后引起婴儿患先天性水俣病，是有机汞侵入脑神经细胞而引起的一种综合性疾病。因1953年首先发现于日本熊本县水俣湾附近的渔村而得名，水俣病是慢性汞中毒的一种类型。B项正确，由于在重金属的开采、冶炼、加工过程中，造成不少重金属如铅、汞、镉、钴等进入大气、水、土壤引起严重的环境污染。如随废水排出的重金属，即使浓度小，也可在藻类和底泥中积累，被鱼和贝类体表吸附，产生食物链浓缩，从而造成公害。C项错误，铅笔芯的主要成分是石墨和黏土，并不是铅，故该说法错误。D项正确，废旧电池中镉含量较高，也存在于水果和蔬菜中，尤其是蘑菇，在奶制品和谷物中也有少量存在。本题为选非题，故正确答案为C。", "tag": "科技常识"},
{"id": "tech-288", "q": "下列生活常识中，小明做法正确的是（）。", "options": ["备考省考的小明，为缓解焦虑，长时间戴耳机听音乐", "小明晨跑不小心扭伤脚踝，立即回家将冰块直接敷在患处", "3 年前打过狂犬疫苗的小明被狗咬伤后，无需再接种疫苗", "被毒蛇咬伤后的小明拒绝使用创可贴止血"], "a": 3, "e": ".【D】本题考查生活常识。A项错误，耳机的振动片更靠近耳膜，若长时间戴耳机会导致声波能量集中刺激内耳，可能会造成耳内血液循环不良、耳鸣、内耳毛细胞坏死甚至听神经伤害。耳廓长期被耳机压迫，耳道长期被耳塞堵住，会导致局部血液循环不畅，造成耳廓疼痛，严重者甚至会导致耳廓软膜炎。B项错误，脚踝扭伤应立即停止行走、运动等活动，取坐位同时将背包、衣物等把足部垫高，帮助静脉回流以减少疼痛和肿胀。受伤48小时内用冰袋或冷毛巾敷于局部，减少出血或渗出，从而减轻疼痛。但是注意不要直接将冰块敷在患处，可以使用湿毛巾包裹冰块，以免冻伤。C项错误，根据卫生部《狂犬病暴露预防处置工作规范2009版》：“一般情况下，全程接种狂犬病疫苗后体内抗体水平可维持至少1年。如再次暴露发生在免疫接种过程中，则继续按照原有程序完成全程接种，不需加大剂量；全程免疫后半年内再次暴露者一般不需要再次免疫；全程免疫后半年到1年内再次暴露者，应当于0和3天各接种1剂疫苗；在1-", "tag": "科技常识"},
{"id": "tech-289", "q": "关于急救方法，不恰当的是（）。", "options": ["为出血伤员止血时，拇指压住近心端动脉", "没有绷带时，用长筒尼龙袜代替绷带包扎", "烧伤伤员口渴时，可让其喝少量淡盐水", "抢救骨折伤员时，可适当调整骨折部位姿势"], "a": 3, "e": ".【D】本题考查科技常识。A项正确，动脉血管中血液流动是依靠心脏搏动来完成，如果动脉血管出血，压迫近心端动脉就可以降低心脏对血液的传递，达到减少出血的目的。B项正确，在没有绷带急救伤员的情况下，可用毛巾、手帕、床单、长筒尼龙袜子等代替绷带包扎。C项正确，烧伤有创面，伤员会损失体液，而人的体液本来就含有盐分，因此烧伤伤员喝少量淡盐水可迅速补充体液。D项错误，面对骨折伤员，抢救时一定要确保不会造成二次伤害，即不能让骨折情况加重或恶化，所以不能调整骨折部位姿势。骨折发生后，应当迅速用夹板固定患处，但不应固定过紧，以免压迫血管引起淤血。没有木板可用树枝、擀面杖、雨伞、报纸卷等物品代替。本题为选非题，故正确答案为D。", "tag": "科技常识"},
{"id": "tech-290", "q": "在生活中，下列做法错误的是（）。", "options": ["用灼烧并闻气味的方法鉴别蚕丝和棉线", "用牙膏清除水龙头下方的水垢", "用淀粉鉴别食盐是否含有碘", "用卫生纸去除冰箱的异味"], "a": 2, "e": ".【C】本题考查科技常识。A项正确，蚕丝的主要成分是蛋白质，灼烧后有烧焦羽毛的味道，而棉花的主要成分是纤维素，灼烧后气味很淡（类似于烧纸的气味），所以可以用灼烧并闻气味的方法来鉴别蚕丝和棉线。B项正确，牙膏的成分中有摩擦剂（一般是碳酸钙粉末），利用这种很细的摩擦颗粒，通过物理方法，可以轻松去除一些难以清除的污垢，因此可以用牙膏清除水垢。C项错误，碘单质遇淀粉会变蓝色，但食盐中的碘是以碘酸钾的形式存在的，所以用淀粉是鉴别不了食盐是否含有碘的。D项正确，卫生纸的吸附性很强。将卫生纸放入冰箱中，卫生纸不仅会吸附冰箱中食物产生的臭味，而且还会除湿。本题为选非题，故正确答案为C。", "tag": "科技常识"},
{"id": "tech-291", "q": "下列俗语与对应的成语，二者本意所指属于同一物理现象的是：", "options": ["宝剑锋从磨砺出——百炼成钢", "酒香不怕巷子深——近朱者赤", "小小秤砣压千斤——举重若轻", "近水楼台先得月——海市蜃楼"], "a": 1, "e": ".【B】物质是由分子组成的，分子在不停地做无规则运动，且分子间存在相互作用的引力和斥力。由于分子在不停地做无规则运动，故不同物质的分子会彼此进入对方，发生扩散现象。题干中的“酒香不怕巷子深”和“近朱者赤”所包含的都是分子运动这一物理现象。故正确答案为B。", "tag": "科技常识"},
{"id": "tech-292", "q": "下列有关医学的说法错误的是（）。", "options": ["春天是急性心梗的高发期", "诺如病毒具有明显的季节性", "原发性高血压高于继发性高血压发病率", "血友病、哮喘和乙型肝炎均是遗传疾病"], "a": 3, "e": ".【D】本题考查科技常识。A项正确，急性心肌梗死是冠状动脉急性、持续性缺血缺氧所引起的心肌坏死。常见的诱因有：过劳、激动、暴饮暴食、寒冷刺激、便秘、吸烟、大量饮酒等。突然的寒冷刺激也可能诱发急性心肌梗死，因此，冬春寒冷季节是急性心肌梗死发病较高的原因之一。B项正确，诺如病毒，又称诺瓦克病毒，是人类杯状病毒科中诺如病毒属的一种病毒。是一组形态相似、抗原性略有不同的病毒颗粒。诺如病毒具有明显的季节性，人们常把它称为“冬季呕吐病”。根据2013年发表的系统综述，全球约的病例和约的发生在冬季（北半球是12月-次年2月，南半球是6-8月），约的病例和约的出现在凉爽的季节（北半球是10月-次年3月，南半球是4-9月）。C项正确，基于目前的医学发展水平和检查手段，能够发现导致血压升高的确切病因，称之为继发性高血压；反之，不-，但随着医学发展水平和检查手段的不断进展，继发性高血压的比例将不断增加，原发性高血压的比例会不断下降。D项错误，1.血友病为一组遗传性凝血功能障碍的出血性疾病，其共同的特征是活性凝血活酶生成障碍，凝血时间延长，终身具有轻微创伤后出血倾向，重症患者没有明显外伤也可发生“自发性”出血。2.哮喘是一种具有复杂性状的，具有多基因遗传倾向的疾病。其特征为：①外显不全，②遗传异质化，③多基因遗传，④协同作用。3.乙型病毒性肝炎是由乙型肝炎病毒引起的以肝脏病变为主的一种传染病。乙型肝炎病毒最主要通过血液传播，最重要的传播方式是母婴垂直传播和医源性感染，不具有遗传性。本题为选非题，故正确答案为D。", "tag": "科技常识"},
{"id": "tech-293", "q": "中药药材的药性有寒凉和温热之分，下列中药属于热性药的是：", "options": ["鹿茸", "黄连", "连翘", "柴胡"], "a": 0, "e": ".【A】本题考查科技常识。A项正确，根据《中国药典》：鹿茸为鹿科动物梅花鹿或马鹿的雄鹿未骨化密生茸毛的幼角，性味甘、咸，温，属于热性药。功能主治为壮肾阳，益精血，强筋骨，调冲任，托疮毒等。B项错误，根据《中国药典》：黄连为毛茛科植物黄连、三角叶黄连或云连的干燥根茎，性味苦，寒，属于寒性药。功能主治为清热燥湿，泻火解毒等。C项错误，根据《中国药典》：连翘为木犀科植物连翘的干燥果实，性味苦，微寒，属于寒性药。功能主治为清热解毒，消肿散结等。D项错误，根据《中国药典》：柴胡为伞形科植物柴胡或狭叶柴胡的干燥根，性味苦，微寒，属于寒性药。功能主治为和解表里，疏肝，升阳等。故正确答案为A。", "tag": "科技常识"},
{"id": "tech-294", "q": "下列与汽车有关的说法错误的是：", "options": ["手动挡和自动挡汽车的主要区别在于是否人为控制离合装置", "冬天路面结冰时在车轮上挂铁链是为了增大摩擦", "遥控钥匙通过发射无线电波控制车门的开关", "手刹的制动原理是切断汽车的动力系统"], "a": 3, "e": ".【D】D项错误：手刹属于辅助制动系统，主要借助人力，是为了防止停车时车辆自行溜车而设立的。手刹是用来锁死传动轴从而使驱动轮锁死的；而能够切断汽车动力系统的是离合器。本题也可借助常识来判断，如影视作品中经常出现在斜坡上停放的车辆由于忘记拉手刹而下滑的桥段，说明切断动力并不是手刹的制动原理。该项当选；A项正确：手动挡的车有离合踏板，而自动挡的车没有离合踏板。在开车时，自动挡车换挡时不需要踩离合器，而手动挡需要踩下离合器才能换挡，排除；B项正确：冬天路面结冰打滑，挂铁链可以增大摩擦力，防止汽车打滑，排除；C项正确：遥控钥匙的工作原理为：先从钥匙发出微弱的无线电波，由汽车天线接收该电波信号，经电子控制单元识别信号代码，再由该系统的执行器执行开锁或闭锁的动作，排除。本题为选非题，故正确答案为D。", "tag": "科技常识"},
{"id": "tech-295", "q": "在日常生活中，下列各项影响食品腐败变质速度的因素中，起最主要作用的是：", "options": ["食品自身的成分", "食品所含的水分", "储存食品的环境温度", "储存食品的环境湿度"], "a": 2, "e": ".【C】本题考查科技常识。引起食物腐败变质有多种原因，比如微生物、食物中的酶等等，但最主要影响因素还是微生物。因此影响食物腐败变质速度主要是看微生物的生长繁殖速度。影响微生物生长的主要因素有温度、氧气、辐射、渗透压等等。其中，温度的影响最大，主要是因为微生物的代谢活动在较小的温度范围内波动就会有很大的变化。故正确答案为C。", "tag": "科技常识"},
{"id": "tech-296", "q": "雷雨天躲在室内，有时也容易遭到雷击。下列关于室内预防雷击的说法，错误的是：", "options": ["关闭门窗可以阻止球形雷电进入", "靠墙壁的位置比房间中央更安全", "不宜靠近电器设备以及使用电器", "不使用淋浴冲凉或触摸金属管道"], "a": 1, "e": ".【B】雷电是常见的暴雨灾害天气，室内预防雷击要做到“三不宜”：不宜敞开门窗（关闭门窗可以阻止球形雷的进入）；不宜使用淋浴冲凉或触摸金属管道；不宜靠近建筑物外墙、电器设备以及使用电器。A、C、D三项表述正确，B项表述错误，打雷时不宜靠近建筑物外墙，房间中央的位置比靠墙位置安全。本题为选非题，故正确答案为B。", "tag": "科技常识"},
{"id": "tech-297", "q": "下列关于土壤污染及其治理的说法，不正确的是", "options": ["土壤污染会影响江河湖海的水质", "有些污染物可能永久残留在土壤中", "一些植物可有效降低土壤重金属污染", "治理土壤污染的主要方式是灌溉清洗"], "a": 3, "e": ".【D】本题考查科技常识。土壤污染是指因人为因素导致某种物质进入陆地表层土壤，引起土壤化学、物理、生物等方面特性的改变，影响土壤功能和有效利用，危害公众健康或者破坏生态环境的现象。A项正确，由于一些能溶于水的污染物，可从土壤中淋洗到地下水里，使得地下水受到污染；另一些悬浮物及土壤所吸附的污染物，可随地表径流迁移，造成地表水污染。因此，土壤污染会影响到江河湖海的水质。B项正确，由于土壤中的有些污染物不易分解，因此可能永久残留在土壤中。C项正确，针对土壤污染物的种类，可以种植有较强吸收力的植物，降低有毒物质的含量，例如羊齿类铁角蕨属的植物能吸收土壤中的重金属。D项错误，对土壤污染的治理，首先要减少农药使用。同时还要采取防治措施，如通过生物降解净化土壤。此外，还可以通过增施有机肥、改变耕作制度、换土、深翻等手段，治理土壤污染。本题为选非题，故正确答案为D。", "tag": "科技常识"},
{"id": "tech-298", "q": "下列说法中，正确的是：", "options": ["鱼在水中能自由沉浮，是因为有鱼鳍", "“黄山毛峰”是绿茶", "秦岭的北坡有三十六峪", "南美洲唯一以葡萄牙语作为官方语言的国家是智利"], "a": 1, "e": ".【B】A项错误，鱼在水中能自由沉浮，是因为有鱼鳔而不是鱼鳍。B项正确，“黄山毛峰”是绿茶。C项错误，秦岭的北坡有七十二峪而非三十六峪。D项错误，智利是以西班牙语为官方语言，而不是葡萄牙语。故正确答案为B。", "tag": "科技常识"},
{"id": "tech-299", "q": "下列与雪有关的说法正确的是：", "options": ["大气中有足够的凝结核是形成降雪的必要条件", "食盐可作为融雪物质，是因为盐水的凝固点比纯水高", "“下雪不冷化雪冷”是因为凝固吸热，有降温制冷作用", "“六月飞雪”是文学作品杜撰的场景，不可能在我国境内出现"], "a": 0, "e": ".【A】降雪的形成条件有两个：一是大气中含有足够的凝结核，二是要有充分的水汽，故A项正确；食盐融雪的原理是盐水的凝固点比纯水的低，故B项错误；“下雪不冷化雪冷”是因为融化吸热，温度降低，故C项错误；夏季高空有较强的冷气流是有可能导致六月飞雪的，我国有部分地区处于寒温带，六月温度也较低，故D项错误。故正确答案为A。", "tag": "科技常识"},
{"id": "tech-300", "q": "2016 年9 月17 日是全民国防教育日，北京市五环路外区域试鸣防空警报，这是本市第四次大规模鸣响防空警报。关于防空警报，下列说法中不正确的是：", "options": ["防空警报信号分为预先警报、空袭警报、解除警报", "战时用于在城市受到空袭威胁时鸣响的提醒人们防空的警报", "战时是各级政府实施人民防空指挥、组织人民疏散的基本手段", "听到警报时在公共场所的居民，应立即回家，再次听到指令后可到临时疏散地域掩蔽"], "a": 3, "e": ".【D】本题考查了生活常识中的防空警报。防空警报是城市防空工程的重要组成部分，平时用于抗灾救灾和突发事故情况下的灾情预报和紧急报知。战时用于人民防空，是各级人民政府实施人民防空指挥，组织人员疏散的基本手段，是在城市受到空袭威胁时鸣响的提醒人们防空的警报。A项正确：防空警报分为预先警报、空袭警报和解除警报这三种。预先警报：鸣响36秒，停24秒，反复3遍为一个周期，时间3分钟；空袭警报：鸣响6秒，停6秒，反复15遍为一个周期，时间3分钟；解除警报：连续鸣响一长声，时间3分钟；B项正确：防空警报战时用于人民防空，是各级人民政府实施人民防空指挥，组织人员疏散的基本手段，是在城市受到空袭威胁时鸣响的提醒人们防空的警报；C项正确：同B项；D项错误：听到警报后市民应立即停止一切工作，把家中电源拉闸断电，关好煤气、熄灭火种、关好门窗，携带有效证件，生活必需品及防护器材，迅速撤离到附近地下防空避难所、人防工程、防空洞。听到解除警报指令后市民可以走出地下防空避难所、人防工程、防空洞，恢复正常工作。本题为选非题，故正确答案为D。", "tag": "科技常识"},
{"id": "tech-301", "q": "一辆客车夜晚行驶在公路上，发现油箱泄露，车厢里充满了汽油的气味，这时应该采取的措施是：", "options": ["洒水降温减少汽油蒸汽", "开灯查找漏油部位", "让车内的人集中到车厢后部", "打开所有车窗，严禁一切烟火，疏散乘客"], "a": 3, "e": ".【D】D项正确，打开车窗可以让车厢通风，释放车厢中的汽油味，严禁一切烟火可以防止泄露出来的汽油燃烧，及时疏散乘客能确保乘客生命安全。A项错误，汽油不溶于水，洒水降温无法减少汽油蒸汽。B项错误，车厢中有汽油味，说明存在汽油蒸汽。汽油具有可燃性，与空气混合后遇明火或电火花容易发生爆炸，而开灯可能产生电火花，因此不宜采取此措施。C项错误，遇到题干所述情况，应及时疏散乘客，保障乘客生命安全。故正确答案为D。", "tag": "科技常识"},
{"id": "tech-302", "q": "关于我国农村三级卫生服务网络，下列说法正确的是：", "options": ["主要承担预防保健、基本医疗、健康教育、计生指导等任务", "包括乡镇卫生院、村卫生室和家庭自我保健", "以让农民“看病不出乡镇”为发展目标", "以乡镇卫生院为基础"], "a": 0, "e": ".【A】农村三级卫生服务网络是指以县级医疗卫生机构为龙头、乡镇卫生院为主体、村卫生室为基础的卫生服务体系，B、D两项错误；农村三级卫生服务网络主要承担着预防保健、基本医疗、卫生监督、健康教育、计划生育技术指导等任务，为农民获得基本卫生服务提供保障，A项正确；我国农村三级卫生服务网络可缓解看病难、看病贵，实现农村医疗卫生发展目标，使农民“小病不出村、一般疾病不出乡、大病基本不出县”，C项错误。故正确答案为A。", "tag": "科技常识"},
{"id": "tech-303", "q": "飞机起飞时，乘客容易出现耳朵不舒服甚至些许疼痛的感觉，为缓解这一症状，乘务人员往往让乘客咀嚼口香糖，这可以起到的作用是（）。", "options": ["保证外界声波传之内耳", "防止听觉感受器受损", "保证听小骨的正常振动", "保持鼓膜内外气压平衡"], "a": 3, "e": ".【D】听觉的形成过程：外界的声波经过外耳道传到鼓膜，引起鼓膜的振动；振动通过听小骨传到内耳，刺激耳蜗内的听觉感受器，产生神经冲动；神经冲动通过与听觉有关的神经传递到大脑皮层的听觉中枢，就形成了听觉，内耳耳蜗含有听觉感受器。A选项飞机起飞时声音非常大，不需要保证传至内耳，错误；B选项听觉感受器已经到了内耳，咀嚼口香糖不会产生影响；C选项听小骨能把鼓膜的振动传给内耳,传导过程还像放大器一样，把声音信号放大十倍,所以即使很轻微的声音人们也能听到，是一种正常行为，与题意无关；D选项咀嚼口香糖的目的是使咽鼓管张开，以保持鼓膜内外的气压平衡，防止其损伤。故正确答案为D。", "tag": "科技常识"},
{"id": "tech-304", "q": "关于生活常识，下列说法错误的是：", "options": ["吃松花蛋时佐以食醋，是为了减少松花蛋的涩味", "电灯泡中加入少量红磷，是为了防止灯丝氧化", "纯碱使馒头稀松多孔，是因为化学反应产生二氧化碳", "千滚水不宜饮用，是因为其中的细菌含量会大大增加"], "a": 3, "e": ".【D】千滚水是指反复煮开的水，水在煮沸的过程中是会有杀菌功能的，而不是像题干表述的细菌增加，一般水在长期搁置过程中才会使得细菌增加，如隔夜水等。因此D项因果联系表述错误。本题为选非题，故正确答案为D。", "tag": "科技常识"},
{"id": "tech-305", "q": "医务人员在给病人打针前，往往会将已经注入注射筒的药水往外推射掉少许。这么做的最主要原因是：", "options": ["可以用此方式检测注射针管等有无异物堵塞，保证注射安全", "从药瓶抽取药水可能会产生一些泡沫，往外推射药水可以将其挤出", "从药瓶抽取药水难免会抽入少量空气，往外推射药水可以将其挤出", "用药瓶存放的药水，难免产生沉淀，用推射的方式能减少沉淀"], "a": 2, "e": ".【C】本题考查与医学相关的生活常识。医务人员在抽取药水时可能会不小心抽入少量的空气，如果空气混合着药水一起进入患者的血管内，空气可能会堵塞某些较细的血管，造成血液流速不畅，导致人体组织缺氧和功能异常，甚至危及生命。因此在注射前，必须把这部分空气彻底从针管里排出。而A项中的异物、B项中的泡沫、D项中的沉淀等，都不是主要原因，这些因素要么可以通过肉眼观察发现从而得以处理，要么不会严重危及人的生命。故正确答案为C。", "tag": "科技常识"},
{"id": "tech-306", "q": "下列哪一措施不能起到减少空气污染的作用：", "options": ["加快天然气等清洁能源利用", "尽可能使用低硫少灰的燃料", "鼓励步行，加强自行车交通系统建设", "发展高层建筑，提高城市容积率"], "a": 3, "e": ".【D】本题考查科技常识。A项正确，清洁能源即绿色能源，是指不排放污染物、能够直接用于生产生活的能源，它包括核能和可再生能源。天然气作为一种清洁能源，燃烧时产生的二氧化碳少于其他化石燃料，造成的温室效应较低，燃烧之后也没有废渣、废水。大力推广清洁燃料天然气，重点用于民用燃料及工业燃料的替代方面，对于我国一次能源以煤炭为主而带来的废气排放严重超标、酸雨成灾及温室效应等环境保护被动局面的改变，推进节能减排、减少大气污染将起到积极作用。B项正确，大气污染物的生成，与工业生产原料和燃料有直接关系。应当严格选择原料和燃料，尽可能使用低硫少灰的燃料，采取预处理措施，如洗煤脱硫、重油脱硫，或者建设焦炉，变煤为气焦双收，变有害物多的原料和燃料为无害少害的原料和燃料，依次降低硫和杂质的排放量，减少空气污染。C项正确，机动车尾气排放的二氧化碳、硫化物、氮氧化物、氟氯烃等使温室效应、光化学烟雾、臭氧层破坏和酸雨等大气环境问题日益严重。鼓励步行，加强自行车交通系统建设，倡导绿色出行理念，可以有效减少机动车的使用，既节约能源，提高能源利用效率，减少空气污染，又有益于健康，兼顾效率。D项错误，发展高层建筑，可以提高城市容积率和土地利用效率，缓解住宅供求矛盾，但与减少空气污染无关。本题为选非题，故正确答案为D。", "tag": "科技常识"},
{"id": "tech-307", "q": "关于心肺复苏，下列说法错误的是：", "options": ["患者晕倒后心跳微弱应立即进行心肺复苏", "给溺水者做心肺复苏不需要先使病人吐水", "人工呼吸吹气过大时会导致患者胸内压过高", "心脏骤停后4 分钟内是心肺复苏的黄金抢救时间"], "a": 0, "e": ".【A】本题考查科技常识。A项错误，心肺复苏是当病人停止呼吸和心脏骤停时，用人工呼吸和胸外按压进行抢救的一种技术。患者心跳微弱时，应当及时送至医院检查，若此时做胸外心脏按压可能会加重病情。B项正确，如果溺水者昏迷无反应，呼吸及脉搏消失，一定要第一时间拨打120，并立即启动心肺复苏至患者呼吸脉搏恢复或急救人员到达。溺水急救不要再控水，这是因为在争分夺秒的急救过程中，肺部进水的危害性不大，更重要的是恢复呼吸。控水法，如倒背、腹部冲击等其实并不能施救溺水者，控水只会拖延复苏，加重误吸，明显增加死亡率。对于溺水后心脏骤停，争分夺秒的心肺复苏是唯一有效的急救方式。C项正确，在进行人工呼吸若吹气过大时，会引起胸腔内压的过度上升，进而导致血流回流受阻和胸外按压时血流输出的下降。D项正确，在正常室温下，心脏骤停4分钟后脑细胞就会出现不可逆转的损害。因此，对于心脏骤停的患者，4分钟内进行心肺复苏救活率更高，又称“黄金4分钟”。本题为选非题，故正确答案为A。", "tag": "科技常识"},
{"id": "tech-308", "q": "目前，垃圾分类投放渐成民众共识，根据垃圾箱上的分类标识，以下垃圾投放错误的是：", "options": ["", "", "", ""], "a": 1, "e": ".【B】B项所示的分类标识为有害垃圾，而烂铁和玻璃属于可回收垃圾，故不可以投放在贴有该标识的垃圾箱中，B项符合题意。A项所示标识为可回收物，废纸、塑料均属于可回收物；C项所示标识为厨余垃圾，果皮、剩菜都属于厨余垃圾；D项所示标识为其他垃圾，烟头、灰土都列入其他垃圾中。A、C、D三项投放均正确。本题为选非题，故正确答案为B。", "tag": "科技常识"},
{"id": "tech-309", "q": "关于现代武器，下列说法错误的是：", "options": ["迫击炮通常配属装甲兵使用", "陆军航空兵以直升机为主要装备", "洲际弹道导弹是目前射程最远的导弹", "驱逐舰具有防空、反潜和对地攻击的综合作战能力"], "a": 0, "e": ".【A】装甲兵以坦克为基本装备，主要执行地面突击任务，是陆军的重要突击力量。迫击炮是一种炮身短、射角大、弹道弧线高、以座钣承受后座力、采用炮口装填、发射带尾翼弹的曲射滑膛火炮。射程较近，轻便灵活，能射击遮蔽物后方的目标，是一种支援和伴随步兵作战的有效的压制兵器，A项错误。B、C、D三项说法均正确。本题为选非题，故正确答案为A。", "tag": "科技常识"},
{"id": "tech-310", "q": "我国目前应对雾霾污染，改善空气质量的重要任务之一是控制PM2.5，PM2.5 是（）。", "options": ["在空气中（浓度）越高，质量越好", "与较粗的大气颗粒物相比，PM 2.5 粒径小、面积大、活性强，更易附带病毒、有害物质", "在大气中的滞留时间长，输送距离短", "直径小于等于2.5 纳米的细颗粒物"], "a": 1, "e": ".【B】PM2.5细颗粒物指环境空气中空气动力学当量直径小于等于", "tag": "科技常识"},
{"id": "tech-311", "q": "下列关于农业的说法正确的是：", "options": ["花生、大豆、向日葵和芝麻都属于油料作物", "农药在夏天中午气温较高时喷洒灭虫效果最好", "有机农作物通常种在便于运输的交通主干线附近", "追肥是农闲时期为调节土地所含养分而施用的肥料"], "a": 0, "e": ".【A】A项正确，花生、大豆、向日葵、芝麻都属于油料作物，分别可制作花生油、豆油、葵花油、芝麻油。B项错误，夏日中午太阳光照强，大多数害虫躲在叶片的背光面，甚至停止活动，药物喷洒后杀虫率低，而气温高、光照强易造成农药分解、挥发，降低药效，害虫嗅到药味逃之夭夭。C项错误，有机农作物要求其遵照特定的农业生产原则，在生产中不采用基因工程获得的生物及其产物，不使用化学合成的农药、化肥、生长调节剂、饲料添加剂等物质，遵循自然规律和生态学原理。交通干线附近化学、噪声污染较大，不符合有机农作物生产要求。D项错误，追肥的作用主要是为了供应作物某个时期对养分的大量需要，或者补充基肥的不足。故正确答案为A。", "tag": "科技常识"},
{"id": "tech-312", "q": "高温红色预警信号是气象部门通过气象监测在高温到来之前做出的预警信号，以下关于高温红色预警信号的描述正确的是：", "options": ["12 小时内最高气温将升至", "12 小时内最高气温将升至", "24 小时内最高气温将升至", "24 小时内最高气温将升至"], "a": 3, "e": ".【D】本题考查科技常识。高温预警信号分三级，分别以黄色、橙色、红色表示。其中，高温黄色预警信号是指连续三天日最高气温将在以上；高温橙色预警信号是指24小时内最高气温将升至以上；高温红色预警信号（最高级别）是指24小时内最高气温将升至以上。故正确答案为D。", "tag": "科技常识"},
{"id": "tech-313", "q": "下列疾病与其部分临床表现对应错误的是：", "options": ["糖尿病——多饮、多尿、多食、疲乏无力", "水俣病——麻木、惊厥、精神迟钝、视力障碍", "甲亢症——眩晕、嗜睡、厌食、肌肉无力、记忆力减退", "脑中风——呕吐、流涎、意识障碍、一侧肢体感觉异常"], "a": 2, "e": ".【C】A项正确，糖尿病是一组以高血糖为特征的代谢性疾病。患者临床表现主要为：（1）多饮、多尿、多食和消瘦。严重高血糖时出现典型的“三多一少”症状，多见于1型糖尿病。（2）疲乏无力，肥胖。多见于2型糖尿病。B项正确，水俣病是因食入被有机汞污染河水中的鱼、贝类所引起的甲基汞为主的有机汞中毒或是孕妇吃了被有机汞污染的海产品后引起婴儿患先天性水俣病，是有机汞侵入脑神经细胞而引起的一种综合性疾病。主要是表现为神经精神症状：（1）肢体表现：感觉障碍、疼痛、麻木、无力、步行困难、共济失调、偏瘫、震颤等。（2）精神症状：精神迟钝、性格异常、智力迟钝、大发作性癫痫、发笑、意识模糊、惊厥等。（3）其他神经系统障碍：咀嚼吞咽困难、言语不清、耳聋、视力障碍、斜视、畏光等。C项错误，甲亢症是由多种原因引起的甲状腺激素分泌过多所致的一组常见内分泌疾病。主要临床表现为多食、消瘦、杂音等为特征，严重的可出现甲亢危相、昏迷甚至危及生命。因此，选项中临床表现说法错误。D项正确，脑中风是一组以脑部缺血及出血性损伤症状为主要临床表现的疾病。脑中风的症状包括：（1）头痛：无论是脑出血或脑梗死，头痛非常常见，亦是一个重要的脑中风症状和信号。（2）呕吐：一般是伴随头痛一起出现的，也非常常见，其特点是多为喷射状呕吐。如遇有呕吐咖啡色（酱油样或棕黑色）液体，表示病情非常严重。（3）眩晕：眩晕还多伴有呕吐或耳鸣，是脑中风的症状中比较常见的。（4）一侧肢体和面部的感觉异常。（5）口角流涎（流口水）：出现口角斜、流口水或食物从口角流出的现象，要引起足够的重视。（6）突发的视感障碍：表现为看不见左或右的物体或视觉缺损，也可以表现为一过性的眼前发黑或眼前突然飞过一只蚊子的感觉。（7）突发的言语不清和吞咽呛咳症状：表现为病人说话不清，吐词困难，喝水或吞咽时呛咳。（8）意识障碍：表现为神志模糊不清、呼吸不应、打呼噜，严重的可出现深度昏迷。本题为选非题，故正确答案为C。", "tag": "科技常识"},
{"id": "tech-314", "q": "下列做法正确的是：", "options": ["用“201 不锈钢”制成的锅炒菜", "用家用“84 消毒液”对白色织物消毒", "在牙龈肿痛时，以5 摄氏度的凉水刷牙", "用聚氯乙烯（PVC）保鲜膜包裹保存高温油炸食物"], "a": 1, "e": ".【B】本题考查科技常识。A项错误，“201不锈钢”含镍、铬少，防腐性能弱；含锰多，耐酸耐碱性能好，但对人体神经系统有害，不适合做炒锅。目前食用级的不锈钢都是“304不锈钢”和以上级别。B项正确，“84消毒液”是以次氯酸钠为主要有效成分的消毒液，有效氯含量为-，可杀灭肠道致病菌、化脓性球菌和细菌芽孢。适用于一般物体表面、白色衣物、医院污染物品的消毒。C项错误，牙齿进行新陈代谢的最佳温度为35-36.5摄氏度。牙龈肿痛时，倘若刷牙时不注意水温，使牙齿受到骤冷刺激，可能会诱发或加重病情。D项错误，PVC保鲜膜在制作过程中，会加入大量增塑剂，当它在加热状态下或与油脂食品接触使用时，就会有增塑剂析出，对人体造成一定危害，甚至致癌。PVC保鲜膜一般用于生鲜果蔬保鲜等，PE保鲜膜可以用于温度不超过110摄氏度的食物保鲜。故正确答案为B。", "tag": "科技常识"},
{"id": "tech-315", "q": "人们对消毒杀菌越来越重视，下列说法正确的是：", "options": ["", "洁厕灵和84 消毒液混合使用可提高杀菌效果", "多酶消毒液应在沸水状态下使用", "巴氏消毒法可用来给啤酒消毒"], "a": 3, "e": ".【D】本题考查科技常识。A项错误，酒精的学名叫乙醇，它具有很大的渗透能力，能钻到细菌体内，使细菌蛋白质凝固，从而杀死细菌。并不是纯度越高，杀菌消毒的效果就越好。酒精的浓度很高，过高浓度的酒精会在细菌表面形成一层保护膜，阻止其进入细菌体内，难以将细菌彻底杀死；若酒精浓度过低，虽可进入细菌，但不能将其体内的蛋白质凝固，同样也不能将细菌彻底杀死。当酒精浓度为时，它的杀菌能力是最强的。B项错误，洁厕灵和84消毒液不能混合，可能产生有毒气体。当洁厕灵的主要成分是盐酸时，它与主要成分是次氯酸钠的强碱性84消毒液混合会发生化学反应，反应后产生氯气。氯气是一种有强烈刺激性气味的有毒气体。如果吸入一定量的氯气，会损伤人体的呼吸道、眼鼻等器官，出现不适症状，若氯气浓度很高，吸入量又大则会危及生命。C项错误，多酶消毒液即多酶清洗液。需要清洗的物品应当浸泡在已经稀释后的多酶清洗液溶液中，浸泡的时间在2-10分钟左右。多酶清洗液的使用环境一般在PH值5.5-9.0之间，但是PH值6.5-7.5之间的环境下使用效果最好。使用多酶清洗液进行清洗时，水温最好在-之间。D项正确，巴氏消毒法，也称巴氏灭菌法，是法国生物学家路易·巴斯德于1865年发明的消毒方法。巴氏灭菌法来源于巴斯德解决啤酒变酸问题的努力，是一种利用较低的温度既可杀死病菌又能保持物品中营养物质风味不变的消毒法。巴氏消毒法经后人改进，是一种用于彻底杀灭啤酒、酒、牛奶、血清蛋白等液体中病原体的方法，也是现世界通用的一种牛奶消毒法。故正确答案为D。", "tag": "科技常识"},
{"id": "tech-316", "q": "超市卖的农产品包装上，有的贴“绿色食品”，有的贴“有机食品”，有的贴“无公害食品”。绿色食品、有机食品、无公害食品标准对产品的要求由高到低依次排列为：", "options": ["无公害食品、有机食品、绿色食品", "绿色食品、无公害食品、有机食品", "绿色食品、有机食品、无公害食品", "有机食品、绿色食品、无公害食品"], "a": 3, "e": ".【D】本题考查生活常识，主要涉及食品安全的相关内容。有机食品：位于金字塔顶端，生产制作过程非常严苛，严禁使用化肥、农药、抗生素、激素，包括转基因食品技术及其衍生物。绿色食品：在生产过程中允许使用农药和化肥，但对用量和残留量有严格规定。无公害食品：生产过程中允许使用农药和化肥，但不能使用国家禁止使用的高毒、高残留农药。这三者用图展示如下：故正确答案为D。", "tag": "科技常识"},
{"id": "tech-317", "q": "下列属于可回收利用垃圾的是（）。", "options": ["食品类废物", "陶器", "油漆颜料", "报纸"], "a": 3, "e": ".【D】本题考查生活常识。可回收垃圾就是可以再生循环的垃圾，包括本身或材质可再利用的纸类、硬纸板、玻璃、塑料、金属、人造合成材料包装，以及与这些材质有关的物品，主要包括废纸、塑料、玻璃、金属和布料五大类。不可回收垃圾指除可回收垃圾之外的垃圾，常见的有在自然条件下易分解的垃圾，如烟头、煤渣、建筑垃圾、油漆颜料、食品残留物等废弃后没有多大利用价值的物品。厨余垃圾、有毒有害垃圾也属于不可回收垃圾。厨余垃圾包括果皮、菜叶、剩菜剩饭、饭后垃圾等。有毒有害垃圾包括油漆颜料、废弃电池、废弃灯管等。A项错误，食品类废物属于不可回收垃圾。B项错误，陶器、瓷器及石砖难以回收，属于不可回收垃圾。C项错误，油漆颜料属于不可回收垃圾。D项正确，报纸属于可回收垃圾。故正确答案为D。", "tag": "科技常识"},
{"id": "tech-318", "q": "发生火灾时应匍匐前进以逃生，其原因的下列说法，错误的是（）", "options": ["低处有残留的新鲜空气", "有毒有害气体集中于高处", "浓烟自下而上扩散", "低处视野比较清晰"], "a": 2, "e": ".【C】发生火灾时，浓烟温度较高，首先充满屋顶，随着时间的推移，从屋顶向地面逐渐下移，是自上到下扩散的过程，直到充满整个房间，C项说法错误，符合题意，当选。烟雾的重力作用往往使浓烟聚集在离地面大约三十厘米的地方，因此逃生时应当尽量压低身体，这样才能保证自身安全。A、B、D三项说法正确，但不符合题意，排除。本题为选非题，故正确答案为C。", "tag": "科技常识"},
{"id": "tech-319", "q": "关于药品，下列说法错误的是：", "options": ["大部分药品属于处方药，如注射剂、毒麻药品等", "非处方药不需要凭执业医师处方即可自行购买和使用", "处方药不可擅自使用、停用或增减剂量，否则可能引起严重后果", "药品说明书用以指导医生和患者选择、使用药品，但不具法律意义"], "a": 3, "e": ".【D】处方药就是必须凭执业医师或执业助理医师处方才可调配、购买和使用的药品。大部分药品属于处方药，特殊药品也属于处方药：各类麻醉类药品、抗癌类药品以及精神类药品，因此A项正确；非处方药是指为方便公众用药，在保证用药安全的前提下，经国家卫生行政部门规定或审定后，不需要医师或其它医疗专业人员开写处方即可购买的药品，一般公众凭自我判断，按照药品标签及使用说明就可自行使用，因此B项正确；处方药必须凭执业医师或执业助理医师处方才可调配、购买和使用的药品。不可擅自使用、停用或增减剂量，否则可能引起严重后果，因此C项正确；药品说明书是载明药品的重要信息的法定文件，具有重要的法律意义。我国《药品管理法》第54条规定，药品包装必须按照规定印有或者贴有标签并附有说明书，因此D项错误。本题为选非题，故正确答案为D。", "tag": "科技常识"},
{"id": "tech-320", "q": "机场、银行等服务窗口实行“一米线”制，要求等候服务的顾客必须与正在接受服务的顾客之间保持一米的距离。这一制度的主要功能是：", "options": ["维持服务秩序", "保护顾客隐私", "提升服务质量", "提高道德水准"], "a": 1, "e": ".【B】B项符合题意：一米线，其主要功能是维护个人的隐私，兼有维护公共秩序，保持公众距离的作用。而在机场和银行等服务窗口设置一米线主要是防止顾客个人信息或储户密码等被偷看，起到保护顾客隐私的作用。故正确答案为B。", "tag": "科技常识"},
{"id": "tech-321", "q": "中央电视台天气预报栏目说，“今天白天晴间多云，最高温度25 摄氏度”。这里的“今天白天”所指时间段是：", "options": ["6：00 到18：00", "7：00 到19：00", "8：00 到20：00", "9：00 到21：00"], "a": 2, "e": ".【C】本题考查科技常识。天气预报用语规定：“今天白天”是指上午8:00到晚上20:00的12h；“今天夜间”是指20:00到次日早上8:00的12h。故正确答案为C。", "tag": "科技常识"},
{"id": "tech-322", "q": "关于处方药，下列说法错误的是：", "options": ["不可自行购买和使用", "催眠安定药不属于处方药", "不良反应发生率较高", "须在医生指导下服用药物"], "a": 1, "e": ".【B】本题考查科技常识。处方药就是必须凭执业医师或执业助理医师处方才可调配、购买和使用的药品；而非处方药则不需要凭医师处方即可自行判断、购买和使用的药品。A项正确，根据《处方管理办法》第四条第二款规定：“处方药应当凭医师处方销售、调剂和使用。”处方药不能自行购买和使用。B项错误，安眠药是精神药品，经营此类药品，必须由县以上卫生行政部门指定，其他任何单位和个人均不得经营。现在到药店购买安眠药，一定要出示医生处方。因此，安眠药属于处方药。C项正确，处方药一般不良反应发生概率较大，有一定的治疗风险，需要在医生评估过用药风险和健康收益后再决定是否使用。D项正确，处方药必须凭执业医师开具的处方才可以调配、购买，并且要在医生、护士、药师及其他医疗专业人员的监督和指导下才可使用，处方药不能凭自己判断使用。本题为选非题，故正确答案为B。", "tag": "科技常识"},
{"id": "tech-323", "q": "下列关于盐的说法错误的是：", "options": ["盐又称“百味之王”，是咸味的载体，具有去腥增鲜之用", "人体如果摄入过多的盐分，容易产生高血压、水肿等问题", "按来源及开采方式分类，盐可分为：井盐、海盐、湖盐等", "日常生活中的低钠盐加入了一定比例的氰化钾，其咸味较淡"], "a": 3, "e": ".【D】本题考查科技常识。A项正确，食盐主要成分是氯化钠，味咸。食盐溶液渗透力很强，能提高各种食用原料中固有的鲜味，并且还有解腻、除膻、去腥的作用，有“百味之王”的美称。B项正确，盐的主要成分是氯化钠。氯离子和钠离子在人体新陈代谢中发挥着重要作用。氯离子具有维持渗透压、调节酸碱平衡和组成胃酸等生理作用。钠离子在人体水量恒定上起主要调节作用，钠多则水也多，钠少水也应当减少。因此盐摄入过多时，容易引发水肿；另外人体盐分多了，对水分的需求会相应的增加，从而使过多的水分滞留在体内，导致血管内血浆容量增加，最终引发高血压。C项正确，盐按照原料来源可分为4类：海盐、湖盐、井盐和矿盐。以海水为原料晒制而得的盐叫作海盐；从盐湖中直接采出的盐和以盐湖卤水为原料在盐田中晒制而成的盐叫作湖盐；通过打井的方式抽取地下卤水进而制成的盐叫作井盐；开采岩盐矿床制得的盐叫作矿盐。D项错误，氰化钾有剧毒，不能作为添加剂使用。低钠盐与普通钠盐相比含钠低（氯化钠70左右），富含钾（氯化钾", "tag": "科技常识"},
{"id": "tech-324", "q": "下列说法中，错误的是（）。", "options": ["雷雨可使土壤的氮肥增加", "豆类植物的根瘤菌可以从空气中固氮", "当厨房发生煤气泄漏时应打开抽油烟机", "在金属表面喷漆可以防止金属被氧化腐蚀"], "a": 2, "e": ".【C】本题考查科技常识。A项正确，在雷雨天气，由于在放电条件下，空气中的氧气和氮气反应生成了氮的氧化物，氮的氧化物再与雨水相互作用可形成碳铵，随雨水落入土壤，碳铵能提供作物生成所需要的N元素，属于氮肥，因此雷雨可以使土壤中的氮肥增加。B项正确，根瘤菌与豆科植物共生，形成根瘤并固定空气中的氮气为豆科植物提供营养。C项错误，发生煤气泄漏时，一定要迅速打开门窗，使新鲜空气进来以大大降低室内煤气的浓度。要迅速关闭煤气的阀门，防止煤气的继续泄漏，同时禁止一切能引起火花的行为。打开抽油烟机容易引起电火花，会引燃煤气，发生爆炸。D项正确，金属表面喷漆是一种保护金属不被氧化腐蚀的方法。良好的喷漆涂装保护层保持连续完整无损，结合良好，能够成为抑制腐蚀介质侵入的屏障。本题为选非题，故正确答案为C。", "tag": "科技常识"},
{"id": "tech-325", "q": "关于生活常识，下列说法错误的是：", "options": ["胆囊B 超、尿常规检查均需空腹进行", "装修时使用铜线成本高，但电损耗低", "复方甘草片中含有容易使人成瘾的成分", "葡萄表面附着的白霜是一种糖醇类物质"], "a": 0, "e": ".【A】本题考查科技常识。A项错误，胆囊属于肝胆系统，检查肝胆系统必须空腹，因为一旦进食后胆汁分泌会导致胆囊充盈，胆管扩张，不能充分客观反应胆道系统是否有问题；尿常规检查不需要空腹，但是要注意外阴清洁，在检查之前最好是冲洗外阴，消毒尿道口，用无菌试管留取中段尿送检。B项正确，铜线载流量大、电压损失低、电损耗低、价格高。C项正确，复方甘草片含有阿片粉或罂粟果提取物粉等容易上瘾的成分，一般食用复方甘草片最好是不要超过五天，避免形成药物依赖。D项正确，葡萄表面的“白霜”是葡萄本身分泌的糖醇类物质，被称为果粉，对人体无害。本题为选非题，故正确答案为A。", "tag": "科技常识"},
{"id": "tech-326", "q": "处置突发性公共事件的首要原则是：", "options": ["迅速性原则", "效率性原则", "安全性原则", "慎重性原则"], "a": 0, "e": ".【A】突发性公共事件具有突发性、复杂性、破坏性、可控性等特点，因此，处置突发性公共事件必须迅速、及时，最大程度上控制局面，挽回损失。所以，处置突发性公共事件的首要原则应为迅速性原则。故正确答案为A。", "tag": "科技常识"},
{"id": "tech-327", "q": "下列选项中，用热水比用冷水洗涤效果更好的是：", "options": ["有油渍的碗筷", "有汗渍的衣服", "有血渍的衣服", "有农药残留的蔬菜"], "a": 0, "e": ".【A】A项正确，油渍不溶于水，用冷水难以去掉，而热水温度高，可以加快分子运动，使油渍更快软化，因此用热水来洗涤有油渍的碗筷，效果要比用冷水洗好。B项中的汗渍和C项中的血渍中都含有蛋白质，用热水洗容易导致蛋白质凝固，附着在衣服上，更难清洗。D项，去除有农药残留的蔬菜，通常是用清水多冲洗几遍，用热水洗，水温过高的话，容易导致蔬菜中的营养物质流失，洗涤效果不比冷水好。故正确答案为A。", "tag": "科技常识"},
{"id": "tech-328", "q": "下列关于避雷针的说法，错误的是：", "options": ["南北朝时就已出现与避雷针工作原理相似的“避雷室”", "避雷针和他要保护的建筑是由绝缘物质隔开的", "接闪器可用铝合金、镀锌钢、不锈钢等各种材料制成", "我国现在已经放弃了“避雷针”这一叫法，而代之以“接闪杆”"], "a": 1, "e": ".【B】B项错误：避雷针保护建筑物的方式是引雷上身，然后通过其引下线和接地装置，将雷电流引入地下，从而起到保护建筑物的作用。若将避雷针与建筑绝缘，导入避雷针内的雷电将无处释放，从而引发危险。因此避雷针必须与保护建筑联通。A项正确：南朝盛弘之撰的《荆州记》中记载：“湖阳县，春秋寥国，樊重之邑也。重母畏雷，为母玄石室，叫避之。悉以文石为阶砌，至今犹存。”可见在南北朝时期就出现了“避雷室”。C项正确：接闪杆与接闪带、接闪线、接闪网、用以接闪的金属屋面、金属构件等，统称为接闪器。接闪器必须用导电体作材料，由于接闪器需要暴露在空气中接受风吹日晒，因此可以选用铝合金、锌镀铜、不锈钢等抗氧化、耐腐蚀的合金材料。D项正确：因为避雷针的工作原理不是避免房屋遭受雷击，而是接引雷电引入地下。因此在中华人民共和国国家标准GB50057-2010《建筑物防雷设计规范》中，已经放弃避雷针这一称呼，而代之以“接闪杆”这一更加贴切的叫法。本题为选非题，故正确答案为B。【注：本题为争议题，A项表述不严谨，南北朝时期出现的避雷室由大理石铸造，利用大理石的绝缘特性，故可以避雷。这与现代避雷针引雷上身之后将雷电导入地下的工作原理不完全相同。】", "tag": "科技常识"},
{"id": "tech-329", "q": "手指表皮上突起的纹线，被称为指纹。指纹人人皆有，它是遗传与环境共同作用产生的。下列关于指纹的说法有误的是（）。", "options": ["指纹可以用于身份识别", "人的指纹一般终身不变", "同卵双胞胎的指纹是相同的", "只要不伤及真皮层，手指伤愈后仍能长出同样的指纹"], "a": 2, "e": ".【C】本题考查生活常识。指纹是人类手指末端指腹上由凹凸的皮肤所形成的纹路，指纹能使手在接触物件时增加摩擦力，从而更容易发力及抓紧物件，是在人类进化过程式中自然形成的。A项正确，人的指纹由遗传与环境共同作用，指纹人人皆有，却各不相同，由于指纹重复率极小，大约为150亿分之一，故其称为“人体身份证”，可用于身份识别。B项正确，指纹的形成主要受遗传和环境因素影响，人的指纹原则上来说是终身不变的。当儿童长大成人，指纹也只是放大增粗，其纹形、纹数等特征则保持不变。C项错误，尽管同卵双胞胎在指纹上有高度的相似性，但由于发育开始指尖细胞的微环境中的微小差异会被细胞分化过程放大，最终导致两人的指纹完全相同的概率极低，所以同卵双胞胎的指纹并不完全相同。D项正确，真皮位于表皮下层，表皮和真皮交界处凹凸不平，错综复杂。这些凹凸类似“模子”，最终形成了指纹纹形。只要不伤及手指的内部真皮层，伤愈后仍能长出同样的指纹。本题为选非题，故正确答案为C。", "tag": "科技常识"},
{"id": "tech-330", "q": "日常中，垃圾一般分为：可回收垃圾、有毒垃圾、厨余垃圾和其他垃圾（不可回收垃圾）。据此，下列说法错误的是：", "options": ["可回收垃圾、其他垃圾的标志分别为", "充电电池、废旧灯管灯泡属于有毒垃圾", "受污染的纸张、过期药品等都应归为其他垃圾", "厨余垃圾包括饭菜、过期食品、菜梗菜叶等废弃的生热食物残渣"], "a": 2, "e": ".【C】本题考查生活常识中的垃圾分类知识。A项正确，可回收垃圾表示适宜回收和资源利用的垃圾，主要包括废纸、塑料、玻璃、金属和布料。其标志为；其他垃圾包括砖瓦陶瓷、渣土、瓷器碎片等难以回收的废弃物。其标志为。B项正确，有毒垃圾表示含有毒害物质，需要特殊安全处理，会对人体健康或自然环境造成直接或潜在危害。包括废电池、废灯管、废灯泡、废溶剂及其包装物、废杀虫剂、消毒剂、过期药品等。充电电池、废旧灯管灯泡会对自然环境造成直接或潜在危害，均属于有毒垃圾。C项错误，其他垃圾危害较小，但无再次利用的价值。受污染的纸张无再次利用的价值，可以归入其他垃圾；过期药品可能会污染土地、水源，对环境或者人体健康造成危害，故属于有毒垃圾，不能归入其他垃圾。D项正确，厨余垃圾是居民日常生活及食品加工、饮食服务等活动中产生的垃圾，包括废弃的菜梗菜叶、剩饭、剩菜、果皮、蛋壳、变质的过期食品等。本题为选非题，故正确答案为C。", "tag": "科技常识"},
{"id": "tech-331", "q": "下列疾病与治疗药物对应错误的是：", "options": ["冠心病——硝酸甘油片", "糖尿病——胰岛素", "佝偻病——维生素D 片", "坏血病——阿司匹林"], "a": 3, "e": ".【D】本题考查生活常识，主要涉及疾病与药物的相关知识。A项正确，硝酸甘油片，适应症为用于冠心病、心绞痛的治疗及预防，也可用于降低血压或治疗充血性心力衰竭。所以硝酸甘油片可以用于治疗冠心病。B项正确，胰岛素可增加葡萄糖的利用，能加速葡萄糖的无氧酵解和有氧氧化，促进肝糖原和肌糖原的合成和贮存，并能促进葡萄糖转变为脂肪，控制糖原分解和糖异生，因而能使血糖降低。所以胰岛素用于糖尿病患者控制血糖特别是餐后高血糖。C项正确，佝偻病即维生素D缺乏性佝偻病，是由于婴幼儿、儿童、青少年体内维生素D不足，引起钙、磷代谢紊乱，产生的一种以骨骼病变为特征的全身、慢性、营养性疾病。所以补充维生素D可以有效治疗佝偻病。D项错误，坏血病一般指维生素C缺乏症，这是一种急性或慢性疾病，特征为出血，类骨质及牙本质形成异常。阿司匹林是一种解热镇痛药，主要用于治感冒、发热、头痛、牙痛、关节痛、风湿病，还能抑制血小板聚集。所以坏血病应补充维生素C，而不是用阿司匹林治疗。本题为选非题，故正确答案为D。", "tag": "科技常识"},
{"id": "tech-332", "q": "下列对日常生活现象的解释不正确的是", "options": ["生活中我们一般不会看到高度白酒凝固，是因为酒精的凝固温度低", "天然气灶台火焰的外焰温度比内焰温度高，是因为外焰的燃烧更充分", "水滴入滚热的油锅会立刻爆炸，是因为高温下水与油发生了剧烈的化学反应", "打开冰箱门并不能给室内降温，是因为冰箱在制冷过程中会释放大量的热量"], "a": 2, "e": ".【C】本题考查生活常识。A项正确，水的凝固点是0摄氏度，食用酒精的凝固点是-117摄氏度。酒精与水混合物的凝固点介于-117℃~0℃之间，酒精含量越高，凝固点越低，因此生活中一般看不到高度白酒凝固。B项正确，火焰通常从外到内分为三层，即外焰、内焰和焰心。外焰与内焰相比，可燃气体与空气接触、混合、充分燃烧，温度最高，而内焰温度要低于外焰。C项错误，物理变化，指物质的状态虽然发生了变化，但一般说来物质本身的组成成分却没有改变；而化学变化则是有新物质的产生。当水滴入油锅爆炸是因为油温沸点一般在100摄氏度以上，而水在100摄氏度就汽化。当水滴进入滚烫的油里面，在进入的过程中瞬间变成水蒸汽，对周围的油产生了压力，油被很快推向空中，并发出“啪啪啪”的爆炸声。这个现象并没有新物质的产生，只是物理变化，并不涉及化学反应。D项正确，冰箱仅在封闭的小环境里可以制冷，同时冰箱的压缩机还要向周围环境放热。如果打开冰箱门，冰箱内部的温度就会上升，压缩机就会不停的工作，向室内放热。所以打开冰箱门并不能降低室内温度。本题为选非题，故正确答案为C。", "tag": "科技常识"},
{"id": "tech-333", "q": "现在人们越来越关注餐桌上的健康。用餐时，使用什么餐具对人体更健康：", "options": ["铝制餐具", "不锈钢餐具", "可降解泡沫饭盒", "素色的陶瓷餐具"], "a": 3, "e": ".【D】A项错误，铝制餐具中的铝会加快衰老、影响记忆力；B项错误，不锈钢餐具中的镍和钛有轻微毒性，对人体有害；C项错误，可降解泡沫餐盒主要原料仍为聚苯乙烯，是一种致癌物质；D项正确，素色的陶瓷餐具一般含铅量不会过量，不会对人体造成危害。故正确答案为D。", "tag": "科技常识"},
{"id": "tech-334", "q": "下列哪两种疾病是由细菌引起的：", "options": ["手足口病、狂犬病", "麻疹、腮腺炎", "肺结核、破伤风", "非典型肺炎、水痘"], "a": 2, "e": ".【C】A项错误，手足口病是由肠道病毒引起的传染病；狂犬病是由狂犬病毒所致的急性传染病。B项错误，麻疹是由麻疹病毒引起的传染性很强的疾病，是儿童最常见的急性呼吸道传染病之一；腮腺炎是指腮腺受到病毒或细菌的感染而发炎，常发生在冬春季节，儿童多见。C项正确，肺结核是由结核分枝杆菌引起的慢性传染病；破伤风是破伤风梭菌经由皮肤或黏膜伤口侵入人体，在缺氧环境下生长繁殖，产生毒素而引起肌痉挛的一种特异性感染。D项错误，非典型肺炎是由SARS冠状病毒所引起的严重急性呼吸道综合症。水痘是由水痘——带状孢疹病毒初次感染引起的急性传染病。故正确答案为C。", "tag": "科技常识"},
{"id": "tech-335", "q": "下列关于医学常识的表述，错误的是：", "options": ["发生药物过敏时，应首先多喝些温开水，便于药物排泄", "清晨空腹时肠胃比较脆弱，不宜服用药物", "运动员受伤时，医生可用氯乙烷来给运动员镇痛和局部麻醉", "缺乏碘元素会引发甲状腺肿大或克汀病等"], "a": 1, "e": ".【B】B项错误：不同的药物有不同的服用时间，一般来说没有特殊规定的药物空腹吃效果更好，因为食物会延缓药物吸收，所以一般尽量空腹吃。但是对胃有刺激性或有胃病的人应饭后吃药，防止药物对胃产生副作用。A项正确：药物过敏时多喝开水可以加速新陈代谢，从而加快过敏物质的排泄。C项正确：氯乙烷是冷冻剂、麻醉剂，有冷冻和麻醉作用。运动员摔伤后，伤处的毛细血管扩张。而氯乙烷有吸热的作用，可以使伤处血管收缩，起到止血的作用，同时可以起到麻醉止痛的作用。D项正确：机体缺碘会导致地方性甲状腺肿和地方性克汀病，现在统称为“碘缺乏病”。本题为选非题，故正确答案为B。", "tag": "科技常识"},
{"id": "tech-336", "q": "下列符合常识的是：", "options": ["2000 毫升矿泉水约重2 斤", "成人使用的标准筷子长度约为14 厘米", "仍在流动的淡水河其水温为零下3 摄氏度", "弯道较多的盘山公路限速100 公里每小时"], "a": 2, "e": ".【C】本题考查科技常识。A项错误，毫升是一个容积单位，跟立方厘米对应，容积单位的主单位是升（L）。，。500毫升水大约是1斤，即500、0.5。水的密度是1，500，即500，质量是（），。故2000毫升矿泉水约重4斤。B项错误，现在中国人使用的筷子，标准长度是七寸六分（约为22至24厘米左右）。C项正确，因为淡水河中的水并不是纯净的水，里面可能溶解了很多物质，水的凝固点降低，水也有可能需在0以下才能冻结。因此流动中的淡水河其水温在零下3摄氏度是有可能的。D项错误，《中华人民共和国道路交通安全法实施条例》第四十六条规定：“机动车行驶中遇有下列情形之一的，最高行驶速度不得超过每小时30公里，其中拖拉机、电瓶车、轮式专用机械车不得超过每小时15公里：（一）进出非机动车道，通过铁路道口、急弯路、窄路、窄桥时；（二）掉头、转弯、下陡坡时；（三）遇雾、雨、雪、沙尘、冰雹，能见度在50米以内时；（四）在冰雪、泥泞的道路上行驶时；（五）牵引发生故障的机动车时。”故正确答案为C。", "tag": "科技常识"},
{"id": "tech-337", "q": "“春困”是人体随着自然气候的变化而发生的生理反应。为克服“春困”，下列做法不合适的是（）。", "options": ["多吃黄绿色蔬菜", "保持室内空气流通", "尽可能多做剧烈运动", "养成早睡早起的习惯"], "a": 2, "e": ".【C】本题考查生活常识。“春困”指气候日渐转暖，人会感到困倦、疲乏、头昏欲睡，“春困”是春季普遍存在的一种正常的暂时性生理现象，是人体对季节转换而自然做出的调节反应。A项正确，春季人体的新陈代谢旺盛，饮食应清淡，适当地春补。油腻食品可使人产生疲惫无力、情绪低落的症状，这将加重“春困”现象。食用黄绿色蔬菜，如胡萝卜、菠菜等，能够为人体提供维生素A、维生素C等人体必备维生素，一方面可以增强人体免疫力，另外一方面对恢复精力、消除“春困”有很好的效果。B项正确，长时间室内空气不流通，容易造成室内氧气不足，导致大脑缺氧而引起困倦。所以春季气温回升时保持空气流通，有利于保证大脑供氧，缓解“春困”。C项错误，虽然春天多锻炼能够缓解疲劳，克服“春困”，但是这种运动并非是“剧烈”的运动。由于刚刚经历过冬季，人们缺乏锻炼，过于剧烈的运动反而会对身体造成不必要的伤害，同时剧烈运动时，人体通过无氧呼吸提供运动所需能量，肌肉供氧不足，产生乳酸等代谢产物，容易造成身体疲惫、肌肉酸痛，让人困倦，因此春季运动，适度适量即可。D项正确，充足的睡眠能为人体提供能量，调节气血，缓解白天的困倦感，有效缓解“春困”，另外春日里尽量不要熬夜，以免诱发和加重“春困”。本题为选非题，故正确答案为C。", "tag": "科技常识"},
{"id": "tech-338", "q": "下列说法正确的是：", "options": ["在灭火时，冷水和热水的灭火效果相同", "刹车失灵的情况下，如选择跳车，则向后跳相对比较安全", "露水多出现在阴天、空气湿度大的情况下", "白炽灯的灯丝断了，重新搭上后，会比原来亮"], "a": 3, "e": ".【D】A项错误，热水的蒸汽层会在燃烧物上笼罩，使其与外界氧气的接触减少，这样比冷水更易起到灭火的作用。B项错误，刹车失灵的情况下，因惯性前跳比较安全；C项错误，晴天时没有云层，太阳直接照射，空气垂直方向上温差较大，空气中的水蒸气容易在底层大气液化形成露珠。D项正确，白炽灯灯丝断后再接上，电压不变，电阻变小了，所以功率变大，灯会变得更亮。故正确答案为D。", "tag": "科技常识"},
{"id": "tech-339", "q": "生活常识说法错误的是：（）。", "options": ["水在真空中先沸腾后结冰", "颜色较深的车隔热膜，隔热效果越好", "纯水在0 度时不结冰", "天凉的时候，湿润的地方比干燥的地方感觉冷"], "a": 1, "e": ".【B】A项表述正确。水在真空中，由于压力骤降导致沸点剧降而沸腾，快速沸腾导致热量瞬间散失而结冰，故A项正确。B项表述错误。汽车隔热膜的隔热效果和膜的颜色深浅没有必然的关系。目前的优质隔热膜，一般采用多层复合结构，每一层的设计功能不同，通过涂布特殊材质的粒子，可以分别反射不同波段的红外线和紫外线，有选择性的阻隔太阳光中的不同部分。优质的隔热膜不但能够高效的隔热，还能同时保证高的透光度，保障行车安全。故B项错误。C项表述正确。在纯水情况下，在水温达到了0度时，不是一下子就结冰的，这是因为水的结冰要有结晶核心，当水极端纯净的时候，水里没有凝结核心，所以在水温刚刚达到0度时，还不会结冰，甚至稍微低于0度也不会结冰，这时就形成了所谓的“过冷水”，即低于0度的水。当然，在水温低到一定程度的时候，水分子结成冰晶，过冷水会立即结冰。故C项正确。D项表述正确。天凉的时候，人感觉到的温度实际上是衣服以及被衣服隔离的皮肤表面那些空气的温度。水的比热很大，体温用来加热潮湿的空气要比加热干燥的空气消耗更多的热量，要是衣服也含水，那么加热起来更费劲，人就会感觉更凉。所以在湿度大的地方，衣服容易吸更多的水，衣服里面隔离的那些靠近皮肤的空气湿度也更大，就会让人感觉更冷。故D项正确。本题为选非题，故正确答案为B。", "tag": "科技常识"},
{"id": "tech-340", "q": "首因效应也叫第一印象效应，是指个体在社会认知过程中，通过“第一印象”最先输入的信息对客体以后的认知产生的影响作用。下列选项符合首因效应的是：", "options": ["物以类聚", "削足适履", "恶人先告状", "一俊遮百丑"], "a": 2, "e": ".【C】根据文意可知，首因效应是指“第一印象”影响了个体对客体的认知，C项“恶人先告状”指坏人或理亏的人，抢先去诬告别人，从而给有理的人造成不好的第一印象，与文意相符，当选。A项“物以类聚”是指同类的东西聚在一起，体现的是心理学的“磁石法则”，与文意不符，排除；B项“削足适履”比喻不合理的迁就凑合或不顾具体条件，生搬硬套，体现的是心理学的“刻板效应”，与文意不符，排除；D项“一俊遮百丑”是指一项美掩盖了许多的丑陋，体现的是心理学的“晕轮效应”，与文意不符，排除。故正确答案为C。", "tag": "科技常识"},
{"id": "tech-341", "q": "发展工业旅游能使人牢记工业文明的历史足迹，某旅游团组织开展一次“工业旅游”，根据下图内容及顺序判断，该旅游团游览的工业文明依次是：", "options": ["啤酒酿制技术、青铜器制作技术、纺织技术、风电技术", "橡胶加工技术、景泰蓝制作技术、服装技术、采油技术", "啤酒酿制技术、景泰蓝制作技术、纺织技术、风电技术", "橡胶加工技术、青铜器制作技术、服装技术、采油技术"], "a": 2, "e": ".【C】C项正确：图中①为啤酒酿制过程中使用的木桶，②为景泰蓝摆件，③为纺纱车，④为风力发电机，因此正确顺序为啤酒酿制技术、景泰蓝制作技术、纺织技术、风电技术。本题可采用排除法，首先，图片中最容易判断的是④，很明显可以看出图中是风力发电机，因此可以排除B项和D项。观察A项和C项，只有关于图中②的内容是不同的，而②中的摆件整体较小，有很多精美的细节，而青铜器通常比较粗糙，边缘褶皱少，因此可以确定②为景泰蓝制作技术，不是青铜器制作技术。故正确答案为C。", "tag": "科技常识"},
{"id": "tech-342", "q": "关于运动中受伤的处置方式，下列说法错误的是：", "options": ["可通过伸展练习缓解运动后的肌肉酸痛", "运动中发生肌肉痉挛可采用冷敷痉挛部位来缓解", "一般性关节韧带损伤后，应在24 小时内采用冷敷", "运动骨折后，应先用夹板或其他代用品固定伤肢"], "a": 1, "e": ".【B】本题考查科技常识。A项正确，肌肉酸痛可以说算肌肉疲劳，肌肉酸痛的原因有两种：一种是乳酸堆积导致的酸痛，还有一种是延迟性肌肉酸痛。可以采取如下有效方式缓解：（1）运动后一定要伸展，拉伸可以让筋膜扩张有利于肌肉整体的体积增长。可以舒展肌肉，让肌肉变的更加有弹性，不至于使肌肉变的僵硬。能够有效的缓解肌肉的压力，加速肌肉的恢复。（2）对酸痛局部进行按摩，使肌肉放松，促进肌肉血液循环，有助损伤修复及痉挛缓解；B项错误，应对肌肉痉挛的具体方法要根据肌肉疼痛的不同感受而定。一旦发生肌肉痉挛，应缓和地帮助痉挛的肌肉伸展，直到痉挛和疼痛消失，再柔和地按摩。按摩后如果肌肉仍紧绷，需要热敷；而按摩后觉得肌肉酸痛则需冷敷。B项说法不全面；C项正确，对于一般性关节韧带损伤，应在24小时内采用冷敷，必要时加压包扎24小时以后采用理疗，热敷、按摩、针灸等方式治疗；D项正确，运动骨折后不要移动患肢，应用夹板或其他代用品固定伤肢，及时护送医院检查治疗。本题为选非题，故正确答案为B。", "tag": "科技常识"},
{"id": "tech-343", "q": "下列生活常识中，表述错误的是：", "options": ["药物大多饭后服用，是为了减少对胃肠道的刺激", "大米久泡，会使无机盐和可溶性维生素溶于水而损失", "经常用冷水刷牙，容易导致牙龈出血、牙髓痉挛等疾病", "发烧时喝茶能辅助降温，因为茶叶所含的茶碱能降低人体温度"], "a": 3, "e": ".【D】本题考查生活常识。A项正确，药物饭后服用，是因为有些药对胃有刺激性。在饭后服用，胃里的食物可以将药物隔离，使药性缓慢释放，可减少药物对胃肠道的刺激，有利于药物吸收和利用。B项正确，由于大米中含有一些溶于水的维生素和无机盐，而且很大一部分在大米的外层，如果久泡，米粒中的无机盐和可溶性维生素会有一部分溶于水中而损失。C项正确，人的牙齿相对来说最适应约35-36.5摄氏度的温度，如果经常用冷水刺激牙齿将导致牙龈出血、牙髓痉挛或其他牙病的发生。D项错误，茶叶中含有茶碱，茶碱有兴奋中枢神经、加强血液循环及加速心跳的作用，相对地也会使血压升高。发烧时如果喝茶，由于茶碱的作用，会使体温更快上升，并可影响和降低药物的作用，从而加重病情，因此，发烧时不宜喝茶。本题为选非题，故正确答案为D。", "tag": "科技常识"},
{"id": "tech-344", "q": "燃放烟花最佳的气象条件：有较大分散性低云、碎积云，云底高度在1000 米左右，有一定的水汽，相对湿度70%左右，风力小于3 级。下列诗句描述的天气中最适合欣赏烟花的是：", "options": ["晴空一鹤排云上，便引诗情到碧霄", "黄梅时节家家雨，青草池塘处处蛙", "天上灰布悬，雨丝定连绵", "风雨从北来，万木皆怒号"], "a": 2, "e": ".【C】A项错误，晴天之时一为卷云，不符合碎云的条件；二为云高度极高，4500至10000米，不符合云底高度1000米左右的描述。因此非最适合欣赏烟花的气象条件。B项错误，黄梅时节家家雨，即长江中下游的梅雨季节，为阴雨连绵的天气，雨量在200-400毫米之间。不适合燃放、欣赏烟花。C项正确，天空灰布悬，指的是雨层云，雨层云底部经常伴有碎雨云，云高600-3000米，符合云层的要求；雨丝定连绵，说明会下绵绵细雨，处于下雨前的状态，当空气的相对湿度达100%，即达到饱和状态才能凝成小水滴（雾、云），聚成大水滴才会下雨。下雨前的相对湿度不一定要达100%，温带大陆性气候地区多数地方的相对湿度在80%左右徘徊，接近", "tag": "科技常识"},
{"id": "tech-345", "q": "食用菌（ediblefungus）是可供人类食用的大型真菌。世界第一大食用菌是：", "options": ["金针菇", "木耳", "蘑菇", "香菇"], "a": 2, "e": ".【C】世界第一大食用菌为蘑菇，香菇是第二大食用菌。故正确答案为C。本题相关知识点：金针菇学名毛柄金钱菌，又称毛柄小火菇、构菌、朴菇、冬菇、朴菰、冻菌、金菇、智力菇等，因其菌柄细长，似金针菜，故称金针菇。木耳又叫木菌，因生长于腐木之上，其形似人的耳朵，故名木耳。", "tag": "科技常识"},
{"id": "tech-346", "q": "下图左边为某工业园区区域指示牌内容，右边框内四个长方形为园区内各功能区域面积大小及分布大致示意，据此，指示牌所在位置最可能是：", "options": ["（1）", "（2）", "（3）", "（4）"], "a": 2, "e": ".【C】根据题干给出的四个区域的面积大小以及图例示意，可确定仓库区、包装区、生产区、休息区分布如下图所示：看图角度一般正面面对试卷。根据题干给出四个区域的箭头指示，左上方为仓库区，右下方为包装区，右上方为生产区，休息区为正上方，所以指示牌应该在（3）处。故正确答案为C。（注：试卷所给四个区域为大致分布，如若从题干所给的指示牌与各个区域的距离为解题切入口，不能完全一一对应，则此题无解。另据一般人看指示牌习惯，应该先确定目标方向，所以在解此题时以箭头方向为主。）", "tag": "科技常识"},
{"id": "tech-347", "q": "关于生活常识，下列表述不正确的是：", "options": ["煮肉时，把肉放入热水中煮则汤味鲜美，放在冷水里慢慢煮则肉味鲜美", "空腹吃进大量柿子，会与胃酸凝结成块，形成柿石，引起胃痛、呕吐", "自来水中含有氯，煮饭时它会破坏粮食中所含的维生素B1", "吃过大蒜后，喝杯牛奶，可减少大蒜残留在口中的异味"], "a": 0, "e": ".【A】A项错误，凉水煮肉时，有利于肉中的蛋白质和营养成分溶解于水中，所以汤味鲜美，沸水煮肉可以保证肉中的营养成分更多地保存在肉中；B、C、D三项正确。本题为选非题，故正确答案为A。", "tag": "科技常识"},
{"id": "tech-348", "q": "下列现象与物理效应之间无法对应的一组是：", "options": ["墙内开花墙外香—扩散现象", "杯弓蛇影—折射现象", "镜中花，水中月—平面镜成像", "立竿见影—光沿直线传播现象"], "a": 1, "e": ".【B】A选项正确，“墙内开花墙外香”是气体分子的扩散现象，说明分子在不停地做无规则运动；B选项错误，“杯弓蛇影”指墙壁上的弓映在酒杯里，好像一条蛇，这属于平面镜成像，是由光的反射形成的；C选项正确，“镜中花，水中月”属于平面镜成像，由光的反射形成的；D选项正确，“立竿见影”因为光沿直线传播，光线不能照到竖立的杆子后面，形成了影子。本题为选非题。故正确答案为B。", "tag": "科技常识"},
{"id": "tech-349", "q": "关于目前的国际体育赛事，下列说法正确的是：", "options": ["世界一级方程式锦标赛所用赛车的发动机排量没有限制", "进入世界杯和欧洲杯足球赛决赛圈的球队数量相同", "斯诺克台球属于奥运会的比赛项目之一", "法国网球公开赛属于大满贯的赛事"], "a": 3, "e": ".【D】A项错误，根据国际汽车运动联合会（FIA）的规定，一级方程式锦标赛所用赛车的发动机排量为3000cc；B项错误，进入世界杯决赛圈的队伍为32支，欧洲杯为24支；C项错误，斯诺克的女性参与者太少，这使得它很难成为奥运项目，且斯诺克也只是台球运动的一项，不可能单独列为奥运项目；D项正确，大满贯赛事包括澳大利亚公开赛、法国公开赛、温布尔登网球锦标赛和美国公开赛。故正确答案为D。", "tag": "科技常识"},
{"id": "tech-350", "q": "下列不能用来酿酒的农作物是：", "options": ["谷子", "黄豆", "红薯", "玉米"], "a": 1, "e": ".【B】酿酒使用的原料通常是富含淀粉或糖类物质的玉米、稻米、小麦、高粱、红薯等农作物，它们在微生物的作用下产生酒精。谷子去壳后是小米，可以用来酿制黄酒，而黄豆的主要成分是蛋白质和脂肪，不适合用来酿酒。本题为选非题，故正确答案为B。", "tag": "科技常识"},
{"id": "tech-351", "q": "在阴雨天，由于空气潮湿，衣物容易发霉。下列措施不能防止房间里衣物发霉的是（）。", "options": ["打开室内暖气设备", "在潮湿天气适当打开门窗通风透气", "开启室内空调抽湿功能或抽风装置", "将石灰用布或麻袋包装起来，放在房间的角落"], "a": 1, "e": ".【B】本题考查生活常识。潮湿、通风条件差的密闭环境有利于霉菌繁殖和毒素的产生。A项正确，室内暖气设备可以提高室内的温度，防止水汽凝结，从而减轻室内湿度，可以防止房间里的衣物发霉。B项错误，在潮湿的天气如果打开门窗通风透气，会让室外湿气进入室内，导致室内空气更为潮湿，从而让衣物受潮发霉。C项正确，空调抽湿功能或抽风装置的作用是将室内潮湿的空气排出室外，从而达到降低室内相对湿度的目的，所以开启室内空调抽湿功能或抽风装置可以有效地去除室内的湿气，防止衣物发霉。D项正确，石灰是吸附剂，1公斤生石灰能吸附空气中大约0.3公斤水分，所以把石灰用布或麻袋包起来，放在房间的角落，可以吸收空气中的水分，保持室内干燥，从而防止房间内衣物发霉。本题为选非题，故正确答案为B。", "tag": "科技常识"},
{"id": "tech-352", "q": "现在实施的国际急救指南心肺复苏术中，胸外心脏按压与人工呼吸的比例为：", "options": ["", "", "", ""], "a": 3, "e": ".【D】本题考查生活常识。根据2015版心肺复苏指南：心肺复苏抢救顺序为CAB（即胸外心脏按压-开放气道-人工呼吸），胸外心脏按压和人工呼吸比例为，按压频率为100-120次／分，按压深度为5-6cm，并要求胸廓充分回弹。只有在出现室颤和无脉室速时才进行除颤。故正确答案为D。", "tag": "科技常识"},
{"id": "tech-353", "q": "关于野外生存技能，下列说法中正确的是：", "options": ["在海岛生存时，如身体缺少盐分可饮用海水进行补充", "可以用手表、北极星、树冠、树桩来确认方向", "次氯酸钠可以用于破损伤口的消毒", "攀登雪山的时候不要大量饮水，否则容易造成水肿"], "a": 1, "e": ".【B】本题主要考查生活常识。A项错误，海水中含有大量盐类和多种元素，其中许多元素是人体所需要的。但海水中各种物质浓度太高，远远超过饮用水卫生标准，如果大量饮用，会导致某些元素过量进入人体，影响人体正常的生理功能，还会导致人体脱水，严重的还会引起中毒。所以不可饮用海水补充盐分。B项正确，在野外，可以利用指针式手表对太阳的方法确认方向；夜间天气晴朗的情况下，可以利用北极星确认方向，北极星指示的方向就是北方；可以利用树冠是否浓密确认方向；也可以利用树桩的年轮疏密来确认方向。C项错误，次氯酸钠是强氧化剂，用作漂白剂、氧化剂及水净化剂，用于造纸、纺织、轻工业等，具有漂白、杀菌、消毒的作用，用于水的净化，以及作消毒剂、纸浆漂白等，医药工业中用于制氯胺等。但是次氯酸钠具有腐蚀性，可致人体灼伤，具有致敏性，不能用于破损伤口的消毒。D项错误，登雪山时身体不断以出汗或者呼吸的形式失去水分，因此应当保持充分的饮水以防止脱水，故选项中攀登雪山时不要大量饮水是错误的。故正确答案为B。", "tag": "科技常识"},
{"id": "tech-354", "q": "自来水厂用来进行水消毒处理的常用化学试剂是：", "options": ["臭氧", "氯气", "过氧化氢", "碘伏"], "a": 1, "e": ".【B】B项正确：自来水厂主要以氯气为消毒剂，氯气与水反应生成次氯酸，而次氯酸的强氧化性能导致微生物细胞中的酶被氧化并且蛋白质被阻止合成而死亡，从而实现了消毒。A项错误：臭氧虽然也可用于水处理、水产养殖等领域，但是由于投资大、费用较氯化消毒高，消毒后对管道有腐蚀作用等缺点，臭氧并不是水消毒的常用化学剂。C项错误：过氧化氢水溶液俗称双氧水，适用于医用伤口消毒及环境消毒和食品消毒。D项错误：碘伏是单质碘与聚乙烯吡咯烷酮的不定型结合物，在医疗上用作杀菌消毒剂。故正确答案为B。", "tag": "科技常识"},
{"id": "tech-355", "q": "磁共振成像系统（MRI）不可能对人体造成下列哪一伤害：", "options": ["强静磁场", "随时间变化的梯度场", "射频场导致热效应", "对人体的高能辐射"], "a": 3, "e": ".【D】磁共振的基本原理：是将人体置于特殊的磁场中，用无线电射频脉冲激发人体内氢原子核，引起氢原子核共振，并吸收能量。在停止射频脉冲后，氢原子核按特定频率发出射电信号，并将吸收的能量释放出来，被体外的接受器收录，经电子计算机处理获得图像，这就叫做核磁共振成像。它对疾病的诊断具有很大的潜在优越性。它可以直接作出横断面、矢状面、冠状面和各种斜面的体层图像，不会产生CT检测中的伪影；不需注射造影剂；无电离辐射。MRI对检测脑内血肿、脑外血肿、脑肿瘤、颅内动脉瘤、动静脉血管畸形、脑缺血、椎管内肿瘤、脊髓空洞症和脊髓积水等颅脑常见疾病非常有效，同时对腰椎椎间盘后突、原发性肝癌等疾病的诊断也很有效。核磁共振虽然广泛应用于疾病的检测，但它存在许多可能的伤害。MRI可能对人体造成的伤害主要包括以下方面：（1）强静磁场的危害。强静磁场是在有铁磁性物质存在的情况下，不论是埋植在患者体内还是在磁场范围内，都可能是危险因素。尤其是在高强度的静磁场中工作的员工，高强磁场有可能引起周围电子仪器和设备失效，影响带有心脏起搏器和胰岛素泵（或其他金属植入物）的人员健康。（2）随时间变化的梯度场也会对人体造成伤害，因为其在受试者体内诱导产生电场而兴奋神经或肌肉。外周神经兴奋是梯度场安全的上限指标。在足够强度下，可以产生外周神经兴奋（如刺痛或叩击感），甚至引起心脏兴奋或心室振颤。（3）射频场（RF）的致热效应：RF致热效应被认为是组织温度升高的唯一方式，因为它能穿透表层组织，直接加热组织内部。以眼睛为例，血管相对缺乏，因此散热慢且效率低，在RF辐射作用下有可能对视组织造成热损伤。（4）噪声：MRI运行过程中产生的各种噪声，可能使某些患者的听力受到损伤。患者可有烦躁、语言交流障碍、焦虑、短时失聪和潜在的永久性听力损害。据此可知A、B、C三项正确。磁共振仪在工作时，会在人体周围产生一个超强磁场，接着向人体发射电磁波。但是电磁波对人的辐射危害极小，甚至都比不上你出去晒太阳时紫外线对你的伤害，真正有害的是CT等，故D项错误。本题为选非题，故正确答案为D。", "tag": "科技常识"},
{"id": "tech-356", "q": "下列做法正确的是：", "options": ["用湿土包裹保存新鲜土豆", "用铁罐存放冷却的浓硫酸", "用铝制器皿泡制老醋花生", "用顶部带气孔的玻璃坛制作泡菜"], "a": 1, "e": ".【B】本题考查人文科技知识。A项：错误，用湿土保存土豆湿度过大，会导致土豆霉烂。B项：正确，浓硫酸具有强氧化性，会与铝、铁等金属发生钝化作用，使金属表面形成致密的钝化膜，起到隔绝反应物的作用。C项：错误，食醋的主要成分——醋酸能与活泼金属铝反应，加快了铝制品的腐蚀，不适宜用铝制器皿泡制老醋花生。D项：错误，制作泡菜要密封，因为有氧条件下会抑制乳酸菌的发酵。故正确答案为B。", "tag": "科技常识"},
{"id": "tech-357", "q": "教练给某学员的便条上写道：今天你表现不错，跑位积极，速度达到每秒7 米，全场跑动距离达到1.3 千米，但要更注意与队友们的配合，毕竟60 分钟的比赛不是你一个人的战斗。据此可知，该教练最可能从事的运动是：", "options": ["足球", "马拉松", "篮球", "橄榄球"], "a": 3, "e": ".【D】本题考查运动常识，需结合题目具体分析。A项：错误，足球运动分为上下半场，每个半场时间为45分钟，全场比赛为90分钟，与题干中的60分钟的比赛时间不符。B项：错误，学员速度达到每秒7米，全场跑动距离达到1.3千米，表明是一项爆发力的运动，马拉松全长42.195千米，是耐力型运动，速度不可能达到每秒7米，且与全场跑动距离1.3千米不符。C项：错误，篮球运动比赛共分4节，每节10分钟或12分钟，总共比赛时长为40分钟或48分钟，跟题干中所说的60分钟的比赛时间不符合。D项：正确，橄榄球运动属于爆发性的运动，需要运动员具备很快的速度，且是一项团体运动，需要队员配合才能取得胜利。标准的美式橄榄球比赛分为四节，每节15分钟，共60分钟。故正确答案为D。", "tag": "科技常识"},
{"id": "tech-358", "q": "以下不属于导致听力下降、听力减退原因的是：", "options": ["太多的噪音伤害了内耳中的细毛", "经常用耳勺掏挖耳朵碰伤了耳道", "精神压力过大导致内耳供血障碍", "戴耳机听音乐导致听觉中枢受损"], "a": 1, "e": ".【B】B项错误：耳道是一条自外耳门至鼓膜的弯曲管道，碰伤耳道并不会引起听力下降、听力减退；如果洁耳过度导致破坏鼓膜，则会引起听力下降、听力减退。A项正确：太多的噪音会导致内耳的微细血管经常处于痉挛状态，内耳供血减少，听力急剧减退。C项正确：如果经常处于急躁，恼怒的状态中，会导致体内植物神经失去正常的调节功能，使内耳器官发生缺血，水肿或产生听觉障碍，这样容易出现听力锐减。D项正确：听觉中枢受损容易导致中枢性耳聋。本题为选非题，故正确答案为B。", "tag": "科技常识"},
{"id": "tech-359", "q": "准备活动是指在比赛、训练和体育课正式开始前，为克服内脏器官的生理惰性，缩短进入运动状态的时间和预防运动创伤而进行的身体练习，为接下来的剧烈运动或比赛做好准备。下列不属于准备活动主要作用的是：", "options": ["提高中枢神经系统的兴奋性", "增加皮肤血流量以利于散热", "提高运动时对氧气的利用率", "提高机体的代谢水平"], "a": 2, "e": ".【C】C项错误：准备活动可以使肺通气量及心输出量增加，使工作肌能获得更多的氧气，而不是提高对氧气的利用率。A项正确：准备活动可以提高中枢神经系统的兴奋性，调节不良的赛前状态，使大脑反应速度加快，参加活动的运动中枢间相互协调，可以为正式练习或比赛时生理功能迅速达到适宜程度做好准备。B项正确：皮肤温在调节散热中起主导作用，而皮肤温的高低决定于皮肤血流量的大小，准备活动即为剧烈运动或赛前的热身活动，皮肤血流量增加可以使皮肤温升高，从而利于散热。D项正确：通过做准备活动，可使体温和肌肉温度升高，从而使酶的活性增高，使肌肉的代谢得到加强。本题为选非题，故正确答案为C。", "tag": "科技常识"},
{"id": "tech-360", "q": "关于垃圾分类处理，下列说法错误的是：", "options": ["速冻饺子的包装袋属于厨余垃圾", "塑料制品不可采用深度填埋的处理方法", "果皮等食品类废物可进行堆肥处理", "红色的收集容器用于收集有害垃圾"], "a": 0, "e": ".【A】A项符合题意：厨余垃圾是指居民日常生活及食品加工、饮食服务、单位供餐等活动中产生的垃圾，包括丢弃不用的菜叶、剩菜、剩饭、果皮、蛋壳、茶渣、骨头等，其主要来源为家庭厨房、餐厅、饭店、食堂、市场及其他与食品加工有关的行业。一次性餐具、食品包装袋都归类为“其他垃圾”。因此速冻水饺的包装袋不属于厨余垃圾。B、C、D项说法均正确。本题为选非题，故正确答案为A。", "tag": "科技常识"},
{"id": "tech-361", "q": "当遇到下列情况时，你的正确选择是：", "options": ["被农药污染的食品一定要充分煮熟再食用", "被毒蛇咬伤手臂后，应首先扎住伤口处的近心端", "进行人工呼吸过程中，吹气者应始终捏紧被救者的鼻孔", "处方药和非处方药都必须在医生的指导下购买和使用"], "a": 1, "e": ".【B】B项正确：被毒蛇咬伤手臂后，为防止蛇毒随血液经过心脏扩散到全身，应当首先用止血带扎住伤口处的近心端，防止血液流向心脏；A项错误：被农药污染的食品，即便充分煮熟，也没办法去除残留其中的有害物，故不宜食用；C项错误：进行人工呼吸时，吹气时要捏紧被救者的鼻孔，是为了防止气体从鼻腔逸出，无法进入被救者的肺部；但是吹气完毕后，应当松开被救者的鼻子，便于气体交流，等下次吹气时再捏紧被救者的鼻子；D项错误：处方药必须凭执业医师或执业助理医师的处方才可调配、购买和使用；但非处方药不需要医师或其它医疗专业人员开写处方即可购买。故正确答案为B。", "tag": "科技常识"},
{"id": "tech-362", "q": "吸烟严重威胁人体健康。针对香烟产生的各种有害物质的描述，下列说法错误的是（）。", "options": ["尼古丁可让吸烟者成瘾，并有较强的毒性", "烟焦油易沉积于肺等器官，可诱发癌变", "香烟燃烧时物质分解放出的射线可以致癌", "一氧化碳易溶于水，从而与血红蛋白结合"], "a": 3, "e": ".【D】吸烟严重威胁人体的健康，香烟燃烧时释放的烟雾中含有3800多种已知的化学物质，绝大部分对人体有害，其中包括一氧化碳、尼古丁等生物碱、胺类、腈类、醉类、酚类、烷烃、醛类、氮氧化物，多环芳烃、杂环族化合物、羟基化合物、重金属元素、有机农药等。香烟中含有的尼古丁可以使吸烟者成瘾，并有较强的毒性，A项说法正确。烟焦油易沉积于肺等器官，可诱发癌变，B项说法正确。C选项中香烟燃烧时物质分解放出的射线可以致癌的表述，目前科学界对此缺乏公认的理论，说法也不一，香烟中的致癌物目前我们通常认为是多环芳香烃和亚硝胺之类的化合物，但据最权威的美国《科学》杂志公布的一项调查研究表明：香烟燃烧时产生的钋210的放射性射线辐射会有2%的几率致癌，符合题干可以致癌的表述。D项一氧化碳更容易和血红蛋白结合的原因是：一氧化碳与血红蛋白的亲和力比氧和血红蛋白的亲和力大200－300倍而非易溶于水，二者无因果关系，且一氧化碳的物理性质之一是可（此处有争议，一种说法为微溶，一种为难溶，但没有易溶的说法）溶于水，而非易溶于水。C项表述缺乏严谨的理论依据，但是得到主流科学媒体的认同，D项无因果关系且有表述错误。故正确答案为D。", "tag": "科技常识"},
{"id": "tech-363", "q": "下列对日常生活现象的解释正确的是：", "options": ["自行车在夏天暴晒后容易爆胎，是因为橡胶在高温下变软了", "夏天从冰箱里取出的冷饮瓶表面有小水滴，是因为冰箱湿度大于室内", "赤脚站在瓷砖上比站在棉被上凉爽，是因为瓷砖的温度比棉被的温度低", "热水瓶的内胆镀银是为了减少热辐射"], "a": 3, "e": ".【D】A项错误：自行车在夏天暴晒后容易爆胎，是因为暴晒后车胎中的气体会膨胀，造成胎内气压增大，从而使车胎膨胀，当车胎的膨胀程度超过自身能承受的最大限度时，就会出现爆胎。这属于热胀冷缩原理。B项错误：冷饮瓶表面的小水滴是由于气体液化形成的。冷饮瓶从冰箱取出时，瓶身的温度低于周围环境的温度，当瓶身周围空气中的水蒸气遇到较冷的瓶身时，就会液化成小水滴，附着在瓶身上。C项错误：赤脚站在瓷砖上比站在棉被上凉爽，是因为瓷砖的导热性好，赤脚站上去后身体的热量很快被传导开，而棉被的导热性较差，会将热量聚集在触摸点周围。D项正确：热水瓶的内胆镀银可以形成银镜反应，通过镜面反射把保温瓶内部的热辐射反射回保温瓶内部，就不会出现对外的热辐射，从而减少热量散失，达到保温效果。故正确答案为D。", "tag": "科技常识"},
{"id": "tech-364", "q": "下列关于生活常识的说法错误的是：", "options": ["电脑显示器的背面比正面辐射强", "汽车耗油量通常随着汽车排气量上升而增加", "乱丢的废电池可造成人体镉中毒、锰中毒、汞中毒", "复印机在复印过程中会产生二氧化硫从而损害人体健康"], "a": 3, "e": ".【D】D项错误：复印机在复印过程中，由于静电作用会产生一定浓度的臭氧，长期吸入会损害人体健康。A项正确：电脑显示器辐射最强的是背面，其次为左右两侧,屏幕正面辐射最弱。B项正确：汽车耗油量跟汽车排气量有关，通常汽车耗油量会随排气量上升而增加。C项正确：电池含有镉、锰、汞等重金属元素，这些重金属均有毒性。废电池乱丢可能污染空气和食物，导致人体镉中毒、锰中毒、汞中毒。本题为选非题，故正确答案为D。", "tag": "科技常识"},
{"id": "tech-365", "q": "在日常生活中，佩戴饰品有一定的学问和讲究，下列不符合饰品佩戴礼仪的是：", "options": ["同时佩戴多种饰品，一般不应超过3 种", "佩戴饰品应与性别、年龄、职业等匹配", "戒指戴在中指上，一般表示已婚", "佩戴两种以上饰品，一般要求同质"], "a": 2, "e": ".【C】A、B、D三项均正确，是佩戴饰品的基本礼仪。C项错误：戒指戴在中指上表示已有意中人，正处在恋爱之中；戴在无名指上表示已订婚或结婚；戴在小手指上则暗示自己是一位独身者；戴在食指上，表示无偶或求婚。本题为选非题，故正确答案为C。", "tag": "科技常识"},
{"id": "tech-366", "q": "下列说法不正确的是：", "options": ["眨眼可以湿润眼球，正常人平均每分钟要眨眼十几次", "小孩多理发能有效促进头发长得更快、更密、更粗壮", "当我们停止运动后，肌肉会变软，但不会变成脂肪", "眼泪中溶有许多不同的盐，所以是咸的"], "a": 1, "e": ".【B】A项：正常人的眼皮，每分钟大约要眨动15次，可以起到清洁和湿润眼球的作用，正确。B项：人的头发，是从头皮里面的毛囊长出来的。剪掉或者刮掉头皮外面的头发，头皮内的毛囊是没法知道的，更不可能存在一个反馈系统，促使毛囊长出更多更密的头发来。剃光孩子的头发，新长出的头发是显得更加密一些更加粗一些，其实这只是因为剃光了头发，新头发长出来时，不再像原来的头发那样长短不一，而是同一时间一起生长，自然就显得比起原始头发厚一些。孩子头发的浓密与否、粗细颜色，主要取决于家庭遗传，加上后天的营养和保养，错误。C项：当停止力量练习后，原本紧张结实的肌肉就会变得松弛、萎缩，不会变成脂肪，正确。D项：眼泪中溶有许多不同的盐，食物中的盐分被肠道吸收后进入血液。眼泪是由泪腺分泌的，当血液流过泪腺时，部分盐分便随之渗入眼泪中了，正确。本题为选非题，故正确答案为B。", "tag": "科技常识"},
{"id": "tech-367", "q": "冰冻的肉类在水中比在同温度的空气中解冻得快，这是因为：", "options": ["水的热容量比空气大", "水的密度比空气大", "水的热传递性比空气好", "水和冰的化学成分完全相同"], "a": 2, "e": ".【C】冰冻的肉类在水中比在同温度的空气中解冻得快，这是因为水的热传递性比空气好，水能够较快的将热量转移给冻肉，使其更快解冻。故正确答案为C。", "tag": "科技常识"},
{"id": "tech-368", "q": "举重运动员、体操运动员比赛前，会抓一些白色粉末（主要成分是碳酸镁）涂抹在手掌上，来增加手掌与器械之间的摩擦力。这主要是利用碳酸镁的：", "options": ["润滑作用", "吸湿作用", "中和作用", "保温作用"], "a": 1, "e": ".【B】碳酸镁具有很强的吸湿作用。举重运动员、体操运动员在比赛时，手掌心常会冒汗，而湿滑的掌心会使摩擦力减少，因此在赛前涂抹些碳酸镁，能够吸去掌心汗水，从而增加掌心与器械之间的摩擦力，使运动员能握紧器械，提高动作质量。故正确答案为B。", "tag": "科技常识"},
{"id": "tech-369", "q": "蜻蜓点水是指蜻蜓在水面飞行时轻触水面的动作，其主要是为了：", "options": ["求偶", "饮水", "产卵", "呼吸"], "a": 2, "e": ".【C】蜻蜓的幼虫要生活在水里，为繁衍后代，蜻蜓要在有水的地方产卵。因此，蜻蜓点水实为蜻蜓产卵，卵排到水中，附在水草上，不久便孵出幼虫。故正确答案为C。", "tag": "科技常识"},
{"id": "tech-370", "q": "世界各国由于各自不同的经济与政治状况，形成了不同的城镇化发展模式。下列对应全部正确的是：①欧洲——市场主导，自由发展②韩国、日本——政府推动，短期迅速发展③拉美国家——受殖民地经济制约④美国——政府调控，长期逐步发展", "options": ["②③", "①④", "③④", "①②"], "a": 0, "e": ".【A】美国是市场经济的典型代表，其一贯坚持和主张由市场主导调节经济，因此，在城镇化的建设中也坚持市场占主导地位，政府较少进行干预或调控。因此，④错误。相比美国完全市场化的城镇化发展模式，西欧国家的城镇化虽然依然建立在市场机制的基础上，但政府的调控在城镇化发展过程中发挥了更大的作用。政府通过法律、行政和经济手段，有效地引导城镇化健康发展，在土地、住房、交通、环境等各个方面，政府都发挥着不可替代的作用。因此，①错误。受历史上长期西方殖民统治的影响，拉美国家城镇化的特点是工业化发展严重落后于城镇化步伐，造成了城镇化的过度发展。拉美国家由于城镇化水平与西方国家接近，但是经济发展水平却远远低于西方国家，从而引发了一系列的“城市病”。因此，③正确。以日本、韩国为代表的亚洲工业化国家的城镇化道路被称之为“东亚模式”，城市化速度较快，经济发展史上称之为“东亚奇迹”，且政府对于城镇化的引导作用比较显著。因此，②正确。故正确答案为A。", "tag": "科技常识"},
{"id": "tech-371", "q": "下列成语与工艺技术或行业对应不正确的是：", "options": ["量凿正枘——木工", "锦上添花——纺织", "炉火纯青——冶炼", "青出于蓝——陶瓷"], "a": 3, "e": ".【D】A项正确，“量凿正枘”指木工度量器物孔眼的大小方圆制作可与之相契合的榫头，后比喻说话办事须从实际出发。B项正确，“锦上添花”指在锦上再绣花，比喻好上加好，美上添美，“锦”为丝织品。C项正确，“炉火纯青”原指道士炼丹炼到炉里发出纯青色的火焰就算成功了，后比喻功夫造诣已达到了精湛、纯熟、完美的境界，古代的炼丹和冶炼技术互有助益，都要用到高温焙烧，也就是“炉火纯青”。D项错误，“青出于蓝”意指青从蓝草中提炼出来，但颜色比蓝草更深，比喻学生超过老师或后人胜过前人。这一说法没有特定的行业或技术指向。本题为选非题，故正确答案为D。", "tag": "科技常识"},
{"id": "tech-372", "q": "下列关于自然现象的说法错误的是：", "options": ["霾通常呈黄色或橙灰色，吸入后有害", "露水会对农作物的生长造成危害", "雾和云是由于温度下降造成的", "彩虹有时会同时出现两条"], "a": 1, "e": ".【B】A项正确，霾是由空气中的灰尘、硫酸、硝酸、有机碳氢化合物等粒子组成的，能使大气浑浊，视野模糊并导致能见度恶化。硫酸、灰尘等离子多呈黄色或橙灰色，吸入后对人体有害。B项错误，露水能滋润土壤起到帮助植物生长的作用，有利于田庄的作物对已积累的有机物进行转化和运输，对农作物的生长是有利的。C项正确，云、雾主要是空气中的水蒸气遇冷凝聚成小水滴而形成的。D项正确，彩虹是阳光穿过空气中的小水滴发生折射而产生的，若光线在水滴内进行了两次反射，便会产生第二道彩虹。本题为选非题，故正确答案为B。", "tag": "科技常识"},
{"id": "tech-373", "q": "下列谚语与农业生产经验不符的是：", "options": ["人在屋里热得跳，稻在田里哈哈笑", "麦苗盖上雪花被，来年枕着馍馍睡", "立秋无雨样样有，立秋有雨收半秋", "下秧太冷怕烂秧，小秧出水怕青霜"], "a": 2, "e": ".【C】A、D两项正确，表述了气温与农业收成的关系，排除；B项正确，表述了降雪与农业收成的关系，排除；C项错误，应是“立秋有雨样样有，立秋无雨收半秋”。立秋这天无雨预示着秋季会比较干旱，影响收成，当选。本题为选非题，故正确答案为C。", "tag": "科技常识"},
{"id": "tech-374", "q": "对下列道路交通标志解释不正确的是：", "options": ["注意儿童", "注意行人", "前方有施工", "“徒步”旅游区"], "a": 1, "e": ".【B】根据标志及解释可知A、C、D三项解释正确，B项解释错误，图标代表禁止行人通行，而不是注意行人。本题为选非题，故正确答案为B。", "tag": "科技常识"},
{"id": "tech-375", "q": "从3 月下旬到10 月上旬，太阳在地球上直射位置的移动规律是：", "options": ["赤道→南回归线→赤道", "赤道→北回归线→赤道", "南回归线→赤道→北回归线", "北回归线→赤道→南回归线"], "a": 1, "e": ".【B】根据太阳在地球上直射位置的移动规律可知，春分（3月20日或21日）时太阳直射赤道，随后逐渐北移。夏至（6月21或22日）时，太阳直射北回归线，后南移。秋分（9月22或23日）时太阳直射赤道，之后继续南移。冬至（12月21或22或23日）时直射南回归线。故正确答案为B。", "tag": "科技常识"},
{"id": "tech-376", "q": "关于地球生物演化史，下列哪组排序是正确的？", "options": ["蓝藻→蕨类→裸子植物→被子植物", "节肢动物→草履虫→软体动物→脊椎动物", "细菌→腔肠动物→爬行类→鱼类", "苔藓→绿藻→菌类→双子叶植物"], "a": 0, "e": ".【A】A项正确，根据地球生物演化史；B项错误，单细胞生物应该在节肢动物之前，草履虫是单细胞生物，故正确顺序应为：草履虫→软体动物→节肢动物→脊椎动物；C项错误，鱼类应该在爬行类之前，故正确顺序应为：细菌→腔肠动物→鱼类→爬行类；D项错误，植物进化第一阶段是菌藻植物时代，而后是蕨类植物时代，故正确顺序应为：菌类→绿藻→苔藓→双子叶植物。故正确答案为A。本题相关知识点：地质年代从古到今是：太古代、元古代、古生代、中生代和新生代。有些代进一步划分为若干“纪”，如古生代从远到近划分为寒武纪、奥陶纪、志留纪、泥盆纪、石炭纪和二叠纪；中生代划分为三叠纪、侏罗纪和白垩纪；新生代划分为第三纪和第四纪。不同的地质年代有不同的特征。距今24亿年以前的太古代，地球表面已经形成了原始的岩石圈、水圈和大气圈。这是铁矿形成的重要时代，最低等的原始生命开始产生。距今24亿—6亿年是元古代。到了晚期，地球上出现了大片陆地。“元古代”的意思就是原始生物的时代，这时出现了海生藻类和海洋无脊椎动物。距今6亿—2.5亿年是古生代。海洋中出现了几千种动物，海洋无脊椎动物空前繁盛。以后出现了鱼类动物，一种用鳍爬行的鱼登上陆地，成为陆上脊椎动物的祖先。两栖类也出现了。北半球陆地上出现了蕨类植物，后来变成大片的煤田。距今2.5亿—0.7亿年是中生代，这是爬行动物的时代，这时也出现了原始的哺乳动物和鸟类。蕨类植物日趋衰落，而被裸子植物取代。距今7000万年左右的新生代是地球历史上最新的一个阶段。被子植物大发展，各种食草、食肉的哺乳动物空前繁盛，最终导致人类的出现。一般认为，人类是第四纪出现的，距今约有240万年的历史。", "tag": "科技常识"},
{"id": "tech-377", "q": "下列表述正确的是：", "options": ["人的唾液是由舌头分泌的", "胆分泌胆汁不足，容易导致胆囊炎", "食盐、鱼肝油可被消化道直接吸收", "正常情况下，卵细胞在子宫内受精"], "a": 2, "e": ".【C】A项错误，人的唾液是由口腔内的唾液腺分泌的，而不是由舌头分泌的；B项错误，首先，胆汁是由肝脏分泌到胆囊中，胆囊再排出的；其次，胆汁成分改变会引起胆囊炎，胆汁分泌不足，并不意味着成分发生变化，故不会产生胆囊炎，反而胆汁的排泄受阻会引发胆囊炎；C项正确，食盐、鱼肝油可以被消化道直接吸收；D项错误，正常情况下，卵细胞在输卵管内受精，在子宫内发育。故正确答案为C。", "tag": "科技常识"},
{"id": "tech-378", "q": "在超市里常常看到牛奶装在方形的容器中出售，而碳酸饮料则常装在圆形的容器中出售。下列关于此现象的原因解释不合理的是：", "options": ["视觉上圆形比方形更柔和舒缓，吸引更多的顾客购买", "圆柱形易拉罐下底可做成半球形凹槽以承受更大的压力", "牛奶通常需要存放在冷藏柜中，立方体容器更节约空间", "碳酸饮料通常直接用包装罐饮用，圆柱体拿在手里更舒服"], "a": 0, "e": ".【A】A项不合理，如果形状能吸引更多的顾客，进而带来巨大的收益的话，那么商家都会选择该种形状；B、D项合理，讲的是圆形容器的优点；C项合理，讲的是方形容器的优点。本题为选非题，故正确答案为A。", "tag": "科技常识"},
{"id": "tech-379", "q": "现代生活中，手机的普及和应用给人们的生活带来了极大的便利，但在现实生活中，使用手机时也需要注意安全。以下安全问题不是由于手机无线通讯引起的是：", "options": ["在加油站不能打手机", "坐飞机时不能打手机", "驾驶机动车时不能打手机", "在使用医疗器械的病区不能打手机"], "a": 2, "e": ".【C】A项，加油机普遍采用电脑控制，手机信号会影响设备工作，导致计量不准，更重要的是，手机拨打过程中出现的火花极易引起爆炸，不仅在加油站内，加油站周围二三米之内也不能打手机；B项，手机可能会干扰地空通信，本着安全第一的原则，坐飞机不能打手机；C项，驾驶机动车不能打手机是因为打手机会分散驾驶员的注意力从而可能引发交通事故，其安全问题不是由手机无线通信引起的，C项表述符合题干要求，当选；D项，许多医院都有关于禁止使用手机的规定，因为他们担心手机辐射可能干扰各种救生设备的正常工作。A、B、D三项中的安全问题均和手机无线通讯有关，予以排除。本题为选非题，故正确答案为C。", "tag": "科技常识"},
{"id": "tech-380", "q": "冰是水在低温条件下的一种形态，然而生活中发现，在我国北方的冬季，河流往往是表面结冰而深层依然是流动的水。对于此种现象，原因是：", "options": ["水固化成冰时会释放出热量", "表面冰层具有隔热保温作用", "水在0℃左右具有热缩冷涨的性质", "气温尚未低到使河流整体冰冻的程度"], "a": 1, "e": ".【B】冰的密度小所以浮在水面上，由于冰是热的不良导体，对下层的水起到了隔热保温的作用。故正确答案为B。", "tag": "科技常识"},
{"id": "tech-382", "q": "下列有关生活常识的说法，不正确的是（）。", "options": ["夏天不宜穿深色衣服，深色衣服比浅色衣服更易吸收辐射热", "驱肠虫药若饭后服用，不易达到最好的驱虫效果", "在汽车玻璃清洗液中加入适当比例的酒精，可使其抗冻效果更好"], "a": 2, "e": ".【C】本题考查衣食住行等生活中常见事物的相关知识。A项，从物理的角度讲，黑色吸收所有光线，白色反射所有光线，所以相比于浅色衣服，深色衣服更容易吸收阳光中的辐射热，不宜在夏天穿着。该项表述正确。B项，驱肠虫药一般空腹服用，此时肠胃食物已经排空，药物易与虫体充分接触，驱虫效果较好。该项表述正确。上方偏南的时间较长，所以楼间距可以适当缩小。该项表述错误。D项，酒精的凝固点低，在10度左右时水凝固而酒精不会凝固，所以在汽车玻璃清洗液中加入酒精能够提升抗冻效果。该项表述正确。本题为选非题，故正确答案为C。", "tag": "科技常识"},
{"id": "tech-383", "q": "下列关于日常生活中的做法，不正确的是：", "options": ["为了使用方便和最大限度地利用材料，机器上用的螺母大多是六角形", "在加油站不能使用手机，是因为手机在使用时产生的射频火花很容易引起爆炸，发生危险", "交通信号灯中红色被用做停车信号是因为红色波长最长", "家中遇到煤气泄漏事件应立即使用房间的电话报警"], "a": 3, "e": ".【D】D项错误，打电话时会产生微弱电流，遇到煤气可能发生爆炸。A、B、C三项均正确。本题为选非题，故正确答案为D。", "tag": "科技常识"},
{"id": "tech-384", "q": "下列做法在日常生活中的可行的是：", "options": ["医用酒精和工业酒精的主要成份相同，都可用于伤口消毒", "喝牛奶、豆浆等富含蛋白质的食品可有效缓解重金属中毒现象", "由于淀粉有遇碘变蓝的特性，可利用淀粉检验加碘食盐的真假", "低血糖症状出现时，吃馒头要比喝葡萄糖水见效快"], "a": 1, "e": ".【B】B项正确，误服重金属会使人体内组织中的蛋白质变性而中毒，如果立即服用大量鲜牛奶、蛋清、豆浆，可使重金属跟牛奶、蛋清、豆浆中的蛋白质发生变性作用，从而减轻重金属对机体的危害；A项错误，工业酒精与医用酒精的主要成分——乙醇相同，但是工业酒精中含有部分甲醇，而甲醇对人体有害，不能直接用于伤口消毒；C项错误，遇淀粉变蓝的是碘单质，而食盐中的碘为碘酸钾，为一种稳定的化合物，不会有本选项所说的效果；D项错误，馒头中的淀粉需要经过消化吸收才能转化为葡萄糖，故产生效果的周期长。故正确答案为B。", "tag": "科技常识"},
{"id": "tech-385", "q": "下列关于汽油的说法不正确的是：", "options": ["汽油标号是实际汽油抗爆性与标准汽油抗爆性的比值", "为了保护汽车发动机，应尽量选用高标号的汽油", "汽油可以溶解油污等水无法溶解的物质，起到清洁油污的作用", "汽油着火时应使用泡沫、干粉等灭火剂，不能用水灭火"], "a": 1, "e": ".【B】本题考查生活常识。A项正确，汽油标号是实际汽油抗爆性与标准汽油抗爆性的比值。标号越高，抗爆性能就越强。抗爆性就是指汽油在发动机中燃烧时抵抗爆震的能力,它是汽油燃烧性能的主要指标。爆震是汽油在发动机中燃烧不正常引起的；B项错误，标准汽油是由异辛烷和正庚烷组成。并不是标号越高越好，要根据发动机压缩比合理选择汽油标号；C项正确，根据相似相溶原理，两者都是有机物，汽油能溶解油污等水无法溶解的物质，起到清洁油污的作用；D项正确，汽油着火用二氧化碳或干粉灭火器灭火，也可用干沙灭火。千万不能用水灭火，因为汽油比水轻的多，火会在水的面上流动，扩大火势。本题为选非题，故正确答案为B。", "tag": "科技常识"},
{"id": "tech-386", "q": "关于我国公益电话，下列对应错误的是：", "options": ["122——交通事故报警电话", "12121——网络举报电话", "12315——消费者投诉举报电话", "12306——全国铁路客户服务热线"], "a": 1, "e": ".【B】本题考查科技常识。B项错误，12121是气象信息查询电话，与气象台的天气预报电脑自动服务系统接通。C项正确，12315是消费者投诉举报专线电话，国家工商行政管理总局设立的专门受理消费者投诉举报的专用电话号码。D项正确，12306是全国铁路客户服务热线，是铁路服务客户的重要窗口，为社会和铁路客户提供客货运输业务和公共信息查询、预定等服务。本题为选非题，故正确答案为B。", "tag": "科技常识"},
{"id": "tech-387", "q": "城市大气污染的浓度通常与风速：", "options": ["成正比", "成反比", "无关系", "不定"], "a": 1, "e": ".【B】本题考查科技常识。城市大气污染的浓度通常与风速成反比，一般来说风速越大，空气流通交换速度越快，越有利于空气中污染物质的稀释扩散。故正确答案为B。", "tag": "科技常识"},
{"id": "tech-388", "q": "中药材的主要来源包括动物、植物、矿物等，下列哪一选项属于动物类药材？", "options": ["田七、阿胶", "地龙、牛黄", "龙骨、鸡内金", "决明子、蝉衣"], "a": 1, "e": ".【B】本题考查生活常识，主要考查医药常识。动物类药材是中医药学遗产中的重要组成部分。中医药学历来认为：动物类药材属“血肉有情之”，具有疗效确切、历史悠久等特点，而倍受重视。A项错误，田七是五加科人参属，属于植物类药材；阿胶是以驴皮为主要原料，放阿井之水而制成，属于动物类药材。B项正确，地龙即蚯蚓，属于动物类药材；牛黄是脊索动物门哺乳纲牛科动物牛肝脏的胆结石，属于动物类药材。C项错误，龙骨为古代哺乳动物如象类、犀牛类、三趾马等的骨骼的化石，属于矿物类药材；鸡内金是指家鸡的砂囊内壁，属于动物类药材。D项错误，决明子是一年生半灌木状草本，属于植物类药材；蝉衣是蝉科昆虫黑蚱羽化后的蜕壳，属于动物类药材。故正确答案为B。", "tag": "科技常识"},
{"id": "tech-389", "q": "下列哪种球类运动的场地面积最大？", "options": ["网球", "篮球", "排球", "足球"], "a": 3, "e": ".【D】排球场长度为18米，宽度为9米。篮球场地长28米，宽15米，是一个长方形的平面。一片标准网球场地的占地面积不小于648平方米(南北长36米，东西宽18米)。足球场地长度90~120米，宽度45~90米。由此可知，足球场地面积最大。所以A、B、C三项错误。故正确答案为D。", "tag": "科技常识"},
{"id": "tech-390", "q": "下列说法中，不正确的是：", "options": ["向保温瓶灌开水时，不应灌得过满，这样保温效果会更好", "使用燃气炉灶烧水或炒菜，锅底压住火头可使锅升温快", "锅铲等炊具的柄用木料或塑料制成，是因为木料及塑料是热的不良导体", "炒菜主要是利用热传导方式传热，煮饭、烧水主要是利用对流方式传热"], "a": 1, "e": ".【B】本题考查生活常识。A项正确，往保温瓶灌开水时，要在瓶口留存一层空气，因为空气是热的不良导体，能更好地防止热量散失，保温效果会更好，所以不应灌得过满；B项错误，燃气炉灶的火焰从内到外依次为焰心、内焰、外焰，其中外焰与空气充分接触，燃烧充分，温度最高。所以锅底放在火焰的外焰可以使锅快速升温，而不是压住火头；C项正确，我们用来做饭、炒菜的锅都是用利于传导热的金属制成的，目的就是让热量尽快地传给待加热的食物，但为了防止烫手，我们选用木头、塑料、皮革等属于热的不良导体来制作这些炊具的手柄；D项正确，热传导是指热量从系统的一部分传到另一部分或由一个系统传到另一系统的现象，是固体中热传递的主要方式。炒菜是通过铁锅与食物之间的热传导传热。对流是指液体或气体中较热部分和较冷部分之间通过循环流动使温度趋于均匀的过程，是液体和气体中热传递的特有方式，煮饭和烧水主要是利用水的对流传热。本题为选非题，故正确答案为B。", "tag": "科技常识"},
{"id": "tech-391", "q": "下列说法不正确的是：", "options": ["地震到来时，若来不及撤离，可以躲避到墙角处", "发生泥石流时，可以往泥石流的下游方向逃生", "深色蔬菜的营养素和抗氧化因子的含量较高", "吃鸡蛋过多，会造成血胆固醇含量过高，引起心脑血管疾病的发生"], "a": 1, "e": ".【B】本题考查科技常识。A项正确，发生地震时，若在楼房中来不及撤离，应选择厨房等空间小的空间避震，也可选择内墙、墙角、坚固的家具旁等易形成三角空间的地方，要远离外墙、门窗、阳台、楼梯，不可使用电梯，更不能选择跳楼。B项错误，发生泥石流时，应该马上向与泥石流成垂直方向的山坡上爬，爬得越高越好，跑得越快越好，绝对不能顺着泥石流的流动方向（即下游方向）走。C项正确，深色蔬菜营养素和抗氧化因子的含量较高。同一类蔬菜中，颜色深的品种营养价值更高，如深红色的番茄中番茄红素含量远高于粉红色的。叶菜中，深绿色的品种其维生素B2、叶酸、类黄酮等多种营养成分也高于浅绿色的，即使同一棵菜中，深色部分也要比浅色部分的营养成分含量更高。D项正确，鸡蛋中含有大量胆固醇，吃鸡蛋过多会使胆固醇的摄入量大大增加，造成血胆固醇含量过高，引起动脉粥样硬化和心、脑血管疾病的发生。本题为选非题，故正确答案为B。", "tag": "科技常识"},
{"id": "tech-392", "q": "下列有关生活常识的叙述，正确的是（）。", "options": ["火灾中如果身上着火要马上拍打", "早上蜘蛛网上有水珠表示要下雨", "衣服染上墨水用牛奶清洗效果好", "鱼刺卡在喉咙时可喝浓醋来消除"], "a": 2, "e": ".【C】A项错误，火灾发生时，如果身上着火，千万不要惊慌失措，东奔西跑或胡乱拍打。因为奔跑时形成的小风会使火烧得更旺，同时跑动还会把火种带到别处，引燃周围的可燃物；胡乱拍打，往往顾前顾不了后，在痛苦难熬中，一旦支持不住，就会造成严重烧伤，甚至丧失生命。所以，一旦不幸身上着火，首先应该设法脱掉衣帽。如果来不及脱掉，可以把衣服撕破扔掉。若这都来不及做，可以在没有燃烧物的地方倒在地上打滚，将身上的火苗压灭。B项错误，早晨蜘蛛网上有水珠表示天晴。天气晴朗的日子里,早上温度低，使空气中的水蒸气凝结成小水珠，挂在蜘蛛网上闪烁着，通常天气不会下雨。下雨的征兆有青蛙鸣叫、燕子低飞、蚂蚁过马路、蚯蚓出洞等。蜘蛛露天结网如果是和地面平行的，大部分的时间则预示着不会下雨；若是和地面垂直的，绝大多数时间应该是要下雨的。C项正确，衣物上的蓝墨水污迹，可用牛奶搓揉浸洗。D项错误，虽然酸性物质能分解软骨，但必须是高浓度的强酸。鱼骨头卡在喉咙的时候最好不要喝醋、因为在短时间鱼骨头是不会被醋酸软化而被弄掉的，“吃”醋反而造成了咽喉黏膜广泛性灼伤。故正确答案为C。", "tag": "科技常识"},
{"id": "tech-393", "q": "若遇到突发事件，下列做法正确的是：", "options": ["发生胸腹损伤事故时，应该使病人平躺，保持呼吸通畅", "发现有人触电，应迅速用手将触电者拉离电源", "夜间发现煤气泄漏时，应尽快打开油烟机或排气扇稀释燃气浓度", "在半山腰遇见森林火灾时，应迅速向山顶奔跑逃生"], "a": 0, "e": ".【A】B选项中发现人触电时首先要切断电源或用绝缘体将电线挑开，不能直接用手去拉，这样做也会触电；C选项中煤气泄漏时不应开关电器，开关电器可能产生电火花引燃煤气一起爆炸；D选项发生森林火灾时，一般由于温度高的原因，火会往山上燃烧，所以被大火包围在半山腰时，要快速向山下或有道路的两侧跑，切忌往山上跑；A选项胸腹受伤后，为了避免二次伤害及保证伤者呼吸顺畅，应使病人平躺。故正确答案为A。", "tag": "科技常识"},
{"id": "tech-394", "q": "关于奥林匹克运动会，下列说法正确的是：", "options": ["国际奥委会的总部设在美国纽约", "首位夺得奥运会柔道女子冠军的是中国选手", "2016 年奥运会将在日本东京举办", "第一届现代奥运会是在英国伦敦举行的"], "a": 1, "e": ".【B】A项错误，国际奥委会的总部设在瑞士洛桑；B项正确，首位夺得奥运会柔道女子冠军的是中国选手庄晓岩（在", "tag": "科技常识"},
{"id": "tech-395", "q": "下列关于医学常识的说法，错误的是：", "options": ["站立服药时食道呈现自然垂直状态，有利于药物下行到胃内，便于尽快吸收", "服热性药时应配食热性食物，服凉性药时应配食凉性食物，否则影响药效", "给伤口消毒用酒精并非纯度越高越好", "给病人输氧时，输纯氧效果最好"], "a": 3, "e": ".【D】D项错误，纯净的氧是有毒的，所以给病人输氧并不是越纯越好；A、B、C项正确。本题为选非题，故正确答案为D。", "tag": "科技常识"},
{"id": "tech-396", "q": "以下三种食品安全标志所代表的产品标准对产品的要求由高到低排列正确的是：", "options": ["①②③", "①③②", "③①②", "②③①"], "a": 1, "e": ".【B】B项正确，无公害农产品是绿色食品和有机食品发展的基础，绿色食品和有机食品是在无公害农产品上的进一步提高，有机食品较绿色食品的标准更加的严格；A、C、D三项错误。故正确答案为B。", "tag": "科技常识"},
{"id": "tech-397", "q": "在发生泥石流时，下列做法正确的是：", "options": ["发现泥石流后，要马上向与泥石流成垂直方向一边的山坡爬", "发生山体滑坡时，要马上沿着滑坡方向尽力奔跑", "发生泥石流时，在沟底尽力爬到大树上进行躲避，等待救援", "沿山谷徒步行走时，一旦遭遇大雨，发现山谷有异常的声音或听到警报时，应立即找寻较大的洞穴或巨石躲避，等大"], "a": 0, "e": ".【A】遇到泥石流灾害，采取脱险逃生的办法有：沿山谷徒步行走时，一旦遭遇大雨，发现山谷有异常的声音或听到警报时，要立即向坚固的高地或泥石流的旁侧山坡跑去，不要在谷地停留。一定要设法从房屋里跑出来，到开阔地带，尽可能防止被埋压。发现泥石流后，要马上向与泥石流成垂直方向一边的山坡上面爬，爬得越高越好，跑得越快越好，绝对不能向泥石流的流动方向走。发生山体滑坡时，同样要向垂直于滑坡的方向逃生。要选择平整的高地作为营地，尽可能避开有滚石和大量堆积物的山坡下面，不要在山谷和河沟底部扎营。故正确答案为A。", "tag": "科技常识"},
{"id": "tech-398", "q": "为节约用水和减少污水排放，一些住宅小区对生活污水中的灰水和黑水进行分离处理，并采用了中水回用处理技术，以下关于中水、灰水、黑水的表述，错误的是：", "options": ["中水一般是指污水经过处理后的出水，水质介于上水（给水）和下水（污水）之间", "灰水和黑水都可以作为中水回用系统的水源", "从盥洗室、洗澡间和厨房等流出的洗涤废水是灰水", "呈黑色的废水都是黑水"], "a": 3, "e": ".【D】粪便污水指的是居民日常生活中排泄的洗涤水。国外把粪便污水又称为黑水，与黑水相对的另一概念是灰水。国外的黑水定义有两种，一种定义为含有粪便物质的生活污水；另一种定义为厕所污水，包括冲厕水和粪便，所以D项说明错误。本题为选非题，故正确答案为D。", "tag": "科技常识"},
{"id": "tech-399", "q": "煤、石油与天然气并称为“三大化石燃料”，下列关于它们的说法错误的是：", "options": ["天然气易溶于石油而难溶于水", "石油的密度一般比水小", "“乌金”是煤的美称", "石油的导电性较好"], "a": 3, "e": ".【D】导电必须产生离子，就是说必须是酸性或者碱性，或者是盐类也可以；但是油属于烃类，属于不会导电的碳和氢组成的碳氢化合物。由此可见，石油中并不含有能使物体导电的电子、离子等，所以石油不是导体，因此它不导电。所以D项错误。A、B、C三项均正确。本题为选非题，故正确答案为D。", "tag": "科技常识"},
{"id": "tech-400", "q": "下列关于激光的说法不正确的是：", "options": ["激光器输出的光颜色极纯，是因为波长分布范围很宽", "激光的理论基础起源于爱因斯坦的“受激辐射”理论", "激光对人体的伤害中，以对眼睛的伤害最为严重", "激光的波长取决于发出激光的活性物质"], "a": 0, "e": ".【A】A项错误，激光器输出的光，波长分布范围非常窄，因此颜色极纯。以输出红光的氦氖激光器为例，其光的波长分布范围可以窄到纳米，是氪灯发射的红光波长分布范围的万分之二。由此可见，激光器的单色性远远超过任何一种单色光源。B、C、D三项均正确。本题为选非题，故正确答案为A。", "tag": "科技常识"},
{"id": "tech-401", "q": "上海至洛杉矶的直飞航班正常飞行时间为11 小时30 分左右，而返程则需约14 小时15 分左右，造成这种现象的主要原因是：", "options": ["地势高低", "两地时差", "地球磁场", "空中风向"], "a": 3, "e": ".【D】造成这种现象的主要原因是：（1）风向原因。顺风逆风有明显的区别，在顺风中飞行时，飞机的实际速度为空速加风速，而逆风时反之。（2）航路问题。特别是在远程航线，为了安全，飞机并不是直线飞行。（3）地球自转的因素。如果向西飞，加上地球自转就会很快到达，反之，向东飞存在需要追赶地球自转的因素。所以，在往返西部和东部地区时，即使为同一航线往返，受空中风向的影响，由上海飞洛杉矶的飞行时间较返程的时间更短。故正确答案为D。", "tag": "科技常识"},
{"id": "tech-402", "q": "以下做法中，所运用的科学原理与其他三项不同的是：", "options": ["烹饪海鲜时加入柠檬汁以去除腥味", "服用小苏打可以治疗某些类型的胃痛", "在蜜蜂蜇后的伤口涂抹氨水以减轻疼痛", "在被污染的湖泊中培育水藻吸收过量的氮和磷"], "a": 3, "e": ".【D】A项：海鲜汁呈酸性，加入柠檬汁后由于柠檬汁为碱性，起到了中和作用，以便达到去除腥味的目的；B项：小苏打为弱碱，胃痛主要由胃酸引起，服用小苏打后，与胃酸发生中和反应，降低了胃酸的浓度；C项：蜜蜂毒液呈酸性，涂抹氨水后与毒液发生中和反应，能够起到缓解疼痛的作用；D项：被污染的湖泊中培育水藻吸收过量的氮和磷，是自然的分解过程。A、B、C都属于中和反应。本题为选非题，故正确答案为D。", "tag": "科技常识"},
{"id": "tech-403", "q": "当在建筑物内发生火灾时，在逃生过程中，不应该：", "options": ["一直朝着有亮光的方向逃生", "通过天窗爬上屋顶", "利用建筑物的落水管等竖直管线下滑至地面", "利用阳台、毗邻平台逃生"], "a": 0, "e": ".【A】本题为争议题。A项，在火场内确实不能朝着有亮光的地方跑，因为亮光的地方极有可能正在发生燃烧，但脱离火场之后可以朝着其他灯光的地方跑，有灯光的地方一般会有人经过，容易得救。B项，建筑物发生火灾首先要判断自己所处的楼层位置，如果自己在火灾楼层的下方且距离较近，不要往上跑，如果自己在火灾楼层的上方且距离较近，不要往下跑，以免误入火场。如果处于火灾楼层上方，又无其他办法，情况紧急在四周已被烟雾包围的情况下，应积极自造或寻找避难处所，如高层露台、楼顶平台、可打开的窗户等处，但由于天窗等闭锁造成伤亡也时有发生。C项，有些建筑物外侧有落水管等竖直的管线，确保自身安全的情况下可沿该管至地面，然后安全逃生。D项，阳台以及毗邻的平台关键时刻也可以用以躲避火灾进行逃生。火场逃生一定要结合当时的实际情况结合进行，切勿生搬硬套，弄巧成拙，但就本题而言AB都有不正确的地方，综合比较A项更符合题意。本题为选非题，故正确答案为A。", "tag": "科技常识"},
{"id": "tech-404", "q": "关于生活常识，下列表述不正确的是：", "options": ["打呵欠是一种深呼吸动作，吸入大量氧气，呼出二氧化碳", "向日葵从发芽到花盘盛开之前，其叶子和花盘在白天追随太阳从东转向西", "唐三彩由于斑斓的釉色常常被误认为是瓷器，其实它是陶器", "海水对光的吸收使得大海呈绿色或蓝色，海水深时是绿色，浅时是蓝色"], "a": 3, "e": ".【D】水对于各种光线的吸收是有选择的，不同深度的海水，吸收不同波长的光线。对光线里的红橙色长光波，海水吸收得多，但反射得少；对短波部分的蓝青色光波，海水吸收得少，却反射得多。海水深时是蓝色，浅时是绿色。海水的颜色主要由水分子和悬浮颗粒对光的散射所决定，所以混浊程度不同的海水颜色也不同。近岸的海水悬浮颗粒多，而且颗粒也大，所以从远海到近岸水域，海水颜色依次由深蓝逐渐变浅。在含沙量较多的河口附近，海水中有大量陆地植物分解产生的浅黄色物质，因此海水看上去为淡绿色。D项错误。本题为选非题，故正确答案为D。", "tag": "科技常识"},
{"id": "tech-405", "q": "下列说法正确的是：", "options": ["油锅起火立即用水扑灭，并迅速熄灭炉火", "电路保险丝（片）熔断，用铜线代替以保护电器", "身上着火，就地打滚，或用厚重衣物覆盖压灭火苗", "停电的夜晚发现煤气泄漏后，点燃蜡烛查找泄漏原因"], "a": 2, "e": ".【C】A项错误，油锅一旦起火，严禁用水往锅里浇，因为冷水遇到高温热油会形成“炸锅”，使油火到处飞溅，很容易造成火灾和人员伤亡；B项错误，保险丝的作用是为了让其在超过一定电流的情况下熔断，从而起到保护电路和电器的作用，它的材料必须熔点低、电阻大，这样才能在过载的情况下熔断，如果换成铁丝或铜丝，铁铜丝熔点相当高，可能电线皮烧着了但铁铜丝仍然不会断电，线中仍有电，电线温度会持续升高，后果不堪设想；C项正确，身上着火时，就地打滚或用厚重衣物覆盖压灭火苗是正确的做法；D项错误，煤气泄漏后遇明火会引发火灾甚至爆炸，应先关闭煤气，打开窗户通风。故正确答案为C。", "tag": "科技常识"},
{"id": "tech-406", "q": "2014 年央视“3 15”晚会曝光了部分小商品市场将激光笔作为儿童玩具进行销售一事。儿童使用激光笔不当，最容易造成的人身伤害是（）。", "options": ["辐射内脏，危害健康", "点燃衣服，烧伤身体", "影响食欲，阻碍发育", "损伤视力，甚至致盲"], "a": 3, "e": ".【D】市面上售卖的激光笔和激光手电，不少是属于3B级的，功率超过5mW，如果激光直射进眼睛可能会对眼睛造成伤害。一些高功率的激光笔，漫射光也可能对眼睛造成伤害，所以激光笔不是玩具，不适合儿童使用。在操作高功率激光时，应该戴上特殊的安全眼镜，特别是操作不可视的激光时。还有，不论是功率多大的激光也必须避免射到自己和其他人的眼睛里，激光器本身也应该加上警告标签。故正确答案为D。", "tag": "科技常识"},
{"id": "tech-407", "q": "下列标志与含义对应错误的一项是：", "options": ["食品安全标志", "循环再生标志", "强制认证标志", "环境保护标志"], "a": 3, "e": ".【D】D选项是绿色食品标志，环境保护标志如下图。其他的对应均正确。本题为选非题，故正确答案为D。", "tag": "科技常识"},
{"id": "tech-408", "q": "我国有悠久的酒文化历史，在长期的发展过程中，酿造出多种被誉为“神品”“琼浆”的酒类珍品。下列关于各类酒的作用说法错误的是：", "options": ["白酒有杀菌、去腥、防腐作用，可医用", "啤酒具有清心、提神的作用，可减少过度兴奋和紧张情绪", "红酒有助于防动脉硬化，还可减少骨质疏松症的危险", "黄酒有助于通经络、厚胃肠、养脾扶肝、增进食欲、消除疲劳"], "a": 2, "e": ".【C】A项正确，适量地饮用白酒可以振奋情绪、促进血液循环。白酒又有杀菌、去腥、防腐作用，有很长的医用历史；B项正确，啤酒是夏秋季防暑、降温、解渴、止汗的清凉饮料。据医学和食品专家们研究，啤酒含有4%的酒精，能促进血液循环；含二氧化碳，饮用时有清凉舒适感；还能帮助消化，促进食欲；C项错误，红酒中的多酸含量相当多，所以人们一直认为红酒对于预防心血管疾病有极好的作用，有助于预防动脉硬化和早老性痴呆症等疾病，但并不具有减少骨质疏松危险的功能；D项正确，黄酒味甘苦、性辛温、有小毒，主要作用是行药势、通经络、温脾胃、散湿气，热饮能活血、利小便。所以黄酒有助于通经络、厚胃肠、养脾扶肝、增进食欲、消除疲劳。本题为选非题，故正确答案为C。", "tag": "科技常识"},
{"id": "tech-409", "q": "雷雨过后空气会变得格外新鲜的原因是：", "options": ["空气中的成分没有任何变化，只是人的一种感觉", "空气中的灰尘被雨水冲走了", "空气中的部分氧气变成了臭氧", "雨水冲走了地面上的污物"], "a": 2, "e": ".【C】雷雨过后，闪电的瞬间高温将空气中的氧气经化学变化转变为了臭氧，而臭氧具有净化空气，杀死细菌的作用，人们感到空气特别清新是因为臭氧分子增多的原因，所以空气变得新鲜了。故正确答案为C。", "tag": "科技常识"},
{"id": "tech-410", "q": "小张打篮球不慎扭伤脚踝，脚踝肿胀但并未划破。如果小张脚踝扭伤在24 小时以内，以下哪种处理方法最合理：", "options": ["立即冷敷", "立即热敷", "立即用75%酒精消毒", "立即用碘酒擦洗"], "a": 0, "e": ".【A】冷敷可使毛细血管收缩，减轻局部充血，可使神经末梢的敏感性降低而减轻疼痛，降温退热，可减少局部血流，防止炎症和化脓扩散；可将体内的热传导发散，增加散热，降低体温。热敷可促进炎症的消退，在炎症的早期，热敷可促进炎症的吸收和消散；后期可使炎症局限，有助于坏死组织的消除和组织修复。热敷能使肌肉、肌腱和韧带等组织松弛，解除因肌肉痉挛、强直而引起的疼痛，如腰肌劳损、扭伤等。还可减轻深部组织充血，使局部血管扩张。受伤后肿胀未划破，正确做法应该是在伤后24小时之内先予冷敷。受伤24小时以后，那些断裂损伤的毛细血管基本发生凝血而不再继续出血，这时再改用热敷。故正确答案为A。", "tag": "科技常识"},
{"id": "tech-411", "q": "下列关于流行病的相关表述，错误的是：", "options": ["疟疾是一种感染人口众多，能在短时间内广泛蔓延的传染病", "艾滋病是由感染HIV 病毒引起，这是一种能攻击人体免疫系统的病毒", "埃博拉的致死率并不高，该病毒主要通过空气传播", "登革热主要通过蚊虫传播，是东南亚儿童死亡的重要原因之一"], "a": 2, "e": ".【C】C项错误：埃博拉是由丝状病毒科的埃博拉病毒导致的严重的致命性疾病，死亡率高达。接触传播是埃博拉病毒的主要传染途径，人们通过接触（通常在屠宰、烹饪或食用时接触）被感染的动物或被感染人的体液而遭到感染。多数病例是人际传播造成的。A项正确：疟疾是一种由寄生虫引起的威胁生命的疾病，通过受感染的雌蚊叮咬传至人类，能在短时间内广泛蔓延。根据世界卫生组织的报道，约32亿人（近全球人口的一半）面临疟疾风险。B项正确：艾滋病是一种危害性极大的传染病，由感染艾滋病病毒（HIV病毒）引起。HIV是一种能攻击人体免疫系统的病毒。D项正确：登革热是登革病毒经蚊媒传播引起的急性虫媒传染病，主要通过伊蚊叮咬传播，是东南亚地区儿童死亡的主要原因之一。本题为选非题，故正确答案为C。", "tag": "科技常识"},
{"id": "tech-412", "q": "下列与果树有关的说法正确的是：", "options": ["富含氮的肥料可促进果树开花结果", "杏树是耐旱能力比较弱的树种", "冬季不需要对果树进行病虫防治", "嫁接是一种常用的果树繁殖方式"], "a": 3, "e": ".【D】本题考查生物常识。A项错误，使用含氮的肥料能促进细胞的分裂和生长，使枝叶长得繁茂；含磷的肥料能促进幼苗的发育和花的开放，使果实、种子提早成熟，因此促进开花结果应使用富含磷的肥料，而非含氮的肥料。B项错误，杏树具有扎根较深，喜光、耐旱、抗寒、抗风的特点，其寿命可长达百年以上，在我国多在北方地区栽培。“耐旱能力较弱”的说法错误。C项错误，冬季是果树病虫潜伏越冬的时期。做好冬季病虫害防治工作，对减少病源菌及害虫的越冬基数，有效控制次年病虫害的发生十分重要，因此冬季也需要对果树进行病虫防治。D项正确，为了保持优良特性，加快繁殖速度，人们常用茎对一些植物进行繁殖，嫁接就是其中常用的一种。简单来说嫁接就是把一个植物体的芽或枝，接在另一个植物体上，使结合在一起的两部分长成为一个完整的植物体，常见的苹果、梨、桃等果树都是进行嫁接繁殖的，是一种常用的果树繁殖方式。故正确答案为D。", "tag": "科技常识"},
{"id": "tech-413", "q": "人们经常利用植物去判断生长地的环境，下列有关说法正确的是：", "options": ["矮牵牛含有的花青素对二氧化硫有指示作用", "树林中所有树冠西边稀疏东边繁盛，说明东风盛行", "胡杨的生长地土壤通常呈现深褐色", "地衣大量生长反映空气湿度较低​"], "a": 0, "e": ".【A】本题考查科技常识。A项正确，花青素的颜色因酸碱度不同而异，在酸性条件下呈红色，在碱性条件下为蓝色。随着一天从早晨到晚上空气中二氧化硫含量的增加，矮牵牛对二氧化硫吸收量也逐渐加大，花中的酸性不断提高，从而造成花色由蓝变红。B项错误，树木向风面的芽体由于受风的袭击而损坏，因此向风面枝条稀疏；而背风面的芽体则因受风的影响较小而存活较多。选项中树冠西边稀疏东边繁盛，说明风从西边吹来，即西风盛行。C项错误，胡杨主要分布于中国西北各地，喜沙质土壤，常于沙漠地区水源附近形成绿洲，故胡杨的生长地土壤通常呈现黄色。D项错误，地衣的生长一般喜爱高湿度、低温度及低光照强度。这些因素中湿度是其生长最重要的因素，因此地衣大量生长反映空气湿度较高。故正确答案为A。", "tag": "科技常识"},
{"id": "tech-414", "q": "在农业生产中若长期使用某种杀虫剂，会导致害虫的抗药性增强、杀虫效果减弱，其最主要原因是：", "options": ["害虫体内积累的杀虫剂增强了自身的抗药性", "杀虫剂造成害虫基因突变，产生了抗药性基因", "抗药性强的害虫所产生的后代一定具有很强的抗药性", "杀虫剂对害虫有选择作用，使抗药性强的害虫被保留下来"], "a": 3, "e": ".【D】A项错误：害虫体内积累的杀虫剂增加了害虫自身的耐药性，而非抗药性。B项错误：基因突变是本来就存在的，是不定向的，并不是由于用了杀虫剂产生了抗药性基因。C项错误：选项说法过于绝对，由于变异是不定向的，所产生的后代不一定都具有很强的抗药性。D项正确：当使用某种杀虫剂后，绝大多数害虫被杀死，少数具有抗药性的个体生存下来并繁殖；抗药性害虫大量繁殖后，再用该种杀虫剂，会有比以前更多的个体生存下来。因此，杀虫剂对害虫起到一个定向选择的作用。故正确答案为D。", "tag": "科技常识"},
{"id": "tech-415", "q": "关于农作物，下列对应错误的是：（）", "options": ["豆类、薯类——粮食作物", "花生、向日葵——经济作物", "西红柿、青梅——蔬菜作物", "玉米、紫云英——饲料作物"], "a": 2, "e": ".【C】粮食作物以水稻、豆类、薯类、青稞、蚕豆、小麦为主要作物，因此A项正确；经济作物以油籽、蔓青、大芥、花生、胡麻、大麻、向日葵等为主，因此B项正确；饲料作物如玉米、绿肥、紫云英等，在2015年中央1号文件着重指出：“支持青贮玉米和苜蓿等饲草料种植，开展粮改饲和种养结合模式试点”的战略决策。因此D项正确。蔬菜作物主要有萝卜、白菜、芹菜、韭菜、蒜、葱、胡萝卜、菜瓜、莲花菜、菊芋、刀豆、芫荽、莴笋、黄花、辣椒、黄瓜、西红柿、香菜等；果类有梨、青梅、苹果、桃、杏、核桃、李子、樱桃、草莓、沙果、红枣等品种。青梅属于果类作物，因此C项错误。本题为选非题，故本题正确答案选C。", "tag": "科技常识"},
{"id": "tech-416", "q": "关于生物，下列说法错误的是：", "options": ["酸菜和腐乳的制作过程中都离不开乳酸菌的发酵", "病毒只能寄生在活细胞中进行生命活动", "细菌有完整的能量代谢系统，可以独立地生长繁殖", "木耳是真菌的一种，常生长在阴湿、腐朽的树干上"], "a": 0, "e": ".【A】A项错误，制作酸菜过程要用到乳酸菌，在无氧的条件下，乳酸菌发酵产生乳酸，使得酸菜具有特殊的风味；而腐乳的主要生产工序分为前期发酵和后期发酵，前期发酵使得豆腐上开始生长毛霉，前期发酵的作用，一是使豆腐表面有一层菌膜包住；二是毛霉分泌以蛋白酶为主的各种酶，有利于豆腐所含有的蛋白质水解为各种氨基酸。后期发酵通过腌制并配入各种辅料，促进其他生化反应，生成腐乳的香气。故在腐乳的制作过程没有乳酸菌的参与。B项正确，病毒没有细胞结构，不能独立生活，它具有高度的寄生性，必须依赖宿主细胞的能量和代谢系统，获取生命活动所需的物质和能量。因此，病毒只能寄生在活细胞中进行生命活动。C项正确，细菌是一种具有细胞壁的单细胞微生物。细胞是生命活动的单位，一些生命活动的基本过程，如物质代谢、能量转换、运动、发育、繁殖和遗传等，都是以细胞为结构基础来实现的。能进行能量转换是因细胞具有完整的能量代谢系统。细菌作为细胞生物，因而具有完整的能量代谢系统。D项正确，木耳是担子菌纲木耳科木耳属植物。担子菌纲是真菌门的一个大纲，因而属于真核生物。真核生物是一类比较高等的微生物，有完整的细胞核，主要靠菌丝体分解吸收现成的营养物质。木耳寄生于阴湿、腐朽的树干上，单生或本题为选非题，故正确答案为A。", "tag": "科技常识"},
{"id": "tech-417", "q": "下列哪种疾病经过粪口途径传播？", "options": ["细菌性痢疾", "流行性脑炎", "乙型肝炎", "疟疾"], "a": 0, "e": ".【A】本题考查科技常识。A项正确，细菌性痢疾是一种肠道传染病，流行于夏秋季，主要表现为起病急、发热、腹痛、腹泻，严重者可能出现感染性休克和中毒性脑病。细菌性痢疾主要经过粪口途径传播，主要传染源为病人及带菌者。B项错误，流行性脑炎分为甲型脑炎和乙型脑炎，其中尤以乙型脑炎最为常见。流行性乙型脑炎的病原传染主要是通过蚊虫叮咬进行的。C项错误，乙型肝炎是由乙肝病毒引起的，以肝脏损害为主的一组全身性传染病，主要表现为疲乏、食欲减退、厌油、肝功能异常等。主要传染源为乙肝患者、病毒携带者。传播途径为母婴传播、血液及血制品传播、破损的皮肤和粘膜及性接触传播等。D项错误，疟疾是由疟原虫引起的传染病，主要表现为发抖、寒战、高热、乏力等，严重可危及生命。疟疾的主要传播媒介是按蚊，当按蚊叮咬人时，可将携带的疟原虫带入人体血液，引起疟疾的传播。故正确答案为A。", "tag": "科技常识"},
{"id": "tech-418", "q": "关于我国的油料作物，下列说法错误的是：", "options": ["芝麻喜凉，果实有黑、白之分，山东省产量最高", "花生喜温耐瘠，适宜种在排水良好的沙质土壤中", "大豆喜温，生长发育期间低温会延迟开花成熟", "油菜抗寒力较强，是我国分布最广的油料作物"], "a": 0, "e": ".【A】本题考查科技常识。A项错误，芝麻是我国主要油料作物之一，种子有黑白二种，具有较高的应用价值。芝麻喜温，在我国黄河及长江中下游各省均有种植，以河南、湖北、安徽、江西、河北等省分布较多，其中以河南省产量最高。B项正确，花生是一种喜温的豆科作物，适应性强，有较强的耐旱、耐瘠薄能力，种植花生对土壤要求不严,以排水良好的沙质土壤为最好。C项正确，大豆是喜温作物，在温暖的环境下生长良好。发育期间以最为适宜。大豆进入花芽分化期后，如果温度过低会使花芽分化受阻，使花期延迟。D项正确，油菜是喜冷凉、抗寒力较强的作物，主要分布在长江流域，是我国分布最广的油料作物。本题为选非题，故正确答案为A。", "tag": "科技常识"},
{"id": "tech-419", "q": "白居易有诗云：“绿蚁新醅酒，红泥小火炉。晚来天欲雪，能饮一杯无？”下列与该诗相关的说法正确的是：", "options": ["“绿蚁”是因为酒中添加了可食用调色剂", "“醅酒”的过程利用了微生物的作用", "炉火燃烧的过程是内能转化成化学能", "从雪到水的转化过程会释放出热量​"], "a": 1, "e": ".【B】本题考查科技常识。A项错误，由于酒是新近酿好的，未经过滤，酒面泛起酒渣泡沫，颜色微绿，细小如蚁，故称“绿蚁”。“绿蚁”并非是因为酒中添加了可食用调色剂。B项正确，“醅酒”是指酿造酒，是利用微生物发酵生产含一定浓度酒精饮料的过程。C项错误，内能是物质系统内部分子热运动的各种形式的动能以及分子间势能的总和。化学能是指参与化学反应的物质所具有的能量。炉火燃烧的过程是化学能转化成热能。D项错误，融雪的时候水由固体变为液体会吸收热量，使气温降低。故正确答案为B。", "tag": "科技常识"},
{"id": "tech-420", "q": "某人扁桃体化脓，医生建议其静脉注射头孢，药液从其手背静脉到达扁桃体患处所经过的途径是：上肢静脉→右心房→①→②→左心房→③→④→动脉→扁桃体毛细血管（患处）。依次填入①②③④正确的是：", "options": ["肺循环；右心室；左心室；主动脉", "左心室；肺循环；主动脉；右心室", "主动脉；右心室；左心室；肺循环", "右心室；肺循环；左心室；主动脉"], "a": 3, "e": ".【D】本题考查生物常识。人体内血液循环分为两大部分，体循环和肺循环。体循环是指血液由左心室进入主动脉，再流经全身的各级动脉、毛细血管网，各级静脉，最后汇集到上、下腔静脉，流回右心房的循环途径。肺循环是指血液由右心室进入肺动脉，流经肺部的毛细血管网，再由肺静脉流入左心房的循环途径。体循环和肺循环同时进行，并且在心脏处汇合在一起，组成一条完整的循环途径。本题中药物从上肢静脉随血液流入，进入右心房，然后到右心室，经过肺循环进入左心房，再到左心室进入体循环，经过主动脉，各级动脉，最后到达扁桃体毛细血管（患处）。具体途径见下图：故正确答案为D。", "tag": "科技常识"},
{"id": "tech-421", "q": "关于袋鼠，下列描述不正确的是：", "options": ["哺乳动物中跳得最远", "在澳大利亚广泛分布", "是草食性动物", "有胎盘"], "a": 3, "e": ".【D】本题考查生物常识。A项正确，袋鼠以跳代跑，最高可跳到4米，最远可跳至13米，是跳得最高最远的哺乳动物。B项正确，袋鼠主要分布在澳洲和南北美洲的草原上和丛林中。大多数袋鼠都是澳大利亚的特产。C项正确，袋鼠是食草动物，以矮小润绿离地面近的小草为生，个别种类的袋鼠也吃树叶或小树芽。D项错误，袋鼠是比较原始的哺乳动物，它虽已胎生，但它还没有胎盘，不能像有胎盘哺乳动物那样，生出发育完全的幼仔，而只能产出个“早产儿”，再在体外“育儿袋”里继续发育，直至成熟。故袋鼠没有胎盘。本题为选非题，故正确答案为D。", "tag": "科技常识"},
{"id": "tech-422", "q": "2019 年，亚马逊雨林和澳大利亚东部丛林分别发生了严重的山火，对生态环境造成多方面影响。下列影响属于不可逆的是：", "options": ["植物燃烧留下的有毒物质", "生物遗传多样性的丧失", "森林植被的破坏"], "a": 2, "e": ".【C】本题考查科技常识。根据对生态环境所造成影响程度的大小可以分为三种类型：一是不可逆转的影响，二是负面作用较大的影响，三是负面作用较小的影响。A、D项错误，对于生物数量降低、森林植被的破坏，都是生物数量的减少，经过一段时间的生物繁殖可以得到恢复，不是不可逆的，属于负面作用较大的影响。B项错误，对于植物燃烧留下的有毒物质，可以采取措施控制它的危害，且经过一段时间后有毒物质也会自然降解，不是不可逆的，属于负面作用较大的影响。C项正确，亚马逊雨林和澳大利亚山火使大面积的森林被焚烧，超十亿野生动物因此丧生，有些物种很可能因此灭绝，造成生物种类多样性和遗传多样性的丧失，且丧失的物种和遗传特性是无法完全恢复的，属于不可逆的影响。故正确答案为C。", "tag": "科技常识"},
{"id": "tech-423", "q": "下列关于蛋白质的说法错误的是：", "options": ["蛋白质是鸟类羽毛的构成成分", "蛋白质缺乏会导致儿童发育迟缓", "蛋白质摄入过量会在人体内转化为脂肪", "植物蛋白比动物蛋白更易被人类消化吸收"], "a": 3, "e": ".【D】本题考查生物常识。A项正确，鸟类羽毛的主要成分是角蛋白，除此以外还有人体的头发，动物的鳞甲等主要成分也与之类似。B项正确，蛋白质的缺乏常见症状是代谢率下降，对疾病抵抗力减退，易患病，远期效果是器官的损害，常见的是儿童的生长发育迟缓、营养不良、体质下降、淡漠、易激怒，并因为易感染而继发疾病。C项正确，摄入必要的蛋白质对人体健康十分重要，但是如果摄取过量的话也会在体内转化成脂肪，造成脂肪堆积，加重肾脏负担。D项错误，相比之下，动物蛋白更容易被人类消化吸收，主要是由于动物蛋白相对于人类的营养结构比较吻合，其蛋白质的种类和结构更加接近人体的蛋白结构和数量。故植物蛋白比动物蛋白更易被人类消化吸收的说法错误。本题为选非题，故正确答案为D。", "tag": "科技常识"},
{"id": "tech-424", "q": "下列诗词没有描述生物应激性反应的是：", "options": ["明月别枝惊鹊，清风半夜鸣蝉", "我有迷魂招不得，一唱雄鸡天下白", "人间四月芳菲尽，山寺桃花始盛开", "飞蛾性趋炎，见火不见我，愤然自投掷"], "a": 2, "e": ".【C】本题考查科技常识。应激性是指一切生物对外界各种刺激（如光、温度、声音、食物、化学物质、机械运动、地心引力等）所发生的反应。应激性是一种动态反应，是细胞对刺激发生反应的特性。A项正确，“明月别枝惊鹊，清风半夜鸣蝉”出自辛弃疾的《西江月夜行黄沙道中》，意为天边的明月升上了树梢，惊飞了栖息在枝头的喜鹊，清凉的晚风仿佛传来了远处的蝉叫声。喜鹊被惊飞，体现了生物应激性反应。B项正确，“我有迷魂招不得，一唱雄鸡天下白”出自李贺的《致酒行》，意为我的魂魄好像迷失在外，招不回来；当长夜过去，雄鸡高唱，天下大白的时候，才会有我的出路。公鸡对光线特别敏感，当天刚刚发亮时，就能感受到光而报晓，体现了生物应激性反应。C项错误，“人间四月芳菲尽，山寺桃花始盛开”出自白居易的《大林寺桃花》，意为人间四月里百花凋零已尽，可是山寺之中，桃花却刚刚盛开。由于地势高的原因，山中的温度一般比平原的温度要低，所以山中的植物达到有效积温所需时间就长，发育就慢。其没有描述生物应激性反应。D项正确，“飞蛾性趋炎，见火不见我，愤然自投掷”出自秦应阳的《飞蛾》，意为飞蛾的本性惯于趋向炎热，只见到火而见不到自己，像愤然投掷一样。飞蛾夜间活动，具有趋光性，属于生物应激性反应。本题为选非题，故正确答案为C。", "tag": "科技常识"},
{"id": "tech-425", "q": "下列关于生活中常见农产品的说法错误的是：", "options": ["西瓜又名夏瓜、寒瓜，含水量一般可达", "马铃薯的块茎富含淀粉，可供食用，是一种粮食作物", "香菇是一种常见的食用菌，不属于植物，但属于蔬菜", "胡萝卜属于十字花科萝卜属，在10 世纪被引入中国"], "a": 3, "e": ".【D】本题考查科技常识。A项正确，西瓜又名夏瓜、寒瓜，属一年生蔓生藤本。西瓜的含水量高达以上，是最“富水”的水果之一。西瓜中所含的瓜氨酸、精氨酸成分，能够帮助尿素形成，有利尿的作用，而排尿能够带走体内的一部分热量，故而西瓜有消暑作用。B项正确，马铃薯俗称土豆，属茄科一年生草本，块茎富含淀粉，可供食用。马铃薯与小麦、稻谷、玉米、高粱并称为世界五大粮食作物。C项正确，香菇是一种常见的食用菌，在生物分类中属于真菌，非植物，是一种常见的蔬菜。D项错误，胡萝卜是伞形科胡萝卜属的一员，一年生或二年生草本。胡萝卜原产于亚洲的西南部，阿富汗为最早演化中心，于公元10世纪从伊朗引入欧洲大陆，约在13世纪从伊朗引入中国，发展成中国生态型。本题为选非题，故正确答案为D。", "tag": "科技常识"},
{"id": "tech-426", "q": "“杂交水稻之父”袁隆平培育出高产的杂交水稻新品种，是利用了：", "options": ["基因的多样性", "染色体的多样性", "细胞的多样性", "DNA 的多样性"], "a": 0, "e": ".【A】选用两个在遗传上有一定差异，同时它们的优良性状又能互补的水稻品种，利用了人工培育水稻与野生稻之间基因差异，进行杂交，生产具有杂种优势的第一代杂交种，用于生产，这就是杂交水稻。故正确答案为A。", "tag": "科技常识"}
);
